window.HB_TR["leviticus"]["ur"]=["1۔ اور خداوند نے موسیٰ کو بلایا اور جماعت کے خیمہ سے اس سے کہا،\n2۔ بنی اسرائیل سے بات کرو، اور انہیں کہو، اگر تم میں سے کوئی خداوند کے لیے نذرانہ پیش کرے گا، تو تم اپنی مویشیوں کی نذرانہ پیش کرو گے، یہاں تک کہ ریوڑ اور ریوڑ کی بھی۔\n3۔ اگر اس کی قربانی ریوڑ کی جلی ہوئی قربانی ہے، تو وہ بغیر کسی بے داغ نر کو پیش کرے: وہ اپنی مرضی سے جماعت کے خیمہ کے دروازے پر خداوند کے سامنے پیش کرے گا۔\n4۔ اور وہ اپنا ہاتھ جلنے والے قربانی کے سر پر رکھے گا؛ اور یہ قبول کیا جائے گا کہ وہ اس کے لیے کفارہ کرے۔\n5۔ اور وہ خداوند کے سامنے بیل کو مارے گا: اور کاہن، ہارون کے بیٹے، خون لائیں گے اور خون کو اس قربان گاہ پر چھڑکیں گے جو جماعت کے خیمہ کے دروازے کے پاس ہے۔\n6۔ اور وہ سلائی کی قربانی کو اتار کر اپنے ٹکڑوں میں کاٹ دے گا۔\n7۔ اور ہارون کاهن کے بیٹے قربان گاہ پر آگ لگائیں گے، اور لکڑی کو آگ پر ترتیب دیں گے:\n8۔ اور کاہن، ہارون کے بیٹے، اس کے حصے، سر اور چربی کو اس لکڑی پر ترتیب سے رکھیں گے جو {ہے} آگ پر جو {ہے} قربان گاہ پر:\n9۔ لیکن اس کے اندر اور ٹانگیں پانی میں دھوئے گا: اور پادری قربان گاہ پر سب کچھ جلا دے گا، {تاکہ وہ جلی ہوئی قربانی} ہو، آگ سے دی گئی نذرانہ ہو، خدا کے لیے میٹھا ذائقہ ہو۔\n10۔ اور اگر اس کی قربانی ریوڑوں کی ہو، یعنی بھیڑ یا بکریوں کی، جلانے والی قربانی کے لیے؛ وہ اسے ایک بے داغ نر لائے گا۔\n11۔ اور وہ اسے قربان گاہ کے کنارے شمال کی طرف خداوند کے سامنے مارے گا: اور کاہن، ہارون کے بیٹے، اس کا خون قربان گاہ پر چھڑکیں گے۔\n12۔ اور وہ اسے اپنے سر اور چربی سے ٹکڑوں میں کاٹے گا: اور پادری انہیں اس لکڑی پر ترتیب سے رکھے گا جو {ہے} آگ پر جو {ہے} قربان گاہ پر:\n13۔ لیکن وہ اندر اور ٹانگیں پانی سے دھوئے گا: اور پادری سب کچھ لے کر قربان گاہ پر جلائے گا: یہ ایک جلتی ہوئی قربانی ہے، آگ سے دی گئی نذران، خدا کے لیے ایک میٹھا ذائقہ ہے۔\n14. اور اگر اس کی قربانی کے لیے جلائی گئی قربانی پرندوں کی ہو، تو وہ کبوتر یا نوجوان کبوتروں کی نذرانہ پیش کرے گا۔\n15۔ اور پادری اسے قربان گاہ پر لے جائے گا، اپنا سر نچوڑے گا، اور اسے قربان گاہ پر جلا دے گا؛ اور اس کا خون قربان گاہ کے کنارے سے نچوڑا جائے گا: {نچوڑنا...: یا، سر کو کیل سے کاٹ دو}\n16۔ اور وہ اپنی فصل کو اپنے پروں سے توڑے گا، اور اسے مشرقی حصے میں قربان گاہ کے پاس، راکھ کی جگہ پر پھینک دے گا: {اس کے پر: یا اس کی گندگی}\n17۔ اور وہ اسے اس کے پروں سے کاٹ دے گا، {لیکن} اسے جدا نہیں کرے گا: اور پادری اسے قربان گاہ پر، اس لکڑی پر جلا دے گا جو {ہے} آگ پر: یہ ایک جلی ہوئی قربانی ہے، آگ کی طرف سے دی گئی قربانی، خداوند کے لیے ایک میٹھا ذائقہ ہے۔","1۔ اور جب کوئی خداوند کے لیے گوشت کی قربانی پیش کرے گا، تو اس کی قربانی عمدہ آٹے کی ہوگی؛ اور وہ اس پر تیل ڈالے گا، اور لوبان لگائے گا:\n2۔ اور وہ اسے ہارون کے کاہن کے بیٹوں کے پاس لے آئے گا، اور اس کے آٹے اور اس کے تیل کا مٹھی اس کے تمام لوبان کے ساتھ لے جائے گا؛ اور پادری اس کی یادگار کو قربان گاہ پر جلائے گا، {تاکہ وہ آگ سے دی گئی نذرانہ ہو، خداوند کے لیے میٹھا ذائقہ ہو:\n3۔ اور گوشت کی قربانی کا باقیات ہارون اور اس کے بیٹوں کی ہوگی: یہ خداوند کی آگ سے دی گئی نذرانے میں سب سے مقدس چیز ہے۔\n4۔ اور اگر تم تندور میں بکی ہوئی گوشت کی قربانی لاؤ، تو وہ بغیر خمیر کے کیک ہوں جن میں عمدہ آٹے کا تیل ملا ہو، یا بغیر خمیر کے ویفرز جو تیل سے مسح کیے گئے ہوں۔\n5۔ اور اگر آپ کی قربانی ایک گوشت کی قربانی ہے جو پین میں بکی ہو، تو وہ باریک آٹے کی ہوگی جس میں خمیر نہیں ہوتا، تیل کے ساتھ ملا کر۔ {پین میں: یا، فلیٹ پلیٹ پر، یا، کاٹیں}\n6۔ تم اسے ٹکڑوں میں تقسیم کرو اور اس پر تیل ڈالو: یہ گوشت کی قربانی ہے۔\n7۔ اور اگر آپ کی قربانی گوشت کی قربانی ہو جو فرائنگ پین میں بیک کی گئی ہو، تو وہ باریک آٹے سے تیل کے ساتھ بنائی جائے گی۔\n8۔ اور تم ان اشیاء سے بنائی گئی گوشت کی قربانی خداوند کے سامنے لاؤ گے، اور جب یہ پادری کے سامنے پیش کی جائے گی، تو وہ اسے قربان گاہ پر لے آئے گا۔\n9۔ اور پادری گوشت کی قربانی سے اس کی یادگار لے کر قربان گاہ پر جلائے گا: یہ آگ سے دی گئی نذرانہ ہے، خداوند کے لیے ایک میٹھا ذائقہ۔\n10۔ اور گوشت کی قربانی میں سے جو کچھ بچا ہے وہ ہارون اور اس کے بیٹوں کا ہوگا: یہ خداوند کی آگ سے دی گئی نذرانے میں سب سے مقدس چیز ہے۔\n11۔ کوئی گوشت کی نذرانہ جو تم خداوند کے سامنے لاؤ گے، خمیر سے نہیں دی جائے گی، کیونکہ تم خدا کی آگ کی پیشکش میں خمیر یا شہد نہیں جلاؤ گے۔\n12۔ جہاں تک پہلے پھلوں کی قربانی کا تعلق ہے، تم انہیں خداوند کے سامنے پیش کرو، لیکن انہیں میٹھے ذائقے کے لیے قربان گاہ پر نہیں جلایا جائے گا۔ {بی برنٹ: عبرانی۔ عروج\n13۔ اور اپنے گوشت کی نذرانہ میں ہر قربانی نمک سے مصالحہ دار کرنا؛ نہ تو اپنے خدا کے عہد کا نمک اپنے گوشت کی قربانی سے کم ہونے دینا چاہیے: اپنی تمام نذرانوں کے ساتھ نمک پیش کرو۔\n14۔ اور اگر تم اپنے پہلے پھلوں کی گوشت کی قربانی خداوند کے سامنے پیش کرو، تو اپنے پہلے پھلوں کے گوشت کی قربانی کے بدلے آگ میں خشک کیے ہوئے سبز مکئی کے کان، {حتیٰ کہ} بھرے ہوئے کانوں سے کٹے ہوئے مکئی پیش کرو۔\n15۔ اور تم اس پر تیل لگاؤ گے، اور اس پر لوبان رکھو: یہ گوشت کی قربانی ہے۔\n16۔ اور پادری اس کی یادگار کو جلا دے گا، اس کے پھٹے ہوئے اناج کا {حصہ}، اور اس کے تیل کا {حصہ}، اس کے تمام لوبان کے ساتھ: {یہ} آگ سے خداوند کے لیے پیش کی جانے والی نذرانہ ہے۔","1۔ اور اگر اس کی قربانی صلح کی قربانی ہو، اگر وہ ریوڑ کی قربانی پیش کرے؛ چاہے وہ مرد ہو یا عورت، وہ اسے خداوند کے سامنے بغیر کسی داغ کے پیش کرے گا۔\n2۔ اور وہ اپنی قربانی کے سر پر ہاتھ رکھے گا، اور اسے جماعت کے خیمے کے دروازے پر مار ڈالے گا: اور ہارون کے بیٹے، کاہن، ارد گرد قربان گاہ پر خون چھڑکیں گے۔\n3۔ اور وہ صلح کی قربانی میں سے آگ سے خدا کو دی گئی نذرانہ پیش کرے گا؛ وہ چربی جو اندر کی طرف کو ڈھانپتی ہے، اور وہ تمام چربی جو {ہے} اندرونی حصے پر، {چربی: یا، سوئیٹ}\n4۔ اور دونوں گردے، اور ان پر جو چربی ہے، جو پہلوؤں سے ہے، اور جگر کے اوپر، گردوں کے ساتھ، وہ اسے لے جائے گا۔ {کال...: یا، جگر کے اوپر اور گردوں کے اوپر}\n5۔ اور ہارون کے بیٹے اسے قربان گاہ پر جلائیں گے، جو اس لکڑی پر ہے جو آگ پر ہے: یہ آگ کی طرف سے پیش کی جانے والی نذرانہ ہے، خداوند کے لیے میٹھا ذائقہ۔\n6۔ اور اگر اس کی قربانی صلح کی قربانی کے طور پر خداوند کو ریوڑ میں سے ہو؛ مرد ہو یا عورت، وہ اسے بغیر کسی داغ کے پیش کرے گا۔\n7۔ اگر وہ اپنی قربانی کے لیے بکرا پیش کرے تو اسے خداوند کے سامنے پیش کرے گا۔\n8۔ اور وہ اپنی قربانی کے سر پر ہاتھ رکھے گا، اور اسے جماعت کے خیمے کے سامنے قتل کرے گا: اور ہارون کے بیٹے اس کا خون قربان گاہ پر چھڑکیں گے۔\n9۔ اور وہ صلح کی قربانی میں سے آگ سے خداوند کو پیش کرے گا؛ اس کی چربی {اور} پورا پچھواڑے کو، وہ سختی سے ریڑھ کی ہڈی سے اتار دے گا؛ اور وہ چربی جو اندر کی طرف ڈھانپتی ہے، اور وہ تمام چربی جو اندر کی طرف ہے،\n10۔ اور دونوں گردے، اور ان پر جو چربی ہے، جو پہلوؤں سے ہے، اور جگر کے اوپر، گردوں کے ساتھ، وہ اسے لے جائے گا۔\n11۔ اور پادری اسے قربان گاہ پر جلائے گا: یہ خدا کے لیے آگ سے پیش کی گئی قربانی کا کھانا ہے۔\n12۔ اور اگر اس کی قربانی بکری ہو، تو وہ اسے خداوند کے سامنے پیش کرے گا۔\n13۔ اور وہ اس کے سر پر ہاتھ رکھے گا، اور جماعت کے خیمے کے سامنے اسے قتل کرے گا: اور ہارون کے بیٹے اس کا خون ارد گرد قربان گاہ پر چھڑکیں گے۔\n14۔ اور وہ اس میں سے اپنی نذرانہ پیش کرے گا، {حتیٰ کہ} وہ نذرانہ جو آگ سے خداوند کو دی گئی ہو؛ وہ چربی جو اندر کی طرف ڈھانپتی ہے، اور وہ تمام چربی جو اندر کی طرف ہے،\n15۔ اور دو گردے، اور ان پر جو چربی ہے، جو پہلو سے ہے، اور جگر کے اوپر، گردوں کے ساتھ، اسے لے جائے گا۔\n16۔ اور پادری انہیں قربان گاہ پر جلائے گا: یہ آگ سے پیش کی گئی نذرانہ کا کھانا ہے جو میٹھے ذائقے کے لیے ہے: سارا چربی خداوند کی ہے۔\n17. {یہ تمہاری نسلوں کے لیے تمہارے تمام گھروں میں ایک دائمی قانون ہوگا کہ تم نہ چربی کھاؤ نہ خون۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل سے کہیں، کہو، اگر کوئی شخص لاعلمی میں خداوند کے کسی بھی حکم کے خلاف گناہ کرے {ان چیزوں کے بارے میں} جو نہیں ہونی چاہئیں، اور ان میں سے کسی کے خلاف کرے گا:\n3۔ اگر مسح شدہ پادری لوگوں کے گناہ کے مطابق گناہ کرے؛ پھر وہ اپنے گناہ کے بدلے جو اس نے گناہ کیا ہے، خداوند کے سامنے گناہ کی قربانی کے لیے ایک بے داغ نوجوان بیل لے آئے۔\n4۔ اور وہ بیل کو جماعت کے خیمہ کے دروازے تک لے جائے گا، خدا کے سامنے؛ اور بیل کے سر پر ہاتھ رکھے گا، اور اسے خداوند کے سامنے مار دے گا۔\n5۔ اور مسح شدہ پادری بیل کے خون سے لے کر جماعت کے خیمے میں لے جائے گا:\n6۔ اور پادری اپنی انگلی خون میں ڈالے گا، اور خدا کے سامنے، مقدس مقام کے پردے کے سامنے، سات بار خون چھڑکائے گا۔\n7۔ اور پادری میٹھی لوبان کی قربان گاہ کے سینگوں پر خون کا کچھ حصہ رکھے گا، جو خدا کے سامنے ہے، جو جماعت کے خیمے میں ہے؛ اور بیل کا سارا خون جلنے والے قربانی کے قربان گاہ کے نیچے ڈالے گا، جو جماعت کے خیمہ کے دروازے پر ہے۔\n8۔ اور وہ گناہ کی قربانی کے لیے بیل کی ساری چربی اتار دے گا؛ وہ چربی جو اندر کی طرف ڈھانپتی ہے، اور وہ تمام چربی جو اندر کی طرف ہے،\n9۔ اور دو گردے، اور ان پر جو چربی ہے، جو پہلو سے ہے، اور جگر کے اوپر، گردوں کے ساتھ، اسے لے جائے گا،\n10۔ جیسا کہ یہ امن کی قربانی کے بیل سے اتارا گیا: اور پادری انہیں جلانے والی قربانی کے مذبح پر جلائے گا۔\n11۔ اور بیل کی کھال، اور اس کا سارا گوشت، اس کا سر، اس کے پیر، اندرونی حصہ اور اس کا گوبر،\n12۔ پورا بیل بھی بغیر کیمپ کے ایک صاف جگہ لے جائے گا، جہاں راکھ نکالی جائے گی، اور اسے لکڑی پر آگ سے جلا دے گا: جہاں راکھ نکالی جائے گی، اسے جلا دیا جائے گا۔ {بغیر...: عبرانی۔ بغیر کیمپ کے} {کہاں...: عبرانی۔ راکھ کے بہنے پر}\n13۔ اور اگر اسرائیل کی پوری جماعت جہالت میں گناہ کرتی ہے، اور یہ معاملہ جماعت کی نظروں سے چھپا دیا جائے، اور انہوں نے خداوند کے کسی بھی حکم کے خلاف [کچھ خلاف} کیا ہے جو نہیں کی جانی چاہئیں، اور وہ قصوروار ہیں؛\n14۔ جب وہ گناہ معلوم ہو جائے جو انہوں نے اس کے خلاف کیا ہے، تو جماعت گناہ کے لیے ایک نوجوان بیل پیش کرے گی اور اسے جماعت کے خیمہ گاہ کے سامنے لے آئے گی۔\n15۔ اور جماعت کے بزرگ خداوند کے سامنے بیل کے سر پر ہاتھ رکھیں گے: اور بیل کو خداوند کے سامنے ذبح کیا جائے گا۔\n16۔ اور جو پادری مسح کیا جائے گا، وہ بیل کے خون کو جماعت کے خیمے میں لے جائے گا:\n17۔ اور پادری اپنی انگلی خون کے کچھ حصے میں ڈالے گا، اور خدا کے سامنے سات بار خون چھڑکائے گا، چادر کے سامنے بھی۔\n18۔ اور وہ خون کا کچھ حصہ قربان گاہ کے سینگوں پر رکھے گا جو {ہے} خداوند کے سامنے، یعنی جماعت کے خیمے میں، اور تمام خون کو سجلنے والے قربان گاہ کے نیچے بہائے گا، جو جماعت کے خیمہ کے دروازے پر ہے۔\n19۔ اور وہ اس کی ساری چربی اس سے لے کر قربان گاہ پر جلائے گا۔\n20۔ اور وہ بیل کے ساتھ ویسا ہی کرے گا جیسے اس نے بیل کے ساتھ گناہ کی قربانی کے طور پر کیا، اسی طرح وہ اس کے ساتھ کرے گا: اور پادری ان کے لیے کفارہ کرے گا، اور اسے معاف کر دیا جائے گا۔\n21۔ اور وہ بیل کو بغیر قید کے لے جائے گا، اور اسے اسی طرح جلا دے گا جیسے اس نے پہلا بیل جلایا تھا: یہ جماعت کے لیے گناہ کی قربانی ہے۔\n22۔ جب کسی حکمران نے گناہ کیا ہو، اور لاعلمی کی وجہ سے {کچھ حد تک} خداوند اپنے خدا کے کسی بھی حکم کے خلاف {جو نہیں ہونی چاہئیں} کے بارے میں کیا ہو اور وہ قصوروار ہو؛\n23۔ یا اگر اس کا گناہ، جس میں اس نے گناہ کیا ہے، اس کے علم میں آ جائے؛ وہ اپنی قربانی لائے گا، بکری کا بچہ، ایک بے داغ نر جو بے داغ ہو:\n24۔ اور وہ اپنا ہاتھ بکری کے سر پر رکھے گا، اور اسے اس جگہ مارے گا جہاں وہ خداوند کے سامنے جلنے والی قربانی کو مارتے ہیں: یہ گناہ کی قربانی ہے۔\n25۔ اور پادری گناہ کی قربانی کے خون میں سے اپنی انگلی سے لے گا، اور اسے جلنے والے قربان گاہ کے سینگوں پر رکھے گا، اور اپنا خون سجلنے کی قربان گاہ کے نیچے بہائے گا۔\n26۔ اور وہ اپنی ساری چربی قربان گاہ پر جلائے، جیسے کہ صلح کی قربانیوں کی چکنائی کی طرح: اور پادری اس کے گناہ کی کفارہ کرے گا، اور اسے معاف کر دیا جائے گا۔\n27۔ اور اگر عام لوگوں میں سے کوئی لاعلمی میں گناہ کرتا ہے، جبکہ وہ خداوند کے ان احکامات میں سے کسی کے خلاف ہے جو نہیں کرنی چاہئیں، اور وہ قصوروار ہے؛ {کوئی بھی: عبرانی۔ کوئی بھی روح} {عام...: عبرانی۔ زمین کے لوگ}\n28۔ یا اگر اس کا گناہ جو اس نے کیا ہے، اس کے علم میں آ جائے، تو وہ اپنی قربانی لے کر آئے گا، جو بکری کا بچہ ہے، ایک بے داغ مادہ، اپنے گناہ کے لیے جو اس نے گناہ کیا ہے۔\n29۔ اور وہ گناہ کی قربانی کے سر پر ہاتھ رکھے گا، اور جلنے والی قربانی کی جگہ گناہ کی قربانی کو قتل کرے گا۔\n30۔ اور پادری اس کے خون سے اپنی انگلی سے لے کر جلنے والے قربان گاہ کے سینگوں پر رکھے گا، اور اس کا سارا خون قربان گاہ کے نیچے بہائے گا۔\n31۔ اور وہ اس کی ساری چربی نکال دے گا، جیسے صلح کی قربانیوں سے چربی نکالی جاتی ہے؛ اور پادری اسے قربان گاہ پر جلائے گا تاکہ خداوند کے لیے میٹھا ذائقہ ہو؛ اور پادری اس کے لیے کفارہ کرے گا، اور اسے معاف کر دیا جائے گا۔\n32۔ اور اگر وہ گناہ کی قربانی کے طور پر بھیڑ لے آئے تو اسے بے داغ مادہ لائے گا۔\n33۔ اور وہ گناہ کی قربانی کے سر پر ہاتھ رکھے گا، اور اسے گناہ کی قربانی کے طور پر اس جگہ قتل کرے گا جہاں وہ جلنے والی قربانی کو مارے جاتے ہیں۔\n34۔ اور پادری گناہ کی قربانی کے خون سے اپنی انگلی سے لے کر جلنے والے قربان گاہ کے سینگوں پر رکھے گا، اور اس کا سارا خون قربان گاہ کے نیچے بہائے گا:\n35۔ اور وہ اس کی ساری چربی لے لے گا، جیسے میمنے کی چربی صلح کی قربانیوں کی قربانی سے نکالی جاتی ہے؛ اور پادری انہیں قربان گاہ پر جلا دے گا، جیسا کہ خداوند کو آگ سے دی گئی نذرانے کے مطابق ہے: اور پادری اپنے کیے گئے گناہ کا کفارہ دے گا، اور اسے معاف کر دیا جائے گا۔","1۔ اور اگر کوئی شخص گناہ کرے، اور قسم کھانے کی آواز سنے، اور گواہ ہو، چاہے اس نے دیکھا ہو یا جانتا ہو؛ اگر وہ یہ نہ کہے تو وہ اپنی غلطی برداشت کرے گا۔\n2۔ یا اگر کوئی شخص کسی ناپاک چیز کو چھوئے، چاہے وہ ناپاک جانور کی لاش ہو، یا ناپاک مویشیوں کی لاش، یا ناپاک رینگنے والی چیزوں کی لاش، اور اگر وہ اس سے چھپا دی جائے؛ وہ بھی ناپاک اور مجرم ہوگا۔\n3۔ یا اگر وہ انسان کی ناپاکی کو چھوئے، جو بھی ناپاکی ہو، انسان کو اس سے ناپاک کر دیا جائے اور وہ اس سے چھپا دیا جائے؛ جب وہ جان لے گا، تب وہ قصوروار ہوگا۔\n4۔ یا اگر کوئی شخص اپنے ہونٹوں سے قسم کھائے کہ وہ برائی یا بھلائی کرے گا، جو بھی ہو، کہ کوئی شخص قسم کھائے گا اور اسے اس سے چھپا دیا جائے گا؛ جب وہ جان لے گا، تو وہ ان میں سے کسی ایک میں قصوروار ہوگا۔\n5۔ اور جب وہ ان {چیزوں} میں سے کسی میں قصوروار ہوگا، تو وہ اعتراف کرے گا کہ اس نے اس {چیز} میں گناہ کیا ہے:\n6۔ اور وہ اپنے گناہ کے بدلے خداوند کو گناہ کی قربانی دے گا، جو اس نے گناہ کیا ہے، ریوڑ کی ایک مادہ، ایک بکری یا بکریوں کا بچہ، گناہ کی قربانی کے بدلے؛ اور پادری اس کے گناہ کے بارے میں اس کا کفارہ کرے گا۔\n7۔ اور اگر وہ بکری لا نہ سکے، تو وہ اپنی غلطی کے بدلے، جو اس نے کیا ہے، دو کچھوے یا دو نوجوان کبوتر خداوند کے پاس لے آئے؛ ایک گناہ کی قربانی کے لیے، اور دوسرا جلتی ہوئی قربانی کے لیے۔ {وہ...: عبرانی۔ اس کا ہاتھ بھیڑ کے جتنا کافی نہیں پہنچ سکتا}\n8۔ اور وہ انہیں پادری کے پاس لے جائے گا، جو پہلے گناہ کی قربانی کے لیے پیش کرے گا، اور اس کا سر اس کی گردن سے نچوڑے گا، لیکن اسے الگ نہیں کرے گا:\n9۔ اور وہ گناہ کی قربانی کا خون قربان گاہ کے کنارے پر چھڑکائے گا؛ اور باقی خون قربان گاہ کے نیچے نچوڑا جائے گا: یہ گناہ کی قربانی ہے۔\n10۔ اور وہ دوسرا جلنے کی قربانی پیش کرے گا، طریقہ کے مطابق: اور پادری اس کے گناہ کا کفارہ دے گا جو اس نے گناہ کیا ہے، اور اسے معاف کر دیا جائے گا۔ {طریقہ: یا، آرڈیننس}\n11۔ لیکن اگر وہ دو کبوتر یا دو نوجوان کبوتر لانے کے قابل نہ ہو، تو گناہ گار کو اپنی قربانی کے بدلے عمدہ آٹے کا دسواں حصہ گناہ کی قربانی کے طور پر لائے گا؛ وہ اس پر تیل نہیں لگائے گا، نہ ہی اس پر لوبان لگائے گا: کیونکہ یہ گناہ کی قربانی ہے۔\n12۔ پھر وہ اسے پادری کے پاس لے آئے گا، اور پادری اس کا مٹھی بھر لے گا، {حتیٰ کہ} اس کی یادگار بھی، اور اسے قربان گاہ پر جلا دے گا، جیسا کہ خداوند کو آگ سے دی گئی نذرانے کے مطابق ہے: یہ گناہ کی قربانی ہے۔\n13۔ اور پادری اس کے لیے کفارہ کرے گا کیونکہ اس نے ان گناہوں میں سے کسی ایک میں گناہ کیا ہے، اور اسے معاف کر دیا جائے گا: اور باقی ماندہ حصہ پادری کا ہوگا، گوشت کی قربانی کے طور پر۔\n14۔ اور خداوند نے موسیٰ سے کہا،\n15۔ اگر کوئی شخص خداوند کی مقدس چیزوں میں لاعلمی سے گناہ کرے؛ پھر وہ اپنے گناہ کے بدلے خداوند کے سامنے ایک بے داغ مینڈھا لائے گا، جو تمہارے اندازے کے مطابق چاندی کے شیکل سے ہوگا، مقدس مقام کی شیکل کے بعد، ایک ناجائز قربانی کے طور پر:\n16۔ اور وہ مقدس چیز میں کیے گئے نقصان کی تلافی کرے گا، اور اس میں پانچواں حصہ شامل کرے گا، اور اسے پادری کو دے گا: اور پادری اس کے لیے گناہ کی قربانی کے مینڈھے سے کفارہ کرے گا، اور اسے معاف کر دیا جائے گا۔\n17۔ اور اگر کوئی شخص گناہ کرے اور ان میں سے کوئی ایسا کام کرے جو خداوند کے احکامات کے تحت ممنوع ہے؛ اگرچہ وہ نہیں جانتا، پھر بھی وہ قصوروار ہے، اور اپنی گناہ برداشت کرے گا۔\n18۔ اور وہ ریوڑ سے ایک بے داغ مینڈھا لائے گا، تمہاری قیمت کے مطابق، ایک جرم کی قربانی کے طور پر، پادری کے لیے، اور پادری اس کی لاعلمی کا کفارہ کرے گا جس میں اس نے غلطی کی اور اسے افسوس نہ ہو، اور اسے معاف کر دیا جائے گا۔\n19۔ یہ {خطا} کی قربانی ہے: اس نے یقینا خداوند کے خلاف گناہ کیا ہے۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ اگر کوئی شخص گناہ کرے، اور خداوند کے خلاف گناہ کرے، اور اپنے پڑوسی سے جھوٹ بولے جو اسے رکھنے کے لیے دیا گیا تھا، یا رفاقت میں، یا کسی چیز میں جو تشدد سے چھین لیا گیا ہو، یا اپنے پڑوسی کو دھوکہ دے گا؛ {رفاقت میں: یا، معاملات میں} {فیلوشپ: عبرانی۔ ہاتھ ڈالنا}\n3۔ یا وہ چیز جو کھو گئی ہے اسے پا لی، اور اس کے بارے میں جھوٹ بولتی ہے، اور جھوٹی قسم کھاتی ہے؛ ان سب میں جو انسان گناہ کرتا ہے، ان میں سے کسی میں:\n4۔ پھر یہ ہوگا، کیونکہ اس نے گناہ کیا ہے اور وہ قصوروار ہے، کہ وہ وہ چیز واپس کرے گا جو اس نے زور سے چھین لی ہے، یا وہ چیز جو اس نے دھوکہ دے کر حاصل کی ہے، یا جو اسے رکھنے کے لیے دی گئی تھی، یا وہ کھوئی ہوئی چیز جو اسے ملی،\n5۔ یا وہ سب جس کے بارے میں اس نے جھوٹی قسم کھائی ہے؛ وہ اسے اصل رقم میں واپس کرے گا، اور پانچواں حصہ مزید شامل کرے گا، {اور} اسے اس شخص کو دے دے گا جس کے پاس یہ ہے، اس کے جرم کی قربانی کے دن۔ {اس دن...: یا، اس دن جب اسے مجرم پایا گیا: عبرانی۔ اس کے خلاف ورزی کے دن}\n6۔ اور وہ اپنی غلطی کی قربانی خداوند کے سامنے لے آئے گا، جو ریوڑ سے ایک بے داغ مینڈھا ہے، تیری نظر کے ساتھ، جرم کی قربانی کے طور پر، پادری کے لیے:\n7۔ اور پادری اس کے لیے خداوند کے سامنے کفارہ کرے گا: اور اس کے خلاف جو کچھ بھی اس نے کیا ہے، اسے معاف کر دیا جائے گا۔\n8۔ اور خداوند نے موسیٰ سے کہا،\n9۔ ہارون اور اس کے بیٹوں کو حکم دو، کہو، یہ سلائی کی قربانی کا قانون ہے: یہ سلائی ہوئی قربانی ہے، کیونکہ قربان گاہ پر رات بھر صبح تک جلتی رہتی ہے، اور قربان گاہ کی آگ اس میں جلتی رہے گی۔ {کیونکہ...: یا، جلنے کے لیے}\n10۔ اور پادری اپنا کپڑا پہنے گا، اور اپنی کتان کی پتلون اپنے جسم پر پہنے گا، اور وہ راکھ اٹھائے گا جو آگ نے قربان گاہ پر جلنے والی قربانی کے ساتھ جل کر رکھی ہے، اور انہیں قربان گاہ کے پاس رکھے گا۔\n11۔ اور وہ اپنے کپڑے اتارے گا، اور دوسرے کپڑے پہنے گا، اور راکھ کو کیمپ کے بغیر صاف جگہ لے جائے گا۔\n12۔ اور قربان گاہ پر آگ اس میں جل رہی ہوگی؛ اسے بجھایا نہیں جائے گا: اور پادری ہر صبح اس پر لکڑی جلائے گا، اور اس پر سلائی کی قربانی ترتیب سے رکھے گا؛ اور وہ اس پر صلح کی نذرانے کی چربی جلائے گا۔\n13۔ آگ ہمیشہ قربان گاہ پر جلتی رہے گی؛ یہ کبھی بجھ نہیں جائے گا۔\n14. اور یہ گوشت کی قربانی کا قانون ہے: ہارون کے بیٹے اسے خداوند کے سامنے، قربان گاہ کے سامنے پیش کریں گے۔\n15۔ اور وہ اس میں سے اپنا مٹھی، گوشت کی پیشکش کا آٹا، اس کے تیل اور تمام لوبان جو گوشت کی قربانی پر ہے، لے کر قربان گاہ پر جلا دے گا {کیونکہ یہ میٹھی خوشبو} ہے، {حتیٰ کہ} اس کی یاد کے طور پر، خداوند کے نام۔\n16۔ اور اس کا باقی حصہ ہارون اور اس کے بیٹے کھائیں گے: بغیر خمیر کی روٹی کے ساتھ مقدس جگہ میں کھائے جائیں گے؛ جماعت کے خیمہ کے صحن میں وہ اسے کھائیں گے۔\n17۔ اسے خمیر کے ساتھ نہیں پکایا جائے گا۔ میں نے یہ ان کے لیے دیا ہے ان کے حصے کے بدلے جو آگ سے دی گئی تھی؛ یہ {ہے} سب سے مقدس ہے، جیسے {ہے} گناہ کی قربانی، اور جیسا کہ گناہ کی قربانی۔\n18۔ ہارون کے بچوں میں سے تمام مرد اس میں سے کھائیں گے۔ {یہ تمہاری نسلوں میں ہمیشہ کے لیے ایک قانون رہے گا جو خداوند کی آگ سے دی گئی نذرانے کے بارے میں ہے: جو بھی انہیں چھوئے گا وہ مقدس ہوگا۔\n19۔ اور خداوند نے موسیٰ سے کہا،\n20۔ یہ ہارون اور اس کے بیٹوں کی قربانی ہے، جو وہ خداوند کو اس دن پیش کریں گے جب وہ مسح کیا جائے گا؛ ہمیشہ گوشت کی قربانی کے لیے عمدہ آٹے کا دسواں حصہ، آدھا صبح اور آدھا رات کو۔\n21. پین میں اسے تیل سے بنایا جائے گا؛ {اور جب یہ بیک ہو جائے} تو اسے اندر لے آؤ: {اور} گوشت کی نذرانہ کے بیک کیے ہوئے ٹکڑے خداوند کے لیے میٹھا ذائقہ پیش کرو گے۔\n22۔ اور اس کے بیٹوں کا پادری جو اس کی جگہ مسح کیا گیا ہے، اسے پیش کرے گا: {یہ ہمیشہ کے لیے خداوند کے لیے ایک قانون ہے}؛ اسے مکمل طور پر جلا دیا جائے گا۔\n23۔ کیونکہ پادری کے لیے ہر گوشت کی قربانی مکمل طور پر جلا دی جائے گی: اسے نہیں کھایا جائے گا۔\n24۔ اور خداوند نے موسیٰ سے کہا،\n25۔ ہارون اور اس کے بیٹوں سے بات کرو، کہو، یہ گناہ کی قربانی کا قانون ہے: جہاں جلنے والی قربانی ماری جائے گی، وہاں گناہ کی قربانی خداوند کے سامنے ماری جائے گی: یہ سب سے مقدس ہے۔\n26۔ جو پادری اسے گناہ کے طور پر پیش کرے گا، وہ اسے کھائے گا: مقدس جگہ پر، جماعت کے خیمہ کے صحن میں کھائے جائے گا۔\n27۔ جو بھی اس کے جسم کو چھوئے گا وہ مقدس ہوگا: اور جب اس کا خون کسی لباس پر چھڑکا جائے تو مقدس جگہ پر چھڑکا گیا خون دھو دو۔\n28۔ لیکن وہ مٹی کا برتن جس میں یہ بھیگا ہوا ہے، ٹوٹ جائے گا: اور اگر اسے برتن کے برتن میں بھیگا دیا جائے تو اسے صاف کیا جائے گا اور پانی میں دھویا جائے گا۔\n29۔ کاہنوں میں سے تمام مرد اس میں سے کھائیں گے: یہ سب سے مقدس ہے۔\n30۔ اور کوئی گناہ کی قربانی، جس کا خون جماعت کے خیمہ میں مقدس جگہ پر صلح کے لیے لایا جائے، نہیں کھائی جائے گی: اسے آگ میں جلایا جائے گا۔","1. اسی طرح یہ {ہے} قانون برائے تجاوزات کی قربانی: یہ {ہے} سب سے مقدس ہے۔\n2۔ جہاں وہ جلنے والی قربانی کو ماریں گے، وہاں وہ قربانی کو قتل کریں گے: اور اس کا خون قربان گاہ پر چھڑکا جائے گا۔\n3۔ اور وہ اس کی ساری چربی پیش کرے گا؛ پچھواڑے، اور اندر کی چربی جو ڈھانپتی ہے،\n4۔ اور دو گردے، اور ان پر جو چربی {ہے} جو پہلو سے ہے، اور جگر کے اوپر جو گردوں کے ساتھ ہے، وہ اسے لے جائے گا:\n5۔ اور پادری انہیں قربان گاہ پر جلا دے گا {کیونکہ یہ آگ سے خداوند کے لیے پیش کی گئی نذرانہ ہے} یہ {خطا} کی قربانی ہے۔\n6۔ پادریوں میں سے ہر مرد اسے کھائے گا: یہ مقدس جگہ پر کھائے جائے گا: یہ سب سے مقدس ہے۔\n7. جیسے گناہ کی قربانی {ہے}، ویسے ہی {ہے} گناہ کی قربانی: {ان کے لیے ایک قانون ہے}: جو پادری اس سے کفارہ کرے گا، اسے {وہ} ملے گا۔\n8۔ اور جو پادری کسی انسان کی جلتی ہوئی قربانی پیش کرے، {حتیٰ کہ} پادری کو اس سوختی قربانی کی کھال اپنے لیے ملے گی جو اس نے پیش کی ہے۔\n9۔ اور جو بھی گوشت کی قربانی تندور میں بکی جائے گی، اور جو کچھ فرائنگ پین اور پین میں رکھا جائے گا، وہ سب پادری کے ہوں گے جو اسے پیش کرے گا۔ {پین میں: یا، فلیٹ پلیٹ پر یا، سلائس}\n10۔ اور ہر گوشت کی قربانی، تیل میں ملائی ہوئی، اور خشک ہو، ہارون کے تمام بیٹوں کو ملے گا، ایک {اتنا} کے برابر دوسرے کو۔\n11۔ اور یہ امن کی قربانیوں کی قربانی کا قانون ہے، جو وہ خداوند کے سامنے پیش کرے گا۔\n12۔ اگر وہ اسے شکرگزاری کے طور پر پیش کرے، تو وہ شکرگزاری کی قربانی کے ساتھ تیل میں ملائے ہوئے بغیر خمیر کے کیک اور تیل سے مسح شدہ بغیر خمیر کے ویفرز، اور تیل کے ساتھ ملائے ہوئے کیک کو باریک آٹے کے تلے ہوئے پیش کرے گا۔\n13۔ کیک کے علاوہ، وہ اپنی قربانی کے بدلے خمیر شدہ روٹی پیش کرے گا، جس میں اس کی صلح کی قربانیوں کی قربانی شامل ہوگی۔\n14۔ اور وہ اس میں سے ایک قربانی میں سے ایک پیش کرے گا {کیونکہ خداوند کو ایک ہلکی قربانی دی جائے گی، اور یہ پادری کا ہوگا جو صلح کی نذرانے کا خون چھڑکائے گا۔\n15۔ اور اس کی صلح کی قربانیوں کا گوشت اسی دن کھایا جائے گا جس دن پیش کیا جائے گا؛ وہ اس میں سے کچھ بھی صبح تک نہیں چھوڑے گا۔\n16۔ لیکن اگر اس کی قربانی قسم یا رضاکارانہ قربانی ہو، تو وہ اسی دن کھائی جائے گی جس دن وہ قربانی پیش کرے گا: اور کل بھی باقی حصہ کھایا جائے گا:\n17۔ لیکن قربانی کے باقی گوشت کو تیسرے دن آگ سے جلا دیا جائے گا۔\n18۔ اور اگر تیسرے دن اس کی صلح کی قربانی کے گوشت کا کوئی حصہ کھایا جائے تو اسے قبول نہیں کیا جائے گا، نہ ہی اسے پیش کرنے والے پر منسوب کیا جائے گا: یہ مکروہ ہوگا، اور جو روح اس میں سے کھائے گی وہ اس کی گناہ برداشت کرے گی۔\n19۔ اور جو گوشت کسی ناپاک چیز کو چھوئے گا، اسے نہیں کھایا جائے گا؛ اسے آگ سے جلایا جائے گا: اور گوشت کے لیے، جو بھی پاک ہے وہ اس میں سے کھائے گا۔\n20۔ لیکن جو روح صلح کی قربانی کے گوشت کو کھاتی ہے، جو خداوند سے متعلق ہے، اس کی ناپاکی اس پر ہے، وہ روح بھی اپنی قوم سے کاٹ دی جائے گی۔\n21۔ مزید یہ کہ وہ روح جو کسی ناپاک چیز کو چھوئے، جیسے انسان کی ناپاکی، یا کوئی ناپاک جانور یا کوئی ناپاک چیز ہو، اور امن کی قربانیوں کے گوشت سے کھائے جو خداوند کے لیے ہیں، حتیٰ کہ وہ روح بھی اپنی قوم سے کاٹ دی جائے گی۔\n22۔ اور خداوند نے موسیٰ سے کہا،\n23۔ بنی اسرائیل سے کہو کہو، تم کوئی چربی، بیل، بھیڑ یا بکری نہیں کھاؤ گے۔\n24۔ اور جانور کی چکنائی جو خود سے مر جائے، اور جو جانور پھٹی ہوئی اس کی چکنائی کسی اور مقصد کے لیے استعمال کی جا سکتی ہے، لیکن تم اسے کبھی نہیں کھاؤ گے۔ {درندہ...: عبرانی۔ کارکیس}\n25۔ کیونکہ جو بھی جانور کی چربی کھائے گا، جس کی نذرانہ آگ سے خدا کو پیش کی جائے، وہ بھی جو اسے کھائے گا، وہ بھی اپنی قوم سے کاٹ دی جائے گی۔\n26. مزید برآں، آپ اپنے کسی بھی گھر میں کسی بھی قسم کا خون نہیں کھائیں گے، چاہے وہ مرغی کا ہو یا جانور کا۔\n27۔ جو بھی روح خون کھائے گی، وہ بھی اپنی قوم سے کاٹ دی جائے گی۔\n28۔ اور خداوند نے موسیٰ سے کہا،\n29۔ بنی اسرائیل سے فرماو، کہو، جو اپنی صلح کی قربانیاں خداوند کے سامنے پیش کرتا ہے، وہ اپنی قربانی خداوند کے سامنے پیش کرے گا، اس کی صلح کی قربانیوں کی قربانی۔\n30۔ اس کے اپنے ہاتھ خداوند کی آگ سے بنائی گئی نذرانے لائیں گے، سینے والی چکنائی، وہ لے کر آئے گا تاکہ سینے کو لہرایا جا سکے {بطور خدا کے سامنے نذرانہ کے طور پر۔\n31۔ اور کاهن چربی کو قربان گاہ پر جلائے گا، لیکن سینہ ہارون اور اس کے بیٹوں کا ہوگا۔\n32۔ اور دائیں کندھا تم پادری کو اپنے امن کی قربانیوں کی قربانی کے بدلے پیش کرو گے۔\n33۔ ہارون کے بیٹوں میں سے جو صلح کی قربانیوں اور چربی کا خون پیش کرتا ہے، اس کے حصے کے لیے دایاں کندھا ہوگا۔\n34۔ لہراتا ہوا سینہ اور کندھے کے لیے میں نے بنی اسرائیل کو ان کی صلح کی قربانیوں سے ہٹا دیا ہے، اور انہیں ہارون کاہن اور اس کے بیٹوں کو ہمیشہ کے لیے بنی اسرائیل کی اولاد میں سے ایک مجسمے کے ذریعے دے دیا ہے۔\n35. یہ وہ حصہ ہے جو ہارون اور اس کے بیٹوں کے مسح کا حصہ ہے، جو خداوند کی آگ کے ذریعے دی گئی نذرانے سے ہے، اس دن {جب} اس نے انہیں خدا کی خدمت کے لیے پادری کے دفتر میں پیش کیا؛\n36۔ جسے خداوند نے حکم دیا کہ انہیں بنی اسرائیل میں سے دیا جائے، اس دن جب اس نے انہیں مسح کیا، {وہاں} ان کی نسلوں کے لیے ہمیشہ کے لیے ایک حکم دیا جائے۔\n37. یہ جلنے کی قربانی، گوشت کی قربانی، گناہ کی قربانی، اور جرم کی قربانی، تقدیس، اور امن کی قربانیوں کا قانون ہے؛\n38۔ جسے خداوند نے موسیٰ کو پہاڑ سینا میں حکم دیا، اس دن جب اس نے بنی اسرائیل کو حکم دیا کہ وہ سینا کے بیابان میں خداوند کے سامنے اپنی قربانیاں پیش کریں۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ ہارون اور اس کے بیٹوں کو اپنے ساتھ لے جائے، کپڑے، مسح کرنے کا تیل، گناہ کی قربانی کے لیے ایک بیل، دو مینڈے، اور خمیر کی ایک ٹوکری لے جائے؛\n3۔ اور تو تمام جماعت کو جماعت کے خیمہ کے دروازے تک جمع کرو۔\n4۔ اور موسیٰ نے خداوند کے حکم کے مطابق کیا؛ اور مجمع کو جماعت کے خیمہ کے دروازے تک جمع کیا گیا۔\n5۔ اور موسیٰ نے جماعت سے کہا، یہ وہ کام ہے جسے خداوند نے کرنے کا حکم دیا ہے۔\n6۔ اور موسیٰ ہارون اور اس کے بیٹوں کو لے آیا اور انہیں پانی سے دھویا۔\n7۔ اور اس نے اس پر کوٹ پہنایا، اسے بیلٹ سے باندھا، اور چادر پہنایا، اور ایفود اس پر پہنا، اور اسے ایفود کی عجیب بیلٹ سے باندھا، اور اسے اس سے باندھ دیا۔\n8۔ اور اس نے اس پر سینہ کی چادر پہنائی: اسی طرح اس نے سینے کی چادر میں یوریم اور تھمم بھی ڈالے۔\n9۔ اور اس نے اپنے سر پر مائٹر رکھا؛ اسی طرح اس نے تاج کے اوپر، {حتیٰ کہ} اپنے سامنے سونے کی تختی، مقدس تاج بھی رکھی؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n10۔ اور موسیٰ نے مسح کرنے والا تیل لیا، اور خیمہ اور اس میں موجود تمام چیزوں کو مسح کیا اور انہیں پاک کر دیا۔\n11۔ اور اس نے اس میں سے سات بار قربان گاہ پر چھڑکے، اور قربان گاہ اور اس کے تمام برتنوں، چاہے وہ لیور ہو یا پاؤں کو، مسح کیا تاکہ انہیں پاک کیا جا سکے۔\n12۔ اور اس نے ہارون کے سر پر مسح کرنے والا تیل ڈالا اور اسے مسح کیا تاکہ اسے پاک کرے۔\n13۔ اور موسیٰ نے ہارون کے بیٹوں کو لایا، انہیں کوٹ پہنایا، بیلٹ باندھا اور ٹوپیاں پہنائیں؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔ {پٹ بونٹس: ہیب۔ بندھے ہوئے بونٹس}\n14۔ اور اس نے گناہ کی قربانی کے لیے بیل لایا: اور ہارون اور اس کے بیٹوں نے گناہ کی قربانی کے لیے بیل کے سر پر ہاتھ رکھے۔\n15۔ اور اس نے قتل کر دیا؛ اور موسیٰ نے خون لیا، اور اسے اپنی انگلی سے قربان گاہ کے سینگوں پر رکھا، اور قربان گاہ کو پاک کیا، اور خون قربان گاہ کے نیچے انڈیل کر اسے مقدس کر دیا، تاکہ اس پر صلح کی جا سکے۔\n16۔ اور اس نے اندر کی طرف موجود تمام چربی لے لی، اور جگر کے اوپر، اور دونوں گردے اور ان کی چربی لے لی، اور موسیٰ نے اسے قربان گاہ پر جلا دیا۔\n17۔ لیکن بیل، اس کی کھال، اس کا گوشت اور گوبر، وہ بغیر کیمپ کے آگ میں جل گیا؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n18۔ اور اس نے جلانے والی قربانی کے لیے مینڈھا لایا: اور ہارون اور اس کے بیٹوں نے مینڈھے کے سر پر ہاتھ رکھ دیے۔\n19۔ اور اس نے {اسے} کو مار ڈالا؛ اور موسیٰ نے ارد گرد قربان گاہ پر خون چھڑک دیا۔\n20۔ اور اس نے مینڈھے کو ٹکڑوں میں کاٹ دیا؛ اور موسیٰ نے سر، ٹکڑے اور چربی جلا دی۔\n21۔ اور اس نے اندرونی حصے اور ٹانگوں کو پانی میں دھویا؛ اور موسیٰ نے پورا مینڈھا قربان گاہ پر جلا دیا: یہ میٹھے ذائقے کے لیے جلی ہوئی قربانی تھی، اور آگ سے خداوند کے لیے پیش کی گئی نذرانہ تھی؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n22۔ اور اس نے دوسرا مینڈھا، جو تقدیس کا مینڈھا تھا، لایا: اور ہارون اور اس کے بیٹوں نے مینڈھے کے سر پر ہاتھ رکھے۔\n23۔ اور اس نے {اسے} کو مار ڈالا؛ اور موسیٰ نے اس کا خون لیا اور اسے ہارون کے دائیں کان کی نوک، اس کے دائیں ہاتھ کے انگوٹھے پر، اور اس کے دائیں پاؤں کی بڑی انگلی پر رکھا۔\n24۔ اور اس نے ہارون کے بیٹوں کو لایا، اور موسیٰ نے ان کے دائیں کان کی نوک، دائیں ہاتھوں کے انگوٹھوں پر، اور ان کے دائیں پیروں کی بڑی انگلیوں پر خون لگایا، اور موسیٰ نے خون کو قربان گاہ کے ارد گرد چھڑکا۔\n25۔ اور اس نے چربی، کولہے، اور تمام چربی جو اندر کی طرف تھی، اور جگر کے اوپر، اور دو گردے، ان کی چربی اور دائیں کندھے کو لیا:\n26۔ اور اس بغیر خمیر کے روٹی کے ٹوکری سے، جو خداوند کے سامنے تھی، اس نے ایک بغیر خمیر کا کیک، تیل لگا روٹی کا کیک اور ایک ویفر لیا، اور انہیں چربی پر اور دائیں کندھے پر رکھا:\n27۔ اور اس نے سب کچھ ہارون کے ہاتھوں اور اس کے بیٹوں کے ہاتھوں پر ڈال دیا، اور انہیں خداوند کے سامنے لہرانے کے لیے لہرایا۔\n28۔ اور موسیٰ نے انہیں ان کے ہاتھوں سے لے کر قربان گاہ پر جلایا جو جلتی ہوئی قربانی پر تھی: یہ ایک میٹھے ذائقے کے لیے وقف تھے: یہ آگ سے خداوند کے لیے پیش کی گئی نذرانہ ہے۔\n29۔ اور موسیٰ نے سینے کو اٹھایا اور اسے خداوند کے سامنے لہرانے کے لیے لہرایا: {کیونکہ} تقدیس کے مینڈھے سے یہ موسیٰ کا حصہ تھا؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n30۔ اور موسیٰ نے مسح کے تیل سے، اور وہ خون جو {قربان گاہ} پر تھا، لیا اور ہارون پر، {اور} اپنے لباسوں پر، اپنے بیٹوں پر، اور اپنے بیٹوں کے کپڑوں پر چھڑکا؛ اور ہارون کو مقدس کیا، {اور} اس کے کپڑے، اپنے بیٹوں کو، اور اپنے بیٹوں کے کپڑے بھی ساتھ لے لیے۔\n31۔ اور موسیٰ نے ہارون اور اس کے بیٹوں سے کہا، جماعت کے خیمہ کے دروازے پر گوشت کو ابالو: اور وہاں اسے اس روٹی کے ساتھ کھاؤ جو تقدیس کی ٹوکری میں ہے، جیسا کہ میں نے حکم دیا تھا، کہا، ہارون اور اس کے بیٹے اسے کھائیں گے۔\n32۔ اور جو کچھ گوشت اور روٹی سے بچا ہے اسے آگ سے جلایا جائے گا۔\n33۔ اور تم جماعت کے خیمے کے دروازے سے سات دن تک باہر نہیں جاؤ گے، جب تک تمہاری تقدیس کے دن ختم نہ ہو جائیں: سات دن تک وہ تمہیں مقدس کرے گا۔\n34۔ جیسا کہ اس نے آج کیا ہے، {ویسے} خداوند نے حکم دیا ہے کہ وہ تمہارے لیے کفارہ کرے۔\n35۔ اس لیے تم جماعت کے خیمے کے دروازے پر دن رات سات دن رہو گے، اور خداوند کی حفاظت کرو گے کہ تم نہ مرنا: کیونکہ مجھے ایسا حکم دیا گیا ہے۔\n36۔ یوں ہارون اور اس کے بیٹوں نے وہ سب کچھ کیا جو خداوند نے موسیٰ کے ہاتھ سے حکم دیا۔","1۔ اور یہ آٹھویں دن ہوا، {کہ} موسیٰ نے ہارون اور اس کے بیٹوں اور اسرائیل کے بزرگوں کو بلایا؛\n2۔ اور اس نے ہارون سے کہا، اپنے لیے ایک نوجوان بچھڑا گناہ کی قربانی کے طور پر لے لو، اور ایک مینڈھا بغیر کسی عیب کے جلنے کی قربانی دو، اور خداوند کے سامنے پیش کرو۔\n3۔ اور تم بنی اسرائیل سے کہو کہو، بکریوں کے بچے کو گناہ کی قربانی کے طور پر لو؛ اور ایک بچھڑا اور ایک بھیڑا، {دونوں} پہلے سال کے، بغیر کسی داغ کے، سجلنے کی قربانی کے طور پر؛\n4۔ ایک بیل اور ایک مینڈھا امن کی قربانیوں کے لیے، خدا کے سامنے قربان کرنے کے لیے؛ اور تیل کے ساتھ ملا ہوا گوشت کی نذرانہ بھی: کیونکہ آج خداوند آپ پر ظاہر ہوگا۔\n5۔ اور انہوں نے وہ سب کچھ پیش کیا جو موسیٰ نے جماعت کے خیمہ کے سامنے حکم دیا تھا، اور سب جماعت قریب آ کر خداوند کے سامنے کھڑی ہو گئی۔\n6۔ اور موسیٰ نے کہا، یہ وہ کام ہے جو خداوند نے تمہیں کرنے کا حکم دیا ہے: اور خداوند کی شان تمہیں ظاہر کرے گی۔\n7۔ اور موسیٰ نے ہارون سے کہا، قربان گاہ پر جاؤ، اپنا گناہ کی قربانی اور اپنی جلتی ہوئی قربانی پیش کرو، اور اپنے لیے اور لوگوں کے لیے کفارہ دو، اور لوگوں کی قربانی پیش کر، اور ان کے لیے کفارہ دو؛ جیسا کہ خداوند نے حکم دیا۔\n8۔ ہارون اس لیے قربان گاہ پر گیا، اور گناہ کی قربانی کا بچھڑا مار ڈالا، جو {اپنے لیے} تھا۔\n9۔ اور ہارون کے بیٹوں نے خون اس کے پاس لایا، اور اس نے اپنی انگلی خون میں ڈبوئی، اور اسے قربان گاہ کے سینگوں پر رکھا، اور خون قربان گاہ کے نیچے بہا دیا:\n10۔ لیکن چربی، گردے، اور گناہ کی قربانی کے جگر کے اوپر والی کال، اس نے قربان گاہ پر جلائی؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n11۔ اور گوشت اور کھال کو آگ سے جلا دیا بغیر کیمپ کے۔\n12۔ اور اس نے سلائی ہوئی قربانی کو ذبح کیا؛ اور ہارون کے بیٹوں نے اسے خون پیش کیا، جسے اس نے قربان گاہ پر چھڑک دیا۔\n13۔ اور انہوں نے اس کے سامنے سلائی ہوئی قربانی، اس کے ٹکڑے اور سر پیش کیے، اور اس نے انہیں قربان گاہ پر جلا دیا۔\n14۔ اور اس نے اندرونی اور ٹانگیں دھوئیں، اور قربان گاہ پر جلانے والی قربانی پر جلا دیے۔\n15۔ اور اس نے لوگوں کی قربانی لے کر بکری لی، جو لوگوں کے لیے گناہ کی قربانی تھی، اور اسے قتل کر کے گناہ کے طور پر پیش کیا، جیسا کہ پہلا تھا۔\n16۔ اور اس نے جلنے والی قربانی لائی اور اسے اپنے طریقے کے مطابق پیش کیا۔ {طریقہ: یا، آرڈیننس}\n17۔ اور اس نے گوشت کی قربانی لی، اس میں سے ایک مٹھی بھر لی، اور اسے صبح کی جلی ہوئی قربانی کے ساتھ قربان گاہ پر جلا دیا۔ {لیا...: عبرانی۔ اس کا ہاتھ اس میں سے بھر دیا}\n18۔ اس نے بیل اور مینڈھے کو بھی قتل کیا {ایک قربانی کے طور پر} جو لوگوں کے لیے تھی: اور ہارون کے بیٹوں نے اسے خون پیش کیا، جسے اس نے ارد گرد قربان گاہ پر چھڑکا،\n19۔ اور بیل اور مینڈھے کی چکنائی، پچھواڑے، اور وہ جو {اندرونی حصہ} کو ڈھانپتی ہے، اور گردے، اور کاول {اوپر} جگر کی:\n20۔ اور انہوں نے چربی سینوں پر رکھی، اور اس نے چربی قربان گاہ پر جلا دی:\n21۔ اور سینے اور دائیں کندھے پر ہارون نے خداوند کے سامنے ایک نذرانہ لہرایا؛ جیسا کہ موسیٰ نے حکم دیا۔\n22۔ اور ہارون نے لوگوں کی طرف ہاتھ اٹھایا، انہیں برکت دی، اور گناہ کی قربانی، جلانے والی قربانی، اور صلح کی نذرانے سے نیچے آیا۔\n23۔ اور موسیٰ اور ہارون جماعت کے خیمہ میں گئے، باہر آئے اور لوگوں کو برکت دی: اور خداوند کی شان سب لوگوں پر ظاہر ہوئی۔\n24۔ اور خداوند کے سامنے سے آگ نکلی، اور قربان گاہ پر جلنے والی قربانی اور چربی کو جلا دیا: جب سب نے دیکھا تو چیخ اٹھے اور منہ کے بل گر گئے۔","1۔ اور ناداب اور ابیہو، ہارون کے بیٹے، نے ان میں سے کسی ایک کو اپنا بخور لیا، اس میں آگ لگائی، اور اس پر خوشبو ڈالی، اور خدا کے سامنے عجیب آگ پیش کی، جس کا حکم اس نے انہیں نہیں دیا۔\n2۔ اور خداوند کی طرف سے آگ نکلی، اور انہیں نگل گیا، اور وہ خداوند کے سامنے مر گئے۔\n3۔ پھر موسیٰ نے ہارون سے کہا، یہی وہ ہے جو خداوند نے فرمایا، کہ میں ان میں پاک ہوں گا جو میرے قریب آئیں گے، اور سب لوگوں کے سامنے جلال پاؤں گا۔ اور ایرن خاموش رہا۔\n4۔ اور موسیٰ نے عزیئل کے بیٹے، جو ہارون کے چچا تھے، مشائیل اور الزفان کو بلایا اور کہا، قریب آؤ، اپنے بھائیوں کو مقدس مقام کے سامنے سے کیمپ سے باہر لے جاؤ۔\n5۔ تو وہ قریب گئے اور انہیں ان کے کوٹ میں لے کر کیمپ سے باہر لے گئے؛ جیسا کہ موسیٰ نے کہا تھا۔\n6۔ اور موسیٰ نے ہارون، الیعازر اور اس کے بیٹوں ایثمار سے کہا، اپنے سر نہ کھولو، نہ اپنے کپڑے پھاڑو؛ کہیں تم مر نہ جاؤ، اور سب لوگوں پر غصہ نہ آ جائے، بلکہ تمہارے بھائیو، پورے اسرائیل کے گھر، اس آگ کا ماتم کریں جو خداوند نے آگ لگائی ہے۔\n7۔ اور تم جماعت کے خیمے کے دروازے سے باہر نہیں جاؤ گے، ورنہ مر جاؤ گے: کیونکہ خداوند کا مسح کرنے والا تیل تم پر ہے۔ اور انہوں نے موسیٰ کے کلام کے مطابق ایسا کیا۔\n8۔ اور خداوند نے ہارون سے کہا،\n9۔ جب تم جماعت کے خیمے میں جاؤ تو نہ شراب پیو اور نہ ہی تیز پینا، نہ تمہارے بیٹے، ورنہ مر جاؤ گے: یہ تمہاری نسلوں کے لیے ہمیشہ کے لیے ایک حکم رہے گا:\n10۔ اور تاکہ تم پاک اور ناپاک میں فرق کر سکو، اور ناپاک اور پاک کے درمیان؛\n11۔ اور تاکہ تم بنی اسرائیل کو وہ تمام قوانین سکھاؤ جو خداوند نے موسیٰ کے ہاتھوں ان سے کہے ہیں۔\n12۔ اور موسیٰ نے ہارون، اور الیعزر اور اپنے بیٹوں سے کہا، خداوند کی آگ سے بنائی گئی نذرانے میں سے باقی گوشت کی قربانی لے کر قربان گاہ کے پاس بغیر خمیر کے کھاؤ، کیونکہ یہ سب سے مقدس ہے:\n13۔ اور تم اسے مقدس جگہ پر کھاؤ گے، کیونکہ یہ تمہارا حق ہے، اور تمہارے بیٹوں کا حق ہے، خداوند کی آگ سے دی گئی قربانیوں کا: کیونکہ مجھے ایسا حکم دیا گیا ہے۔\n14۔ اور لہراتا ہوا سینہ اور کندھا صاف جگہ پر کھاؤ گے؛ تم، اور تمہارے بیٹے، اور تمہاری بیٹیاں تمہارے ساتھ ہیں: کیونکہ وہ تمہارا حق ہیں، اور تمہارے بیٹوں کے حق، جو بنی اسرائیل کی صلح کی قربانیوں سے دیے جاتے ہیں۔\n15۔ کندھا اور لہراتا ہوا سینہ چربی کی آگ سے دی گئی نذرانے کے ساتھ لائیں گے، تاکہ خداوند کے سامنے لہرانے کے لیے پیش کیا جا سکے؛ اور یہ تمہارا ہوگا، اور تمہارے بیٹوں کا بھی، ہمیشہ کے لیے ایک قانون کے تحت؛ جیسا کہ خداوند نے حکم دیا ہے۔\n16۔ اور موسیٰ نے محنت سے گناہ کی قربانی کی بکری تلاش کی، اور دیکھو وہ جل گئی: اور وہ الیعزر اور ایثمار سے ناراض ہوا، جو ہارون کے بیٹے {جسے} زندہ رہ گئے تھے، اور کہا،\n17۔ تم نے مقدس جگہ پر گناہ کی قربانی کیوں نہیں کھائی، جب کہ وہ سب سے مقدس ہے، اور {خدا} نے اسے تمہیں جماعت کی بدکاری برداشت کرنے اور ان کے لیے خداوند کے سامنے کفارہ دینے کے لیے دیا ہے؟\n18۔ دیکھو، اس کا خون مقدس {جگہ} میں نہیں لایا گیا: تمہیں واقعی مقدس {جگہ} میں کھانا چاہیے تھا، جیسا کہ میں نے حکم دیا تھا۔\n19۔ اور ہارون نے موسیٰ سے کہا، دیکھو، آج انہوں نے اپنے گناہ کی قربانی اور سلائی کی قربانی خداوند کے سامنے پیش کی ہے؛ اور ایسی باتیں میرے ساتھ ہوئی ہیں: اور {اگر} میں آج گناہ کی قربانی کھا چکا ہوتا، تو کیا وہ خدا کی نظر میں قبول کی جاتی؟\n20۔ اور جب موسیٰ نے یہ سنا، تو وہ مطمئن ہو گیا۔","1۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n2۔ بنی اسرائیل سے کہو، یہ وہ جانور ہیں جنہیں تم زمین پر موجود تمام جانوروں میں کھاؤ گے۔\n3۔ جو بھی کھر کو چیرتا ہے اور پھٹے ہوئے ہے، {اور} ان جانوروں میں سے کڈ کو چباتا ہے جو تم کھاؤ گے۔\n4۔ پھر بھی تم ان میں سے نہ کھاؤ گے جو کاڈ چباتا ہے، نہ ہی وہ جو کھر کو تقسیم کرتے ہیں: جیسے اونٹ کیونکہ وہ کاڈ چباتا ہے، لیکن کھر کو تقسیم نہیں کرتا؛ وہ تمہارے لیے ناپاک ہے۔\n5۔ اور کون، کیونکہ وہ کڈ کو چباتا ہے، لیکن کھر کو تقسیم نہیں کرتا؛ وہ تمہارے لیے ناپاک ہے۔\n6۔ اور خرگوش، کیونکہ وہ کڈ کو چباتا ہے، مگر کھر کو تقسیم نہیں کرتا؛ وہ تمہارے لیے ناپاک ہے۔\n7۔ اور سور، اگرچہ وہ کھر کو تقسیم کرتا ہے اور پاؤں پھٹتا ہے، پھر بھی وہ کڈ کو نہیں چباتا؛ وہ تمہارے لیے ناپاک ہے۔\n8۔ ان کے گوشت کو نہ کھاؤ گے، نہ ان کی لاش کو چھوؤ گے؛ وہ آپ کے لیے ناپاک ہیں۔\n9۔ یہ آپ پانیوں میں موجود تمام چیزوں میں سے کھائیں گے: جو کچھ پانیوں میں، سمندروں اور دریاؤں میں پنکھ اور ترازو رکھتا ہے، وہ آپ کھائیں گے۔\n10۔ اور وہ سب جو سمندروں میں پر اور ترازو نہیں رکھتے، نہ ہی دریاؤں میں، نہ پانیوں میں حرکت کرنے والے، اور جو بھی جاندار پانی میں ہے، وہ سب تمہارے لیے مکروہ ہوں گے:\n11۔ وہ تمہارے لیے بھی ایک مکروہ ہوں گے؛ تم ان کے گوشت کو نہیں کھاؤ گے، بلکہ ان کی لاشیں تم پر مکروہ ہوں گی۔\n12۔ جو پانی میں نہ پر ہو اور نہ ہی ترازو ہو، وہ تمہارے لیے مکروہ ہوگا۔\n13۔ اور یہ وہ لوگ ہیں جو تم پرندوں میں مکروہ ہو سکتے ہو؛ انہیں نہیں کھائے جائیں گے، وہ ایک مکروہ مخلوق ہیں: عقاب، اوسیفریج، اور اوسپرے،\n14۔ اور گدھ، اور پتنگ اپنی نسل کے بعد؛\n15۔ ہر کوا اپنی نسل کے مطابق؛\n16۔ اور الو، اور رات کا باز، اور کوکو، اور باز جو اس کی نسل کے مطابق ہے،\n17۔ اور چھوٹا الو، اور کورمورینٹ، اور بڑا الو،\n18۔ اور ہنس، اور پیلیکن، اور گیئر عقاب،\n19۔ اور اسٹورک، اپنی نسل کے ہیرن، اور لیپ ونگ، اور چمگادڑ۔\n20۔ جو بھی پرندے چاروں پر حملہ کریں گے، وہ تمہارے لیے مکروہ ہوں گے۔\n21۔ پھر بھی تم ہر اس اڑتے ہوئے رینگنے والے جانور کو کھا سکتے ہو جو {چار} پر جاتا ہے، جن کے پیروں کے اوپر ٹانگیں ہیں، زمین پر چھلانگ لگانے کے لیے؛\n22۔ {یہاں تک کہ} کہ تم ان میں سے کھا سکتے ہو؛ ٹڈی دل اپنی نوع کے بعد، گنجا ٹڈی دل اپنی نوع کے بعد، بھنبھرا اپنی نسل کے بعد، اور ٹڈی دل اس کی نسل کے بعد۔\n23. لیکن باقی تمام اڑتے ہوئے رینگنے والے جاندار، جن کے چار پاؤں ہیں، وہ تمہارے لیے ایک مکروہ چیز ہوں گے۔\n24۔ اور ان کے لیے تم ناپاک ہو گے: جو بھی ان کی لاش کو چھوئے گا وہ ناپاک رہے گا یہاں تک کہ روز پاکیزہ۔\n25۔ اور جو بھی ان کی لاش اٹھائے گا، وہ اپنے کپڑے دھوئے گا، اور ناپاک رہے گا جب تک کہ وہ جج نہ ہو۔\n26. ہر اس جانور کی لاشیں جو کھر کو تقسیم کرتی ہے، اور نہ تو پھٹے ہوئے ہے اور نہ ہی کڈ چباتا ہے، تمہارے لیے ناپاک ہے: جو بھی انہیں چھوئے گا وہ ناپاک ہوگا۔\n27. اور جو بھی اس کے پنجوں پر جاتا ہے، ان تمام جانوروں میں جو چاروں پر چلتے ہیں، وہ تمہارے لیے ناپاک ہیں: جو ان کی لاش کو چھوئے گا وہ ناپاک ہوگا جب تک کہ وہ برابر نہ ہو۔\n28۔ اور جو ان کی لاش اٹھائے گا وہ اپنے کپڑے دھوئے گا اور ناپاک رہے گا جب تک کہ وہ تمہارے لیے ناپاک نہ ہوں۔\n29۔ یہ بھی تمہارے لیے ان رینگنے والے جانداروں میں سے ناپاک ہوں گے جو زمین پر رینگتی ہیں؛ چوہا، چوہا، اور اپنی نسل کے پیچھے کچھوا،\n30۔ اور فرٹ، اور گرگٹ، اور چھپکلی، گھونگھا، اور تل۔\n31۔ یہ سب لوگ تمہارے لیے ناپاک ہیں: جو بھی انہیں چھوئے گا، جب وہ مر جائیں گے، وہ ناپاک رہے گا جب تک کہ وقت نہ گزرے۔\n32۔ اور جب ان میں سے کوئی بھی مر جائے گا تو وہ ناپاک ہوگا؛ چاہے وہ کوئی لکڑی کا برتن ہو، یا لباس، یا چمڑ، یا تھیلا ہو، جو بھی برتن ہو جس میں {کو} کام کیا جائے، اسے پانی میں ڈالنا ضروری ہے، اور وہ ناپاک رہے گا جب تک کہ وقت تک صاف نہ ہو؛ تو یہ صاف ہو جائے گا۔\n33۔ اور ہر مٹی کا برتن جس میں {کو} گرے، اس میں جو {ہے} وہ ناپاک ہوگا؛ اور تم اسے توڑو گے۔\n34۔ جو بھی گوشت کھایا جا سکتا ہے، {وہ} جس پر {ایسا} پانی آتا ہے، وہ ناپاک ہوگا؛ اور جو بھی مشروب ہر {ایسا} برتن میں پیا جائے گا، وہ ناپاک ہوگا۔\n35۔ اور ہر وہ چیز جس پر ان کی لاش کا کوئی حصہ گرے گا، وہ ناپاک ہو جائے گی؛ {چاہے} تندور ہو، یا برتنوں کے لیے رینج، وہ توڑ دیے جائیں گے: {کیونکہ} وہ ناپاک ہیں، اور تمہارے لیے ناپاک ہوں گے۔\n36۔ پھر بھی کوئی چشمہ یا گڑھا، {جہاں پانی وافر ہو} صاف ہوگا، لیکن جو ان کے جسم کو چھوتا ہے وہ ناپاک ہوگا۔ {جس میں...: عبرانی۔ پانیوں کا اجتماع}\n37۔ اور اگر ان کی لاش کا کوئی حصہ کسی بیج بونے والے بیج پر گر جائے جو بویا جانا ہے، تو وہ صاف ہو جائے گا۔\n38۔ لیکن اگر {کو} پانی بیج پر ڈالا جائے اور {ان کے جسم کا کوئی حصہ} اس پر گر جائے، تو وہ {تمہارے} کے لیے ناپاک ہوگا۔\n39۔ اور اگر کوئی جانور جسے تم کھا سکتے ہو، مر جائے؛ جو اس کی لاش کو چھوئے گا وہ شام تک ناپاک ہوگا۔\n40۔ اور جو اس کا لاش کھائے گا وہ اپنے کپڑے دھوئے گا، اور ناپاک رہے گا جب تک کہ جسم نہ ہو جائے؛ جو بھی اس کی لاش اٹھائے گا وہ اپنے کپڑے دھوئے گا، اور ناپاک رہے گا جب تک کہ وہ نہ ہو۔\n41۔ اور جو بھی رینگنے والی چیز زمین پر رینگتی ہے {وہ مکروہ ہوگی}؛ اسے نہیں کھایا جائے گا۔\n42۔ جو بھی پیٹ پر جائے، اور جو چاروں پر جائے، یا جو بھی زمین پر رینگنے والی جانداروں میں سے اس سے زیادہ پاؤں رکھتا ہو، اسے تم نہیں کھاؤ گے؛ کیونکہ وہ ایک مکروہ مخلوق ہیں۔ {hath...: عبرانی۔ پاؤں کو بڑھاتا ہے}\n43. تم خود کو کسی رینگنے والی چیز سے ناپاک نہیں کرو گے جو رینگتی ہو، اور نہ ہی اپنے آپ کو ان سے ناپاک کرو گے تاکہ تم اس سے ناپاک ہو جاؤ۔ {تم لوگ خود ہی نفرت انگیز ہو: ہیب۔ آپ کی روحیں وغیرہ}\n44۔ کیونکہ میں آپ کا خدا ہوں: اس لیے آپ خود کو پاک کریں گے، اور آپ پاک ہوں گے؛ کیونکہ میں {پاک} ہوں: تم خود کو زمین پر رینگنے والی کسی بھی چیز سے آلودہ نہیں کرو گے۔\n45. کیونکہ میں وہ خداوند ہوں جو تمہیں مصر کی سرزمین سے نکالتا ہے، تاکہ وہ تمہارا خدا بن جائے: اس لیے تم پاک رہو گے، کیونکہ میں پاک ہوں۔\n46. یہ جانوروں کا قانون ہے، پرندوں کا، اور ہر جاندار کا جو پانیوں میں حرکت کرتی ہے، اور ہر اس مخلوق کا جو زمین پر رینگتی ہے:\n47۔ ناپاک اور پاک کے درمیان فرق کرنا، اور اس جانور کے درمیان جو کھایا جا سکتا ہے اور جو نہیں کھایا جا سکتا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل سے فرماو، اگر عورت نے اولاد پیدا کی اور مرد پیدا کیا تو سات دن ناپاک رہے گی؛ اس کی بیماری کے لیے جدائی کے دنوں کے مطابق وہ ناپاک ہوگی۔\n3۔ اور آٹھویں دن اس کی پیشاب کی کھال کا گوشت ختنہ کیا جائے گا۔\n4۔ اور پھر وہ اپنے پاک کرنے والے خون میں تیس دن تک جاری رکھے گی؛ وہ مقدس چیز کو چھوئے گی نہیں، نہ مقدس میں آئے گی، جب تک کہ اس کی پاکیزگی کے دن پورے نہ ہو جائیں۔\n5۔ لیکن اگر وہ کنواری بچے کو جنم دے تو وہ دو ہفتے ناپاک رہے گی، جیسے اس کی جدائی میں: اور وہ اپنے پاک کرنے والے تین سو چھ دن کے خون میں زندہ رہے گی۔\n6۔ اور جب اس کی پاکیزگی کے دن پورے ہوں، تو بیٹے یا بیٹی کے لیے، وہ پہلے سال کا ایک میمنہ جلانے کی قربانی کے لیے اور ایک نوجوان کبوتر یا کبوتر کو گناہ کی قربانی کے طور پر جماعت کے خیمہ کے دروازے پر، پادری کے پاس لے آئے گی: {پہلے...:  عبرانی۔ اپنے سال کا بیٹا}\n7۔ جو اسے خداوند کے سامنے پیش کرے گا، اور اس کے لیے کفارہ کرے گا؛ اور اسے اس کے خون کی اولاد سے پاک کیا جائے گا۔ یہ {یہ} قانون ہے اس کے لیے جس نے مرد یا عورت پیدا کی ہو۔\n8۔ اور اگر وہ بکرہ نہ لا سکے، تو دو کچھوے یا دو نوجوان کبوتر لائے گی؛ ایک جلنے والی قربانی کے لیے، اور دوسرا گناہ کی قربانی کے لیے: اور پادری اس کے لیے کفارہ کرے گا، اور وہ پاک ہو جائے گی۔ {وہ ہو...: عبرانی۔ اس کا ہاتھ کافی نہیں تھا}","1۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n2۔ جب کسی آدمی کی جلد میں ایک ابھار، زخم یا روشن دھبہ ہو، اور وہ اس کے گوشت کی جلد میں ہو {جیسے کوڑھ کی وبا}؛ پھر اسے ہارون کاہن کے پاس یا اس کے کسی بیٹے کے پاس لایا جائے گا: {اٹھنا: یا، سوجنا}\n3۔ اور پادری وبا کو گوشت کی جلد میں دیکھے گا: اور جب طاعون کے بال سفید ہو جائیں گے، اور وبا نظر آئے گی جو اس کے گوشت کی کھال سے بھی گہری ہو، تو وہ کوڑھ کی وبا ہے: اور پادری اسے دیکھے گا اور اسے ناپاک قرار دے گا۔\n4۔ اگر روشن دھبہ اس کے گوشت کی جلد میں سفید ہو، اور نظر آ رہا ہو جلد سے زیادہ گہرا نہ ہو، اور اس کے بال سفید نہ ہوں؛ پھر پادری سات دن تک وبا کو خاموش کر دے گا:\n5۔ اور پادری ساتویں دن اسے دیکھے گا: اور دیکھو، {اگر} اس کی نظر میں وبا رک جائے، {اور} وبا جلد میں نہ پھیلے؛ پھر پادری اسے سات دن مزید بند کر دے گا:\n6۔ اور پادری ساتویں دن اسے دوبارہ دیکھے گا: اور دیکھو، {اگر} وبا {تھوڑی} سیاہ ہو جائے، {اور} وبا جلد میں نہ پھیلے، تو پادری اسے پاک قرار دے گا: یہ {تو} ایک زخم ہے: اور وہ اپنے کپڑے دھوئے گا، اور صاف ہوگا۔\n7۔ لیکن اگر زخم جلد میں بہت پھیل جائے، تو جب وہ پادری کو صفائی کے لیے دیکھ لیا جائے، تو وہ دوبارہ پادری کے پاس نظر آئے گا:\n8. اور اگر پادری دیکھے کہ کھال میں زخم پھیل گیا ہے، تو پادری اسے ناپاک قرار دے گا: یہ کوڑھ ہے۔\n9۔ جب کوڑھ کی وبا کسی انسان میں ہو، تو اسے پادری کے پاس لایا جائے گا؛\n10۔ اور پادری دیکھے گا {اسے}: اور دیکھو، {اگر} ابھرنے والا {جلد} سفید ہو جائے اور اس نے بال سفید کر دیے ہوں، اور {ابھرتے ہوئے} تیز کچا گوشت ہوگا؛ {جلدی...: عبرانی۔ زندہ گوشت کی زندگی}\n11. یہ اس کی جلد میں ایک پرانا کوڑھ ہے، اور پادری اسے ناپاک قرار دے گا، اور اسے خاموش نہیں کرے گا: کیونکہ وہ ناپاک ہے۔\n12۔ اور اگر کوڑھ کی جلد میں پھیل جائے، اور کوڑھ اس کی تمام جلد کو ڈھانپ لے جس کے سر سے اس کے پاؤں تک ہو، جہاں بھی پادری دیکھے؛\n13۔ پھر پادری غور کرے گا: اور دیکھو، {اگر} کوڑھ نے اس کے جسم کو ڈھانپ لیا ہے، تو وہ {وبا} کو پاک قرار دے گا: سب سفید ہو گیا ہے: وہ {پاک} ہے۔\n14۔ لیکن جب اس میں کچا گوشت ظاہر ہوتا ہے تو وہ ناپاک ہو جاتا ہے۔\n15۔ اور پادری کچا گوشت دیکھے گا اور اسے ناپاک قرار دے گا: {کیونکہ کچا گوشت {ناپاک ہے}: یہ {کوڑھ} ہے۔\n16۔ یا اگر کچا گوشت دوبارہ بدل جائے اور سفید ہو جائے، تو وہ پادری کے پاس آئے گا؛\n17۔ اور پادری اسے دیکھے گا: اور دیکھو، {اگر} وبا سفید ہو جائے؛ پھر پادری {وبا} کو پاک قرار دے گا: وہ {ہے} پاک ہے۔\n18۔ وہ گوشت بھی، جس میں {حتی} اس کی جلد میں پھوڑا تھا، اور وہ شفا پاتا ہے،\n19۔ اور ابال کی جگہ ایک سفید ابھار یا روشن دھبہ ہو، جو سفید اور کچھ حد تک سرخی مائل ہو، اور اسے پادری کو دکھایا جائے؛\n20۔ اور اگر جب پادری اسے دیکھے، تو دیکھو کہ وہ جلد سے نیچے نظر آ رہا ہے، اور اس کے بال سفید ہو جاتے ہیں؛ پادری اسے ناپاک قرار دے گا: یہ کوڑھ کی وبا ہے جو پھوڑے سے نکلی ہے۔\n21. لیکن اگر پادری اسے دیکھے اور دیکھے کہ اس میں سفید بال نہیں ہیں، اور اگر وہ جلد سے نیچے نہ ہو، بلکہ کچھ گہرے ہوں؛ پھر پادری اسے سات دن کے لیے بند کر دے گا:\n22۔ اور اگر یہ جلد میں زیادہ پھیل جائے تو پادری اسے ناپاک قرار دے گا: یہ وبا ہے۔\n23. لیکن اگر روشن نقطہ اس کی جگہ رہے، {اور} نہ پھیلے، تو وہ جلتا ہوا پھوڑا ہے؛ اور پادری اسے پاک قرار دے گا۔\n24۔ یا اگر {کو} گوشت ہو، جس کی جلد {میں} گرم جلن ہو، اور جلنے والا {گوشت} سفید روشن دھبہ ہو، جو کچھ سرخی مائل یا سفید ہو؛ {ایک گرم...: عبوری۔ آگ کی جلن}\n25۔ پھر پادری اسے دیکھے گا: اور دیکھیں، {اگر} روشن دھبے کے بال سفید ہو جائیں اور وہ جلد سے بھی گہرا نظر آئیں؛ یہ ایک کوڑھ ہے جو جلنے سے نکلا ہے: اسی لیے پادری اسے ناپاک قرار دے گا: یہ کوڑھ کی وبا ہے۔\n26. لیکن اگر پادری اسے دیکھے، اور دیکھے، {روشن دھبے میں} سفید بال نہیں ہیں، اور وہ {دوسرے} کی جلد سے نیچے نہیں بلکہ {تھوڑے} سیاہ ہوں؛ پھر پادری اسے سات دن کے لیے بند کر دے گا:\n27۔ اور پادری ساتویں دن اسے دیکھے گا: {اور} اگر یہ جلد میں بہت پھیل جائے تو پادری اسے ناپاک قرار دے گا: یہ کوڑھ کی وبا ہے۔\n28۔ اور اگر روشن دھبہ اس کی جگہ پر رہے، {اور} جلد میں نہ پھیلے، بلکہ کچھ گہرا ہو جائے؛ یہ جلنے کا عروج ہے، اور پادری اسے پاک قرار دے گا: کیونکہ یہ جلنے کی سوزش ہے۔\n29۔ اگر کسی مرد یا عورت کے سر یا داڑھی پر وبا ہو؛\n30۔ پھر پادری وبا کو دیکھے گا: اور دیکھو، اگر وہ جلد سے بھی گہری نظر آ رہی ہے؛ {اور وہاں} اس میں ایک پیلا پتلا بال ہے؛ پھر پادری اسے ناپاک قرار دے گا: یہ خشک زخم ہے، سر یا داڑھی پر جذام بھی۔\n31۔ اور اگر پادری سکال کی وبا کو دیکھے، اور دیکھے کہ وہ جلد سے زیادہ گہری نظر نہیں آتی، اور اس میں کوئی کالا بال نہیں ہے؛ پھر پادری سات دن کے لیے اس شخص کو بند کرے گا جس نے سکال کی وبا دیکھی ہے:\n32۔ اور ساتویں دن پادری طاعون کو دیکھے گا: اور دیکھو، {اگر} سبیل نہ پھیلے، اور اس میں پیلا بال نہ ہو، اور سکال {چمڑے سے گہرا} نظر نہ آئے؛\n33۔ اسے شیو کیا جائے گا، لیکن بال کو شیو نہیں کیا جائے گا؛ اور پادری سات دن مزید خاموش کرے گا {جس کے پاس سکال ہے}:\n34۔ اور ساتویں دن پادری سکے کو دیکھے گا: اور دیکھو، {اگر} سکال جلد میں پھیلا ہوا نہ ہو، نہ ہی جلد سے گہرا نظر آئے؛ پھر پادری اسے پاک قرار دے گا: اور وہ اپنے کپڑے دھوئے گا، اور صاف ہوگا۔\n35۔ لیکن اگر صفائی کے بعد سبیل جلد میں زیادہ پھیل جائے؛\n36۔ پھر پادری اسے دیکھے گا: اور دیکھو، اگر سکال جلد میں پھیل جائے تو پادری پیلے بال نہیں تلاش کرے گا؛ وہ ناپاک ہے۔\n37۔ لیکن اگر وہ سکال اس کی نظر میں ہو، اور {وہ} وہاں سیاہ بال اگ رہے ہوں؛ سکال شفا پاتا ہے، وہ {پاک} ہوتا ہے: اور پادری اسے پاک قرار دے گا۔\n38۔ اگر مرد یا عورت کی جلد میں بھی چمکدار دھبے ہوں، حتیٰ کہ سفید روشن دھبے بھی؛\n39۔ پھر پادری دیکھے گا: اور دیکھو، {اگر} ان کے گوشت کی جلد میں روشن دھبے گہرے سفید ہوں؛ یہ ایک جھریوں والا دھبہ ہے جو جلد میں اگتا ہے؛ وہ صاف ستھرا ہے۔\n40۔ اور جس آدمی کے بال اس کے سر سے جھڑے ہوں، وہ گنجا ہے؛ {پھر بھی} وہ صاف ستھرا ہے۔ {بال...: عبوری۔ سر کھول دیا گیا ہے}\n41۔ اور جس کے بال سر کے حصے سے چہرے کی طرف گرے ہوں، وہ ماتھا گنجا ہے: پھر بھی وہ صاف ہے۔\n42۔ اور اگر گنجے سر یا گنجے ماتھے میں سفید سرخی مائل زخم ہو؛ یہ اس کے گنجے سر یا گنجے ماتھے میں جذام کی بیماری ہے۔\n43۔ پھر پادری اسے دیکھے گا: اور دیکھو، {اگر} زخم کا اٹھنا اس کے گنجے سر یا گنجے ماتھے میں سفید سرخی مائل ہو جائے، جیسے کوڑھ گوشت کی جلد میں ظاہر ہوتا ہے؛\n44۔ وہ کوڑھ کا مریض ہے، وہ ناپاک ہے: پادری اسے مکمل طور پر ناپاک قرار دے گا؛ اس کی وبا {ہے} اس کے دماغ میں۔\n45۔ اور جس کوڑھ میں وبا ہے، اس کے کپڑے پھٹے جائیں گے، اس کا سر ننگا ہوگا، اور وہ اپنے اوپری ہونٹ پر چادر ڈالے گا اور پکارے گا، ناپاک، ناپاک۔\n46۔ وہ تمام دن جب وبا اس میں ہوگی، وہ ناپاک ہوگا؛ وہ ناپاک ہے: وہ اکیلا رہے گا؛ کیمپ کے بغیر {ہو گا} اس کی رہائش {ہوگی}۔\n47۔ وہ لباس بھی جس میں کوڑھ کی وبا ہے، {چاہے وہ اون کا لباس ہو یا لینن کا لباس؛\n48۔ چاہے وہ وارپ میں ہو، یا بھونک؛ لینن یا اون کے؛ چاہے جلد میں ہو، یا کسی بھی جلد کی چیز میں؛ {thing...: عبرانی کام\n49۔ اور اگر طاعون لباس میں سبز یا سرخ مائل ہو، یا جلد میں، چاہے وہ وارپ میں ہو، یا ووف میں، یا کسی بھی جلد میں ہو؛ یہ کوڑھ کی وبا ہے، اور اسے پادری کو دکھایا جائے گا: {چیز: عبرانی۔ برتن، یا، آلہ}\n50۔ اور پادری وبا کو دیکھے گا، اور سات دن کے لیے وبا کو خاموش رکھے گا:\n51۔ اور وہ ساتویں دن طاعون کو دیکھے گا: اگر وبا لباس میں پھیلی ہو، چاہے وہ وارپ میں، یا بھونک میں، یا کسی کھال میں، {یا} کسی بھی کھال کے کام میں؛ وبا ایک پریشان کن کوڑھ ہے؛ یہ {ناپاک} ہے۔\n52. لہٰذا وہ اس لباس، چاہے وہ وارپ ہو یا ووف، اون یا کپڑے یا کسی بھی جلد کی چیز میں جس میں طاعون ہو، جلا دے گا: کیونکہ یہ ایک پریشان کن کوڑھ ہے؛ یہ آگ میں جل جائے گا۔\n53۔ اور اگر پادری دیکھے، اور دیکھے، تو وبا لباس میں نہ پھیل جائے، نہ وارپ میں، نہ بھونک میں، نہ کسی کھال میں؛\n54۔ پھر پادری حکم دے گا کہ وہ اس چیز کو دھو لیں جس میں وبا ہے، اور اسے سات دن مزید بند کر دے گا:\n55۔ اور پادری طاعون کو دیکھے گا، جب وہ دھو جائے گی: اور دیکھو، {اگر} طاعون نے اپنا رنگ نہیں بدلا، اور وبا نہ پھیلے؛ یہ {ہے} ناپاک ہے؛ تم اسے آگ میں جلاؤ گے؛ یہ اندرونی طور پر فکر مند ہے، چاہے وہ اندر سے ننگا ہو یا باہر۔ {کیا...: عبرانی چاہے وہ سر میں گنجا ہو، یا اس کے ماتھے پر}\n56۔ اور اگر پادری دیکھے، اور دیکھے، طاعون دھونے کے بعد کچھ سیاہ ہو جائے؛ پھر وہ اسے لباس سے، یا جلد سے، یا وارپ سے، یا بھونک سے پھاڑ دے گا:\n57۔ اور اگر وہ لباس میں ابھی بھی نظر آئے، چاہے وہ وارپ میں، یا ووف میں، یا کسی بھی جلد کی چیز میں؛ یہ ایک پھیلتی ہوئی وبا ہے: جس میں وبا ہے اسے آگ سے جلا دو۔\n58۔ اور وہ لباس، چاہے وہ وارپ ہو یا بھونک، یا جو بھی جلد کا ہو، جسے تم دھوؤ گے، اگر وبا ان سے دور ہو جائے تو وہ دوسری بار دھویا جائے گا اور صاف ہوگا۔\n59. یہ کوڑھ کی وبا کا قانون ہے جو اون یا لینن کے لباس میں، چاہے وہ وارپ ہو، ووف ہو، یا کسی بھی کھال کی چیز میں ہو، اسے پاک قرار دینے یا ناپاک قرار دینے کے لیے۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2. یہ کوڑھی کا قانون ہوگا جب وہ پاک ہو جائے گا: اسے پادری کے پاس لایا جائے گا:\n3۔ اور پادری کیمپ سے باہر جائے گا؛ اور پادری دیکھے گا، اور دیکھے گا، اگر کوڑھ کی وبا کوڑھ کے مریض میں شفا پا رہی ہو؛\n4۔ پھر پادری حکم دے گا کہ جو پاک کیا جانا ہے اس کے لیے دو پرندے زندہ {اور} صاف، دیودار کی لکڑی، سرخ اور بھونسا لے جائے: {پرندے: یا چڑیا}\n5۔ اور پادری حکم دے گا کہ ان میں سے ایک پرندے کو بہتے پانی پر مٹی کے برتن میں مارا جائے:\n6۔ جہاں تک زندہ پرندے کا تعلق ہے، وہ اسے لے گا، دیودار کی لکڑی، اور سرخ پھیپھ، اور انہیں اور زندہ پرندے کو اس پرندے کے خون میں ڈبو دے گا جو بہتے پانی پر مارا گیا تھا:\n7۔ اور وہ جذام سے پاک ہونے والے پر سات بار چھڑکے، اسے پاک قرار دے گا، اور زندہ پرندہ کھلے میدان میں چھوڑ دے گا۔ {میں...: عبرانی میں۔ میدان کے چہرے پر}\n8۔ اور جو پاک ہونا ہے وہ اپنے کپڑے دھوئے گا، اپنے تمام بال منڈوا دے گا، اور خود کو پانی میں دھوئے گا تاکہ وہ پاک ہو جائے: اور اس کے بعد وہ کیمپ میں آئے گا، اور سات دن اپنے خیمے سے باہر رہے گا۔\n9۔ لیکن ساتویں دن وہ اپنے سر اور داڑھی اور بھنوؤں کے سارے بال منڈوا دے گا، اور اپنے کپڑے دھوئے گا، اور اپنے گوشت کو پانی سے دھوئے گا اور پاک ہو جائے گا۔\n10۔ اور آٹھویں دن وہ دو بغیر داغ کے بھیڑ، پہلے سال کی ایک بھیڑ کا بکر، اور تین دسویں سودے عمدہ آٹے کے لیے، تیل کے ساتھ ملا کر، اور ایک لکڑی تیل کے لیے۔ {میں سے...: عبرانی۔ اپنے سال کی بیٹی}\n11۔ اور وہ پادری جو {اسے} کو پاک کرے گا، وہ اس شخص کو اور وہ چیزیں خداوند کے سامنے پیش کرے گا، جو جماعت کے خیمہ کے دروازے پر ہے:\n12۔ اور پادری ایک برہ لے کر اسے جرم کی قربانی اور تیل کا لکڑی پیش کرے گا، اور انہیں خداوند کے سامنے لہرانے کے لیے لہرائے گا:\n13۔ اور وہ بکری کو اس جگہ ذبح کرے گا جہاں وہ گناہ کی قربانی اور جلنے والی قربانی کو مارے گا، مقدس جگہ پر: کیونکہ جیسے گناہ کی قربانی پادری کی ہے، ویسے ہی جرم کی قربانی بھی ہے: یہ سب سے مقدس ہے:\n14۔ اور پادری جرم کی قربانی کے خون کا {کچھ} لے گا، اور پادری اسے اس کے دائیں کان کی نوک، اپنے دائیں ہاتھ کے انگوٹھے پر، اور اپنے دائیں پاؤں کے بڑے پیر پر رکھے گا:\n15۔ اور پادری تیل کے لکڑی کا {کچھ} لے کر اپنے بائیں ہاتھ کی ہتھیلی میں ڈالے گا:\n16۔ اور پادری اپنی دائیں انگلی کو اپنے بائیں ہاتھ کے تیل میں ڈبوئے، اور خدا کے سامنے سات بار اپنی انگلی سے تیل چھڑکے:\n17۔ اور باقی تیل جو اس کے ہاتھ میں ہے، پادری اس کے دائیں کان کی نوک پر، اپنے دائیں ہاتھ کے انگوٹھے پر، اور اپنے دائیں پاؤں کی بڑی انگلی پر، خلاف ورزی کی قربانی کے خون پر رکھے گا:\n18۔ اور جو تیل پادری کے ہاتھ میں ہے، وہ اس کے سر پر ڈالے گا جسے پاک کیا جانا ہے: اور پادری اس کے لیے خداوند کے سامنے کفارہ کرے گا۔\n19۔ اور پادری گناہ کی قربانی پیش کرے گا، اور اس کے لیے کفارہ کرے گا جسے اس کی ناپاکی سے پاک کیا جانا ہے؛ اور اس کے بعد وہ سلائی ہوئی قربانی کو قتل کرے گا:\n20۔ اور پادری جلنے کی قربانی اور گوشت کی قربانی قربان گاہ پر پیش کرے گا: اور پادری اس کے لیے کفارہ کرے گا، اور وہ پاک ہو جائے گا۔\n21۔ اور اگر وہ غریب ہو اور اتنا حاصل نہ کر سکے؛ پھر وہ ایک بکری کے لیے ایک بکری لے گا جو اس کے لیے کفارہ کے لیے لہرانے کے لیے ہے، اور گوشت کی قربانی کے طور پر تیل کے ساتھ ملا ہوا ایک دسواں حصہ اور تیل کا ایک لکڑی لے گا؛ {نہیں کر سکتا...: عبرانی۔ اس کا ہاتھ نہیں پہنچتا} {ہونے...: عبرانی۔ ہاتھ ہلانے کے لیے}\n22۔ اور دو ٹرٹل ڈووز، یا دو نوجوان کبوتر، جتنے وہ حاصل کر سکتا ہے؛ اور ایک گناہ کی قربانی ہوگی، اور دوسری جلتی ہوئی قربانی۔\n23۔ اور وہ انہیں آٹھویں دن اپنی صفائی کے لیے پادری کے پاس لے جائے گا، جماعت کے خیمہ کے دروازے پر، خداوند کے سامنے۔\n24۔ اور پادری جرم کی قربانی کا برہ اور تیل کا لکڑی لے گا، اور پادری انہیں خداوند کے سامنے لہرانے کے لیے لہرائے گا:\n25۔ اور وہ جرم کی قربانی کے برہ کو قتل کرے گا، اور پادری جرم کی قربانی کے خون کا کچھ حصہ لے کر اس کے دائیں کان کے نوکے، اپنے دائیں ہاتھ کے انگوٹھے پر، اور اپنے دائیں پاؤں کی بڑی انگلی پر رکھے گا:\n26۔ اور پادری تیل کو اپنے بائیں ہاتھ کی ہتھیلی میں ڈالے گا:\n27۔ اور پادری اپنی دائیں انگلی سے اپنے بائیں ہاتھ میں موجود تیل کا {کچھ} سات بار خداوند کے سامنے چھڑکے:\n28۔ اور پادری اپنے ہاتھ میں موجود تیل سے اس کے دائیں کان کے نوکے، اپنے دائیں ہاتھ کے انگوٹھے پر، اور اپنے دائیں پاؤں کے بڑے انگوٹھے پر، جرم کی قربانی کے خون کی جگہ پر رکھے گا:\n29۔ اور باقی تیل جو پادری کے ہاتھ میں ہے، وہ اس کے سر پر لگائے گا جسے پاک کیا جانا ہے، تاکہ خداوند کے سامنے اس کا کفارہ ہو۔\n30۔ اور وہ کبوتر یا نوجوان کبوتروں میں سے ایک کو جو مل سکے پیش کرے گا؛\n31۔ {حتیٰ کہ} جو وہ حاصل کر سکتا ہے، ایک {گناہ کی قربانی} کے لیے، اور دوسرا {جلنے کی قربانی} کے لیے، گوشت کی قربانی کے ساتھ: اور پادری اس کے لیے کفارہ کرے گا جسے خداوند کے سامنے پاک ہونا ہے۔\n32. یہ {ہے} اس کا قانون {ہے} جس میں {ہے} کوڑھ کی وبا، جس کے ہاتھ کو {جو اس کی پاکیزگی سے متعلق ہے} حاصل کرنے کے قابل نہیں۔\n33۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n34۔ جب تم کنعان کی زمین میں آؤ، جسے میں تمہیں ملکیت کے لیے دیتا ہوں، اور میں کوڑھ کی وبا تمہاری ملکیت کے گھر میں ڈال دوں؛\n35۔ اور جو گھر کا مالک ہے وہ آ کر پادری کو بتائے گا، کہہ دے، مجھے لگتا ہے کہ گھر میں وبا ہے:\n36۔ پھر پادری حکم دے گا کہ وہ گھر خالی کر دیں، اس سے پہلے کہ پادری وبا کو دیکھنے جائے، تاکہ گھر میں جو کچھ بھی ہے اسے ناپاک نہ کیا جائے: اور اس کے بعد پادری گھر دیکھنے جائے گا: {خالی: یا، تیار کرو}\n37. اور وہ طاعون کو دیکھے گا، اور دیکھے گا {اگر} وبا گھر کی دیواروں میں کھوکھلی پٹیوں کے ساتھ ہے، سبز یا سرخ، جو دیوار سے نیچے نظر آتی ہیں؛\n38۔ پھر پادری گھر سے باہر گھر کے دروازے تک جائے گا، اور سات دن کے لیے گھر بند کرے گا:\n39۔ اور پادری ساتویں دن دوبارہ آئے گا، اور دیکھے گا: اور دیکھو، {اگر} وبا گھر کی دیواروں میں پھیل گئی ہے؛\n40۔ پھر پادری حکم دے گا کہ وہ وہ پتھر ہٹا دیں جن میں وبا ہے، اور انہیں شہر کے بغیر ایک ناپاک جگہ پر پھینک دیں:\n41۔ اور وہ گھر کو آس پاس کے اندر کھردرا کر دے گا، اور وہ جو گرد شہر کے باہر نکالتے ہیں اسے ناپاک جگہ میں بہا دیں گے:\n42۔ اور وہ دوسرے پتھر لے کر ان پتھروں کی جگہ رکھیں گے؛ اور وہ دوسرا مورٹر لے کر گھر کو تباہ کرے گا۔\n43۔ اور اگر طاعون دوبارہ آئے اور گھر میں پھیل جائے، تو اس کے بعد اس نے پتھر ہٹا دیے، اور گھر کو کھرچ دیا، اور جب اسے چٹا دیا جائے؛\n44۔ پھر پادری آئے گا اور دیکھے گا، اور دیکھو، {اگر} طاعون گھر میں پھیل جائے تو یہ گھر میں ایک پریشان کن کوڑھ ہے: یہ {ناپاک} ہے۔\n45۔ اور وہ گھر، اس کے پتھر، اس کے لکڑی اور گھر کے تمام مورٹر کو توڑ دے گا؛ اور وہ انہیں شہر سے نکال کر ایک ناپاک جگہ لے جائے گا۔\n46۔ مزید برآں، جو گھر بند رہتے ہوئے اندر جاتا ہے، وہ شام تک ناپاک ہوگا۔\n47۔ اور جو گھر میں لیٹتا ہے وہ اپنے کپڑے دھوئے گا؛ اور جو گھر میں کھاتا ہے وہ اپنے کپڑے دھوئے گا۔\n48۔ اور اگر پادری اندر آئے اور اسے دیکھے، اور دیکھے کہ طاعون گھر میں پھیل نہیں گئی، جب کہ گھر کو نقصان پہنچایا گیا، تو پادری گھر کو پاک قرار دے گا، کیونکہ طاعون شفا پا چکی ہے۔ {آئے گا...: عبرانی۔ آنے میں آئے گا، وغیرہ}\n49۔ اور وہ گھر کو صاف کرنے کے لیے دو پرندے، دیودار کی لکڑی، سرخ اور ہسپ لے جائے گا:\n50۔ اور وہ مٹی کے برتن میں بہتے پانی پر پرندوں میں سے ایک کو مار ڈالے گا:\n51۔ اور وہ دیودار کی لکڑی، اور ہسپ، سرخ اور زندہ پرندے کو لے کر انہیں شے ہوئے پرندے کے خون میں ڈبوئے، اور بہتے پانی میں بھی، اور گھر پر سات بار چھڑکے:\n52۔ اور وہ پرندے کے خون، بہتے پانی سے، زندہ پرندے سے، دیودار کی لکڑی، ہسپ سے اور سرخ سے گھر کو صاف کرے گا:\n53۔ لیکن وہ زندہ پرندے کو شہر سے باہر کھلے میدانوں میں چھوڑ دے گا، اور گھر کے لیے کفارہ بنائے گا، اور وہ صاف ہو جائے گا۔\n54. یہ ہر قسم کی کوڑھ کی وبا اور سکال کے لیے قانون ہے،\n55۔ اور لباس اور گھر کے کوڑھ کے لیے،\n56۔ اور ایک ابھرنے کے لیے، اور ایک زخم کے لیے، اور ایک روشن مقام کے لیے:\n57. یہ سکھانا کہ کب {یہ} ناپاک ہے، اور جب {یہ} پاک ہے: یہ {ہے} کوڑھ کا قانون۔ {جب یہ ناپاک ہو...: عبرانی۔ ناپاک کے دن میں، اور پاکیزگی کے دن میں}","1۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n2۔ بنی اسرائیل سے بات کرو، اور ان سے کہو، جب کسی کے جسم سے اولاد ختم ہو، تو اس کی اولاد کی وجہ سے وہ ناپاک ہے۔ {دوڑنا...: یا، لگام دوڑانا}\n3۔ اور یہ اس کی ناپاکی ہوگی جو اس کے بچے میں ہوگی: چاہے اس کا جسم اس کی اولاد کے ساتھ ہو، یا اس کا جسم اس کی اولاد سے روکا جائے، یہ اس کی ناپاکی ہے۔\n4۔ ہر بستر جس پر وہ لیٹا ہو جس کے بچے ہیں، وہ ناپاک ہے؛ اور جس چیز پر وہ بیٹھا ہے، وہ ناپاک ہوگی۔ {بات: عبوری۔ جہاز}\n5۔ اور جو بھی اپنے بستر کو چھوئے گا، وہ اپنے کپڑے دھوئے، پانی میں نہائے گا، اور صبح تک ناپاک رہے گا۔\n6۔ اور جو شخص جس چیز پر بیٹھا ہے جس پر بیٹھا ہے اور جس کے بچے ہیں، وہ اپنے کپڑے دھوئے گا، اور پانی میں نہائے گا، اور ناپاک رہے گا جب تک کہ وہ شادی نہ کرے۔\n7۔ اور جو بچے کے جسم کو چھوئے گا، وہ اپنے کپڑے دھوئے گا، اور خود کو پانی میں نہائے گا، اور ناپاک ہو جائے گا جب تک کہ وہ شادی نہ کرے۔\n8۔ اور اگر جس کے پاس اولاد ہے وہ پاک پر تھوکے؛ پھر وہ اپنے کپڑے دھوئے گا، اور خود کو پانی میں نہائے گا، اور شام تک ناپاک رہے گا۔\n9۔ اور جس زین پر وہ سوار ہو اور جس کا رشتہ ہے، وہ ناپاک ہوگا۔\n10۔ اور جو بھی اپنے نیچے موجود کسی چیز کو چھوئے گا، وہ ناپاک ہوگا جب تک کہ وہ برابر نہ ہو جائے: اور جو ان میں سے کوئی چیز اٹھائے گا وہ اپنے کپڑے دھوئے گا، پانی میں نہائے گا اور ناپاک رہے گا جب تک کہ وہ برابر نہ ہو جائے۔\n11۔ اور جس کو وہ چھوئے گا جس کے پاس بچے ہوئے ہوں اور جس نے اپنے ہاتھ پانی میں نہ دھوئے، وہ اپنے کپڑے دھوئے گا، اور خود کو پانی میں نہلائے، اور ناپاک رہے گا جب تک کہ وہ شادی نہ کرے۔\n12۔ اور وہ مٹی کا برتن جسے وہ چھوئے گا اور جس کا رشتہ ہے، ٹوٹ جائے گا: اور ہر لکڑی کا برتن پانی میں دھویا جائے گا۔\n13۔ اور جب جس کے پاس اولاد ہو وہ اپنی اولاد سے پاک ہو جائے؛ پھر وہ اپنے لیے سات دن گنائے گا اپنی صفائی کے لیے، اپنے کپڑے دھوئے گا، اپنے گوشت کو بہتے پانی میں نہلائے گا، اور پاک ہو جائے گا۔\n14۔ اور آٹھویں دن وہ دو کبوتر یا دو نوجوان کبوتر لے کر خداوند کے سامنے جماعت کے خیمہ کے دروازے پر آئے گا، اور انہیں پادری کو دے گا:\n15۔ اور پادری انہیں پیش کرے گا، ایک {گناہ کی قربانی} کے لیے، اور دوسرا {جلنے کی قربانی} کے لیے؛ اور پادری اس کی اولاد کے لیے خداوند کے سامنے کفارہ کرے گا۔\n16۔ اور اگر کسی آدمی کا جنسی تعلق کا بیج اس سے نکل جائے، تو وہ اپنا سارا گوشت پانی میں دھوئے گا اور صبح تک ناپاک رہے گا۔\n17۔ اور ہر لباس اور ہر جلد جس پر جنسی تعلق کا بیج ہے، پانی سے دھویا جائے گا اور ناپاک ہو جائے گا جب تک کہ وہ برابر نہ ہو جائے۔\n18۔ وہ عورت جس کے ساتھ مرد جنسی تعلق کے بیج کے ساتھ سوئے گا، وہ دونوں پانی میں نہائیں گے، اور ناپاک ہوں گے جب تک کہ وہ برابر نہ ہو جائے۔\n19۔ اور اگر عورت کی اولاد ہو، {اور} اس کی اولاد اس کے جسم میں خون ہو، تو اسے سات دن کے لیے الگ رکھا جائے گا: اور جو بھی اسے چھوئے گا وہ ناپاک رہے گا جب تک کہ وقت نہ گزرے۔ {put...: عبدی۔ اپنی جدائی میں}\n20۔ اور جس چیز پر وہ اپنی جدائی میں لیٹے گی وہ ناپاک ہوگی؛ اور جس چیز پر وہ بیٹھی ہے وہ بھی ناپاک ہوگی۔\n21۔ اور جو بھی اس کے بستر کو چھوئے گا، وہ اپنے کپڑے دھوئے گا، اور خود کو پانی میں نہائے گا، اور صبح تک ناپاک رہے گا۔\n22۔ اور جو بھی اس چیز کو چھوئے جس پر وہ بیٹھی ہو، وہ اپنے کپڑے دھوئے گا، پانی میں نہائے گا، اور صبح تک ناپاک رہے گا۔\n23۔ اور اگر وہ {اس کی} بستر پر ہو، یا جس چیز پر وہ بیٹھی ہو، تو جب وہ اسے چھوئے گا، تو وہ صبح تک ناپاک رہے گا۔\n24۔ اور اگر کوئی مرد اس کے ساتھ سوئے، اور اس کے پھول اس پر ہوں، تو وہ سات دن کے لیے ناپاک ہوگا؛ اور جس بستر پر وہ لیٹا ہے وہ سب ناپاک ہوگا۔\n25۔ اور اگر کسی عورت کے خون کی اولاد اس کی جدائی کے وقت کے کئی دنوں بعد ہو، یا اگر وہ اس کی جدائی کے وقت سے زیادہ ہو؛ اس کی ناپاکی کے تمام دن اس کی جدائی کے دنوں کی طرح ہوں گے: وہ ناپاک ہو جائے گی۔\n26۔ ہر بستر جس پر وہ اپنی اولاد کے تمام دن لیٹے گی، وہ اس کے لیے اس کی جدائی کا بستر ہوگا: اور جس چیز پر وہ بیٹھی گی وہ ناپاک ہوگا، جیسے اس کی جدائی کی ناپاکی۔\n27۔ اور جو بھی ان چیزوں کو چھوئے گا وہ ناپاک ہوگا، اپنے کپڑے دھوئے گا، پانی میں نہائے گا اور ناپاک ہوگا جب تک کہ وقت نہ گزرے۔\n28۔ لیکن اگر وہ اپنی اولاد سے پاک ہو جائے تو وہ سات دن شمار کرے گی، اور اس کے بعد وہ پاک ہو جائے گی۔\n29۔ اور آٹھویں دن وہ اپنے دو کچھوؤں، یا دو نوجوان کبوتروں کو لے کر انہیں پادری کے پاس لے جائے گی، جو جماعت کے خیمہ کے دروازے پر ہے۔\n30۔ اور پادری ایک کو گناہ کی قربانی دے گا، اور دوسرا جلنے کی قربانی کے لیے؛ اور پادری اس کی ناپاکی کے معاملے پر خداوند کے سامنے اس کی کفارہ کرے گا۔\n31۔ یوں تم بنی اسرائیل کو ان کی ناپاکی سے جدا کرو گے؛ کہ وہ اپنی ناپاکی میں نہ مریں، جب وہ میرے خیمے کو ناپاک کریں جو ان میں سے ہے۔\n32. یہ اس شخص کا قانون ہے جس کی اولاد ہو، اور جس کی اولاد اس سے نکلی ہو اور اس سے آلودہ ہو جائے؛\n33۔ اور اس سے جو اپنے پھولوں سے بیمار ہے، اور جس کے پاس اولاد ہے، مرد سے، عورت سے، اور جو اس کے ساتھ ہے جو ناپاک ہے۔","1۔ اور خداوند نے موسیٰ سے بات کی جب ہارون کے دو بیٹوں کی موت ہوئی، جب انہوں نے خداوند کے سامنے پیشکش کی اور مر گئے؛\n2۔ اور خداوند نے موسیٰ سے کہا، اپنے بھائی ہارون سے بات کرو کہ وہ ہر وقت مقدس {مقام} میں نہ آئے، رحم کی نشست کے سامنے جو {تابوت} پر ہے؛ کہ وہ نہ مرے: کیونکہ میں بادل میں رحم کی نشست پر ظاہر ہوں گا۔\n3. یوں ہارون مقدس {جگہ} میں آئے گا: گناہ کی قربانی کے طور پر ایک نوجوان بیل کے ساتھ، اور جلنے کی قربانی کے طور پر ایک مینڈھ کے ساتھ۔\n4۔ وہ مقدس لینن کوٹ پہنے گا، اور اس کے جسم پر لینن کی پتلون پہنی جائے گی، اور لینن کی بیلٹ پہنی جائے گی، اور لینن مائتر پہنا جائے گا: یہ مقدس لباس ہیں؛ لہٰذا وہ اپنا گوشت پانی میں دھوئے گا، اور {یوں} انہیں پہنے گا۔\n5۔ اور وہ بنی اسرائیل کی جماعت سے بکریوں کے دو بچے گناہ کی قربانی کے طور پر اور ایک مینڈھا جلانے کی قربانی دے گا۔\n6۔ اور ہارون گناہ کی قربانی کا بیل پیش کرے گا، جو {اپنے لیے} ہے، اور اپنے اور اپنے گھر کے لیے کفارہ کرے گا۔\n7۔ اور وہ دو بکریاں لے کر جماعت کے خیمہ کے دروازے پر خداوند کے سامنے پیش کرے گا۔\n8۔ اور ہارون دو بکریوں پر قرعہ ڈالے گا؛ ایک حصہ خدا کے لیے، اور دوسرا قربانی کے بکرے کے لیے۔ {scapegoat: عبرانی۔ آزازل}\n9۔ اور ہارون وہ بکری لے آئے گا جس پر خداوند کا پلاٹ گرا تھا، اور اسے گناہ کی قربانی دے گا۔ {گرنا: عبرانی۔ اوپر چلا گیا}\n10۔ لیکن وہ بکری، جس پر قرعہ قربانی کا بکرا بننے کے لیے گرا، خداوند کے سامنے زندہ پیش کیا جائے گا، تاکہ اس سے کفارہ کرے، {اور} اسے قربانی کے بکرے کے طور پر صحرا میں جانے دے۔\n11۔ اور ہارون گناہ کی قربانی کا بیل لائے گا، جو {اپنے لیے} ہے، اور اپنے اور اپنے گھر کے لیے کفارہ بنائے گا، اور گناہ کی قربانی کا بیل جو {ہے} اپنے لیے مارے گا:\n12۔ اور وہ خداوند کے سامنے قربان گاہ سے جلتے ہوئے انگاروں سے بھرا ہوا ایک بخور لے گا، اور اپنے ہاتھوں سے میٹھا دھواں جو تھوڑا پھینٹا گیا ہو، اور اسے پردے کے اندر لے آئے گا:\n13۔ اور وہ اگربتی کو خدا کے سامنے آگ پر رکھے گا، تاکہ لوبان کا بادل اس رحمت کی نشست کو ڈھانپ دے جو گواہی پر ہے، تاکہ وہ نہ مرے:\n14۔ اور وہ بیل کے خون سے لے گا، اور اپنی انگلی سے اسے رحم کی نشست پر مشرق کی طرف چھڑکائے گا؛ اور رحمت کی نشست کے سامنے وہ اپنی انگلی سے سات بار خون چھڑکے۔\n15۔ پھر وہ گناہ کی قربانی کی بکری کو مارے گا، جو لوگوں کے لیے ہے، اور اپنا خون پردے میں لے آئے گا، اور اس خون سے ویسے ہی کرے گا جیسے اس نے بیل کے خون سے کیا، اور اسے رحم کی نشست پر اور رحم کی نشست کے سامنے چھڑکے:\n16۔ اور وہ مقدس جگہ کے لیے کفارہ کرے گا، بنی اسرائیل کی ناپاکی اور ان کے تمام گناہوں کی غلطیوں کی وجہ سے: اور وہ جماعت کے خیمہ کے لیے بھی کفارہ کرے گا، جو ان کی ناپاکی کے بیچ میں ان کے درمیان باقی ہیں۔ {باقی رہیں: عبرانی۔ dwelleth}\n17۔ اور جب وہ مقدس جگہ پر کفارہ دینے جائے تو جماعت کے خیمہ میں کوئی شخص نہیں ہوگا، جب تک کہ وہ باہر نہ آئے اور اپنے لیے، اپنے گھرانے کے لیے، اور اسرائیل کی تمام جماعت کے لیے کفارہ نہ کر لے۔\n18۔ اور وہ اس قربان گاہ پر جائے گا جو {ہے} خداوند کے حضور ہے، اور اس کا کفارہ کرے گا؛ اور بیل کے خون اور بکری کے خون سے لے کر ارد گرد قربان گاہ کے سینگوں پر لگا دے۔\n19۔ اور وہ اس پر سات بار اپنی انگلی سے خون چھڑکے، اسے صاف کرے گا اور بنی اسرائیل کی ناپاکی سے پاک کرے گا۔\n20۔ اور جب وہ مقدس جگہ، جماعت کے خیمہ اور قربان گاہ کی صلح کا خاتمہ کر لے، تو وہ زندہ بکری لے آئے گا:\n21۔ اور ہارون اپنے دونوں ہاتھ زندہ بکری کے سر پر رکھے گا، اور اس پر بنی اسرائیل کی تمام گناہوں اور ان کے تمام گناہوں کا اعتراف کرے گا، انہیں بکری کے سر پر رکھ دے گا، اور ایک قابل رحم آدمی کے ہاتھ سے بیابان میں بھیج دے گا:  {غصہ...: عبرانی مواقع کا آدمی}\n22۔ اور بکری اپنے تمام گناہوں کو اس زمین پر لے جائے گی جو آباد نہیں: اور وہ بکری کو بیابان میں چھوڑ دے گا۔ {نہیں...: ہیب۔ علیحدگی کی وجہ سے}\n23۔ اور ہارون جماعت کے خیمہ میں آئے گا، اور وہ کپڑے اتار دے گا جو اس نے مقدس جگہ میں جاتے وقت پہنے تھے، اور انہیں وہیں چھوڑ دے گا:\n24۔ اور وہ مقدس جگہ پر اپنے گوشت کو پانی سے دھوئے گا، اپنے کپڑے پہنے گا، اور باہر آئے گا، اپنی جلتی ہوئی قربانی اور لوگوں کی سلائی کی قربانی پیش کرے گا، اور اپنے لیے اور عوام کے لیے کفارہ کرے گا۔\n25۔ اور گناہ کی قربانی کی چربی وہ قربان گاہ پر جلائے گا۔\n26۔ اور جو بکری کو بکری کے لیے چھوڑے گا، وہ اپنے کپڑے دھوئے گا، اس کے گوشت کو پانی میں نہلائے، اور پھر کیمپ میں آئے گا۔\n27. اور بیل {گناہ کی قربانی} کے لیے، اور بکری {کے لیے} گناہ کی قربانی، جس کا خون مقدس {جگہ} میں کفارہ کے لیے لایا گیا تھا، {ایک} بغیر کیمپ کے لے جائے گا؛ اور وہ اپنی کھالیں اور گوشت اور گوبر کو آگ میں جلا دیں گے۔\n28۔ اور جو انہیں جلا دے گا وہ اپنے کپڑے دھوئے گا، اپنے گوشت کو پانی سے نہائے گا، اور پھر وہ کیمپ میں آئے گا۔\n29۔ اور {یہ} تمہارے لیے ہمیشہ کے لیے ایک حکم ہوگا: {کہ} ساتویں مہینے میں، مہینے کے دسویں دن، تم اپنی جانوں کو تکلیف دو گے، اور بالکل بھی کوئی کام نہیں کرو گے، {چاہے وہ تمہارے اپنے ملک کا کوئی ہو، یا کوئی اجنبی جو تم میں رہتا ہو:\n30۔ کیونکہ اس دن {پادری} تمہارے لیے کفارہ کرے گا، تمہیں پاک کرے گا، {تاکہ} تم خداوند کے سامنے اپنے تمام گناہوں سے پاک ہو جاؤ۔\n31. یہ آپ کے لیے سکون کا سبت ہوگا، اور آپ اپنی روحوں کو ہمیشہ کے لیے ایک قانون کے ذریعے تکلیف دیں گے۔\n32۔ اور وہ پادری، جسے وہ مسح کرے گا، اور جسے وہ اپنے باپ کی جگہ پادری کے عہدے میں خدمت کے لیے مقرر کرے گا، کفارہ کرے گا، اور لینن کے کپڑے بھی پہنے گا، {حتیٰ کہ} مقدس لباس بھی: {تقدیس: عبرانی۔ اس کا ہاتھ بھر دو}\n33۔ اور وہ مقدس مقام کے لیے کفارہ کرے گا، اور جماعت کے خیمے اور قربان گاہ کے لیے کفارہ کرے گا، اور وہ پادریوں اور جماعت کے تمام لوگوں کے لیے کفارہ کرے گا۔\n34۔ اور یہ تمہارے لیے ایک دائمی قانون ہوگا، تاکہ بنی اسرائیل کے لیے سال میں ایک بار ان کے تمام گناہوں کا کفارہ ہو۔ اور اس نے وہی کیا جو خداوند نے موسیٰ کو حکم دیا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ ہارون، اس کے بیٹوں سے، اور تمام بنی اسرائیل سے بات کرو، اور ان سے کہو؛ یہی وہ چیز ہے جسے خداوند نے حکم دیا ہے، کہتا ہے،\n3۔ جو بھی شخص اسرائیل کے گھرانے میں سے ہو، جو کیمپ میں بیل، بھیڑ یا بکری کو مارے، یا جو اسے کیمپ سے باہر مارے،\n4۔ اور اسے جماعت کے خیمے کے دروازے پر نہ لائے، تاکہ خداوند کے خیمہ کے سامنے نذرانہ پیش کرے؛ خون اس آدمی پر منسوب کیا جائے گا؛ اس نے خون بہایا ہے؛ اور انسان کو اس کے لوگوں سے الگ کر دیا جائے گا:\n5۔ تاکہ بنی اسرائیل اپنی قربانیاں کھلے میدان میں پیش کریں، یہاں تک کہ وہ انہیں خداوند کے سامنے، جماعت کے خیمہ کے دروازے پر، پادری کے پاس لے جا سکیں، اور انہیں خدا کے سامنے امن کی قربانیاں پیش کریں۔\n6۔ اور پادری خدا کے مذبح پر خون چھڑکائے گا {اجتماع کے خیمے کے دروازے پر}، اور چربی کو جلا کر خداوند کے لیے میٹھا ذائقہ دے گا۔\n7۔ اور وہ اب اپنی قربانیاں ان شیطانوں کو نہیں دیں گے جن کے پیچھے وہ بدکاری کر رہے ہیں۔ یہ ان کے لیے ہمیشہ کے لیے ایک قانون رہے گا، جو ان کی نسلوں تک جاری رہے گا۔\n8۔ اور تم ان سے کہو گے، جو بھی انسان اسرائیل کے گھرانے کا ہے، یا جو اجنبی تم میں رہتے ہیں اور جو قربانی یا قربانی پیش کرتے ہیں،\n9۔ اور اسے جماعت کے خیمے کے دروازے تک نہ لائے، تاکہ اسے خداوند کے سامنے پیش کرے؛ وہ انسان بھی اپنے لوگوں سے کٹ جائے گا۔\n10۔ اور جو بھی انسان اسرائیل کے گھرانے کا ہے، یا تمہارے درمیان رہنے والے اجنبی جو کوئی خون کھاتا ہے؛ میں اس روح کے خلاف بھی اپنا چہرہ رکھوں گا جو خون کھاتی ہے، اور اسے اس کے لوگوں سے کاٹ دوں گا۔\n11۔ کیونکہ جسم کی زندگی خون میں ہے: اور میں نے اسے تمہیں قربان گاہ پر دیا ہے تاکہ تمہاری روحوں کا کفارہ ہو: کیونکہ یہ خون ہے جو روح کے لیے کفارہ بناتا ہے۔\n12۔ اسی لیے میں نے بنی اسرائیل سے کہا، تم میں سے کوئی بھی خون نہیں کھائے گا، اور نہ ہی کوئی اجنبی جو تم میں رہتا ہے خون نہیں کھائے گا۔\n13۔ اور جو بھی انسان بنی اسرائیل میں سے ہے، یا جو اجنبی آپ میں رہتے ہیں، جو کسی بھی جانور یا مرغی کا شکار کرتے ہیں اور شکار کرتے ہیں جو کھایا جا سکتا ہے؛ وہ اس کا خون بھی انڈیل دے گا، اور اسے مٹی سے ڈھانپ دے گا۔ {جو کہ...: عبرانی جو کسی بھی شکار کا شکار کرتا ہے}\n14۔ کیونکہ {یہ} تمام جسم کی زندگی ہے؛ اس کا خون اس کی جان کے لیے ہے: اسی لیے میں نے بنی اسرائیل سے کہا، تم کسی گوشت کا خون نہیں کھاؤ گے: کیونکہ ہر جسم کی زندگی اس کا خون ہے: جو اسے کھائے گا اسے کاٹ دیا جائے گا۔\n15۔ اور ہر وہ روح جو اپنی موت یا جانوروں سے پھٹی ہوئی چیز کو کھاتی ہے، چاہے وہ تمہارے اپنے ملک کا ہو یا کوئی اجنبی ہو، وہ اپنے کپڑے دھوئے گا، پانی میں نہائے گا اور ناپاک رہے گا جب تک کہ وہ پاک نہ ہو جائے۔ {جو مر گیا...: عبرانی۔ ایک لاش}\n16۔ لیکن اگر وہ نہ دھوئے، نہ اپنے جسم کو نہلائے؛ پھر وہ اپنی گناہ برداشت کرے گا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل سے بات کرو، اور ان سے کہو، میں تمہارا خداوند خدا ہوں۔\n3۔ مصر کی سرزمین کے اعمال کے بعد، جہاں تم رہتے تھے، تم نہیں کرو گے: اور کنعان کی سرزمین کے اعمال کے بعد، جہاں میں تمہیں لے آؤں، تم نہیں کرو گے: نہ ہی ان کے احکامات پر چلو گے۔\n4۔ تم میرے فیصلے کرو گے، اور میرے احکامات کی پاسداری کرو گے، اس میں چلنا: میں خداوند تمہارا خدا ہوں۔\n5۔ لہٰذا تم میرے قوانین اور فیصلوں کی حفاظت کرو گے: جو اگر کوئی کرے گا تو وہ ان میں زندہ رہے گا: میں خداوند ہوں۔\n6۔ تم میں سے کوئی بھی اس کے قریبی رشتہ دار کے قریب نہ جائے تاکہ ان کی برہنگی ظاہر ہو: میں خداوند ہوں۔ {قریب...: عبرانی۔ اس کے گوشت کا باقی۔}\n7۔ تمہارے والد کی برہنگی یا اپنی ماں کی ننگانی، تم اسے ظاہر نہیں کرو گی: وہ تمہاری ماں ہے؛ تم اس کی برہنگی کو ظاہر نہیں کرو گے۔\n8۔ اپنے والد کی بیوی کی برہنگی کو تم ظاہر نہیں کرو گے: یہ تمہارے والد کی برہنگی ہے۔\n9۔ تمہاری بہن کی برہنگی کی، جو تمہارے والد کی بیٹی ہے، یا تمہاری ماں کی بیٹی، {چاہے وہ گھر میں پیدا ہوئی ہو یا بیرون ملک} پیدا ہو، {حتیٰ کہ} ان کی برہنگی کو تم ظاہر نہیں کرو گے۔\n10۔ اپنے بیٹے کی بیٹی یا بیٹی کی بیٹی کی برہنگی {حتیٰ کہ} ان کی برہنگی کو تم ظاہر نہیں کرو گے: کیونکہ ان کی اپنی برہنگی تمہاری ہے۔\n11۔ تمہارے والد کی بیوی کی بیٹی، جو تمہارے والد سے پیدا ہوئی ہے، وہ تمہاری بہن ہے، تو اس کی برہنگی ظاہر نہیں کرو گے۔\n12. تم اپنے والد کی بہن کی برہنگی کو ظاہر نہ کرو: وہ تمہارے والد کی قریبی رشتہ دار ہے۔\n13۔ تم اپنی ماں کی بہن کی برہنگی کو ظاہر نہ کرو، کیونکہ وہ تمہاری ماں کی قریبی رشتہ دار ہے۔\n14۔ تم اپنے والد کے بھائی کی برہنگی کو ظاہر نہیں کرو گے، اس کی بیوی کے قریب نہیں جاؤ گے: وہ تمہاری پھوپھی ہے۔\n15۔ تم اپنی بہو کی برہنگی کو ظاہر نہ کرو: وہ تمہارے بیٹے کی بیوی ہے؛ تم اس کی برہنگی کو ظاہر نہیں کرو گے۔\n16. تم اپنے بھائی کی بیوی کی برہنگی کو ظاہر نہ کرو: یہ تمہارے بھائی کی ننگی ہے۔\n17۔ تم عورت اور اس کی بیٹی کی برہنگی کو ظاہر نہیں کرو گے، نہ ہی اس کے بیٹے کی بیٹی یا اس کی بیٹی کو اس کی برہنگی ظاہر کرنے کے لیے لے جاؤ گے؛ {کیونکہ} وہ {ہیں} اس کی قریبی رشتہ داریں: یہ {ہے} برائی ہے۔\n18. نہ ہی تم اپنی بہن سے بیوی کو لے کر اسے تنگ کرو گے، اس کی برہنگی کو بے نقاب کرو گے، اس کی زندگی میں دوسرے کے ساتھ۔ {ایک بیوی...: یا، ایک بیوی سے دوسری بیوی}\n19۔ اور تم عورت کے پاس اس کی برہنگی ظاہر کرنے کے لیے نہیں جاؤ گے، جب تک کہ وہ اپنی ناپاکی کی وجہ سے الگ ہو جائے۔\n20۔ مزید برآں، تم اپنے پڑوسی کی بیوی کے ساتھ جسمانی تعلق قائم نہیں کرو گے تاکہ اس کے ساتھ خود کو ناپاک کر سکو۔\n21. اور تم اپنی نسل میں سے کسی کو آگ سے مولخ تک نہ جانے دینا، نہ ہی اپنے خدا کے نام کی بے حرمتی کرنا: میں خداوند ہوں۔ {مولیک: گری۔ مولوخ}\n22۔ تم انسانوں کے ساتھ نہ سوؤ، جیسے عورتوں کے ساتھ ہو: یہ {مکرہ} ہے۔\n23۔ نہ تو تم کسی جانور کے ساتھ سو کر خود کو ناپاک کرو گے، نہ ہی کوئی عورت جانور کے سامنے کھڑی ہو کر اس پر لیٹ جائے گی: یہ الجھن ہے۔\n24۔ ان میں سے کسی بھی چیز میں خود کو ناپاک نہ کریں: کیونکہ ان سب میں وہ قومیں ناپاک ہیں جنہیں میں نے آپ کے سامنے نکالا ہے:\n25۔ اور زمین ناپاک ہو جاتی ہے: اس لیے میں اس پر ظلم کرتا ہوں، اور زمین اپنے باشندوں کو قے کر دیتی ہے۔\n26۔ لہٰذا تم میرے قوانین اور فیصلوں کی حفاظت کرو گے، اور ان میں سے کوئی بھی گناہ نہیں کرو گے؛ نہ ہی آپ کی اپنی قوم کے کسی فرد کے، نہ ہی کوئی اجنبی جو آپ کے درمیان رہتا ہے:\n27۔ (کیونکہ یہ تمام گنایاں زمین کے لوگوں نے کی ہیں، جو تم سے پہلے تھے، اور زمین ناپاک ہو گئی ہے؛)\n28۔ کہ زمین تمہیں بھی نہ نکالے، جب تم اسے ناپاک کرو، جیسے اس نے ان قوموں کو جنم دیا جو تم سے پہلے تھیں۔\n29۔ جو بھی ان گناہوں میں سے کوئی کرے گا، حتیٰ کہ جو لوگ [انہیں} کریں گے، وہ بھی ان کے لوگوں میں سے کاٹ دی جائیں گی۔\n30۔ لہٰذا تم میرا حکم قائم رکھو گے، کہ تم ان گندی رسومات میں سے کوئی بھی نہ کرو جو تم سے پہلے ہوئیں، اور اپنے آپ کو اس میں ناپاک نہ کرو: میں تمہارا خداوند خدا ہوں۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل کی تمام جماعت سے بات کرو، اور ان سے کہو، تم پاک رہو گے: کیونکہ میں، خداوند تمہارا خدا، مقدس ہوں۔\n3۔ تم ہر آدمی، اس کی ماں اور اس کے والد سے ڈرو، اور میری سبت رکھنا: میں خداوند تمہارا خدا ہوں۔\n4. بتوں کی طرف مت موڑو، نہ ہی اپنے لیے پگھلے ہوئے خدا بناؤ: میں تمہارا خداوند خدا ہوں۔\n5۔ اور اگر تم خداوند کو صلح کی قربانی پیش کرو، تو اپنی مرضی سے پیش کرو۔\n6۔ اسے اسی دن کھایا جائے گا جب آپ اسے پیش کریں گے، اور کل بھی؛ اور اگر تیسرے دن تک رہنا پڑے تو اسے آگ میں جلا دیا جائے گا۔\n7۔ اور اگر تیسرے دن کھایا بھی جائے تو یہ {ناپسندیدہ} ہے؛ اسے قبول نہیں کیا جائے گا۔\n8۔ لہٰذا جو بھی اسے کھائے گا وہ اپنی گناہ اٹھائے گا، کیونکہ اس نے خداوند کی مقدس چیز کو بے حرمتی کی ہے: اور وہ روح اس کی قوم میں سے کاٹ دی جائے گی۔\n9۔ اور جب تم اپنی زمین کی فصل کاٹو گے، تو تم اپنے کھیت کے گوشے مکمل طور پر نہیں کاٹو گے، نہ ہی اپنی فصل کی کٹائی جمع کرو گے۔\n10۔ اور تم اپنے انگور کے باغ کو نہ توڑو گے، نہ ہی اپنے انگور کے ہر انگور کو جمع کرو گے؛ تو انہیں غریبوں اور اجنبیوں کے لیے چھوڑ دو: میں تمہارا خداوند خدا ہوں۔\n11۔ تم چوری نہیں کرو، نہ جھوٹ بولو گے، نہ ایک دوسرے سے جھوٹ بولو گے۔\n12۔ اور تم میرے نام سے جھوٹی قسم نہیں کھاؤ گے، نہ ہی اپنے خدا کے نام کی توہین کرو گے: میں خداوند ہوں۔\n13۔ تم اپنے پڑوسی کو دھوکہ نہیں دینا، نہ ہی اسے لوٹنا: جس کو کرائے پر لیا گیا ہے اس کی اجرت تمہارے ساتھ ساری رات صبح تک نہیں رہے گی۔\n14۔ تم بہروں کو لعنت نہ دو، نہ اندھوں کے سامنے رکاوٹ ڈالو، بلکہ اپنے خدا سے ڈرو: میں خداوند ہوں۔\n15۔ تم انصاف میں کوئی ناانصافی نہیں کرو گے: تم غریب کی جان کی عزت نہیں کرو گے، نہ ہی طاقتور کی عزت کرو گے: {لیکن} نیکی میں اپنے پڑوسی کا فیصلہ کرو گے۔\n16۔ تم اپنے لوگوں میں قصہ گو کی طرح اوپر نیچے نہیں جاؤ گے: نہ ہی اپنے پڑوسی کے خون کے خلاف کھڑے ہو سکتے ہو: میں خداوند ہوں۔\n17۔ اپنے بھائی سے دل سے نفرت نہ کرنا: کسی بھی طرح اپنے پڑوسی کو ڈانٹنا، اور اس پر گناہ نہ کرنا۔ {اور...: یا، کہ تم اس کے لیے گناہ نہ اٹھاؤ}\n18۔ تم اپنے لوگوں کے بچوں سے انتقام نہ لو اور نہ ہی کوئی رنجش رکھو، بلکہ اپنے پڑوسی سے ویسا ہی محبت کرو جیسا تم خود ہو: میں خداوند ہوں۔\n19۔ تم میرے قوانین کی حفاظت کرو گے۔ تم اپنے مویشیوں کو مختلف قسم کے مویشیوں کے ساتھ جنسی تعلقات قائم نہ کرنے دو: تم اپنے کھیت کو ملے ہوئے بیج سے نہ بوؤں گی، نہ ہی تم پر کپڑے اور اون کا ملا جلا لباس آئے گا۔\n20۔ اور جو کوئی عورت کے ساتھ جسمانی تعلق قائم کرتا ہے، یعنی وہ خادمہ ہے، جو شوہر سے منسوب ہے، اور نہ ہی اسے کوئی نجات دی گئی ہو؛ اسے کوڑے مارے جائیں گے؛ انہیں موت نہیں دی جائے گی، کیونکہ وہ آزاد نہیں تھی۔ {منگنی شدہ...: یا، کسی کے ہاتھوں بدسلوکی کا شکار: عبرانی انسان کی طرف سے ملامت کی جاتی ہے} {وہ کرے گی...: یا، وہ، وغیرہ: عبرانی۔ وہاں کوڑے مارے جائیں گے}\n21۔ اور وہ اپنی قربانی خداوند کے سامنے لے آئے گا، جماعت کے خیمہ کے دروازے پر، {حتیٰ کہ} ایک مینڈھا بھی جرم کی قربانی کے طور پر۔\n22. اور پادری اس کے لیے کفارہ دے گا کہ خداوند کے سامنے اس گناہ کے لیے جو اس نے کیا ہے، اس کے گناہ کے لیے جو اس نے کیا ہے، اور جو گناہ اس نے کیا ہے اسے معاف کر دیا جائے گا۔\n23۔ اور جب تم زمین پر آؤ اور کھانے کے لیے ہر قسم کے درخت لگاؤ، تو تم اس کے پھل کو غیر ختنہ شدہ شمار کرو: تین سال تک یہ تمہارے لیے غیر ختنہ شدہ ہوگا: اسے نہیں کھایا جائے گا۔\n24۔ لیکن چوتھے سال میں اس کے تمام پھل خداوند کی حمد کے لیے مقدس ہوں گے۔ {مقدس...: عبرانی۔ خداوند کے لیے حمد و ثنا کی پاکیزگی\n25۔ اور پانچویں سال میں تم اس کے پھل سے کھاؤ گے تاکہ وہ تمہیں اس کی مقدار میں اضافہ کرے: میں خداوند تمہارا خدا ہوں۔\n26. تم خون سے کچھ بھی نہیں کھاؤ گے، نہ جادو استعمال کرو گے، نہ اوقات کی پابندی کرو گے۔\n27. تم اپنے سر کے کنارے نہیں گھماؤ گے، نہ ہی اپنی داڑھی کے کونوں کو خراب کرو گے۔\n28۔ تم اپنے جسم میں مردوں کے لیے کوئی کٹائی نہ کرو، نہ تم پر کوئی نشان چھاپ دو: میں خداوند ہوں۔\n29۔ اپنی بیٹی کو طوائف مت کرو تاکہ وہ طوائف بن جائے؛ تاکہ زمین بدکاری میں نہ گر جائے اور زمین برائی سے بھر جائے۔ {: عبرانی۔ گستاخ}\n30. تم میرے سبت رکھو گے، اور میرے مقدس مقام کی عزت کرو گے: میں {ہوں} خداوند ہوں۔\n31۔ ان لوگوں کو جن کی روحیں مانوس ہیں، نہ جادوگروں کی تلاش میں، ان کے ہاتھوں ناپاک نہ سمجھو: میں تمہارا خداوند خدا ہوں۔\n32. تو اپنے بوڑھے سر کے سامنے کھڑے ہو جاؤ، بوڑھے آدمی کے چہرے کی عزت کرو، اور اپنے خدا سے ڈرو: میں خداوند ہوں۔\n33۔ اور اگر کوئی اجنبی تمہارے ساتھ تمہارے ملک میں ٹھہرے تو تم اسے پریشان نہیں کرو گے۔ {vex: یا، ظلم کرو}\n34۔ {لیکن} جو اجنبی تمہارے ساتھ رہتا ہے وہ تمہارے لیے تمہارے درمیان پیدا ہونے والے کی طرح ہوگا، اور تم اسے اپنی ذات کی طرح محبت کرو گے؛ کیونکہ تم مصر کی سرزمین میں اجنبی تھے: میں تمہارا خداوند خدا ہوں۔\n35۔ آپ فیصلے میں، وزن میں، وزن یا پیمائش میں کوئی ناانصافی نہیں کریں گے۔\n36۔ انصاف کے توازن، صرف وزن، ایک منصفانہ ایفاہ، اور ایک منصفانہ ہن، تمہیں ملے گا: میں ہوں خداوند تمہارا خدا، جس نے تمہیں مصر کی سرزمین سے نکالا۔ {وزن: عبرانی۔ پتھریں}\n37۔ لہٰذا تم میرے تمام قوانین اور تمام فیصلے مانو گے اور انہیں انجام دو گے: میں خداوند ہوں۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ پھر تم بنی اسرائیل سے کہو کہنا، جو بھی اسرائیل کے بچوں میں سے ہے، یا ان اجنبیوں میں سے جو اسرائیل میں مقیم ہیں، جو اپنی نسل کا کوئی حصہ مولخ کو دیتا ہے؛ یقینا اسے قتل کر دیا جائے گا: ملک کے لوگ اسے پتھروں سے سنگسار کریں گے۔\n3۔ اور میں اس آدمی کے خلاف اپنا چہرہ رکھوں گا، اور اسے اس کے لوگوں سے الگ کر دوں گا؛ کیونکہ اس نے اپنی نسل سے مولخ کو دیا ہے، تاکہ میری پناہ گاہ کو ناپاک کرے، اور میرے مقدس نام کی بے حرمتی کرے۔\n4۔ اور اگر ملک کے لوگ کسی بھی طرح اپنی آنکھیں اس آدمی سے چھپائیں جب وہ اپنی نسل مولخ کو دے دے، اور اسے قتل نہ کریں:\n5۔ پھر میں اس آدمی اور اس کے خاندان کے خلاف اپنا چہرہ رکھوں گا، اور اسے اور اس کے پیچھے آنے والے تمام لوگوں کو کاٹ دوں گا تاکہ مولیک کے ساتھ اپنی قوم میں سے بدکاری کرے۔\n6۔ اور جو روح ان لوگوں کے پیچھے مڑتی ہے جن کی روحیں مانوس ہیں، اور جادوگروں کے پیچھے جو ان کے پیچھے بدکاری کرتی ہے، میں اس روح کے خلاف اپنا چہرہ بھی لگا دوں گا، اور اسے اس کی قوم سے کاٹ دوں گا۔\n7۔ اپنے آپ کو پاک کرو اور پاک رہو: کیونکہ میں تمہارا خداوند خدا ہوں۔\n8۔ اور تم میرے قوانین کو پورا کرو گے، اور انہیں پورا کرو گے: میں وہ خداوند ہوں جو تمہیں پاک کرتا ہے۔\n9۔ جو بھی اپنے باپ یا ماں کو لعنت دے، اسے ضرور موت دی جائے گی: اس نے اپنے باپ یا ماں کو لعنت دی ہے؛ اس کا خون {اس پر ہوگا}۔\n10۔ اور جو مرد {دوسرے آدمی} کی بیوی کے ساتھ کرے گا، {وہ} جو اپنے پڑوسی کی بیوی کے ساتھ کرے گا، وہ کرنے والا اور کرنے والی کو ضرور موت دی جائے گی۔\n11۔ اور جو آدمی اپنے باپ کی بیوی کے ساتھ سوتا ہے، اس نے اپنے والد کی برہنگی ظاہر کر دی ہے: دونوں کو ضرور قتل کر دیا جائے گا؛ ان کا خون ان پر ہوگا۔\n12۔ اور اگر کوئی آدمی اپنی بہو کے ساتھ سوتا ہے تو دونوں کو ضرور موت دی جائے گی: انہوں نے الجھن پیدا کر دی ہے؛ ان کا خون ان پر ہوگا۔\n13۔ اگر کوئی مرد بھی انسانوں کے ساتھ سوتا ہے، جیسے وہ عورت کے ساتھ کرتا ہے، تو دونوں نے گناہ کیا ہے: انہیں ضرور قتل کر دیا جائے گا؛ ان کا خون ان پر ہوگا۔\n14۔ اور اگر کوئی آدمی اپنی بیوی اور اس کی ماں کو لے جائے تو یہ برائی ہے: وہ دونوں آگ میں جل جائیں گے؛ کہ تم میں کوئی برائی نہ ہو۔\n15۔ اور اگر کوئی جانور کے ساتھ سوئے، تو اسے ضرور مار دیا جائے گا: اور تم اس جانور کو مار ڈالو گے۔\n16۔ اور اگر کوئی عورت کسی جانور کے قریب جائے اور اس کے پاس لیٹ جائے، تو تم اس عورت اور جانور کو مار ڈالو گے: انہیں ضرور مار دیا جائے گا؛ ان کا خون ان پر ہوگا۔\n17۔ اور اگر کوئی آدمی اپنی بہن، اپنے والد کی بیٹی، یا اپنی ماں کی بیٹی کو لے کر اس کی برہنگی دیکھے، اور وہ اس کی برہنگی دیکھے؛ یہ {ہے} ایک بری چیز ہے؛ اور وہ اپنی قوم کی نظر میں کاٹ دیے جائیں گے: اس نے اپنی بہن کی برہنگی بے نقاب کر دی ہے؛ وہ اپنی بدکاری برداشت کرے گا۔\n18۔ اور اگر کوئی مرد عورت کے ساتھ اس کی بیماری میں سوئے اور اس کی برہنگی ظاہر کرے؛ اس نے اس کا چشمہ دریافت کیا ہے، اور اس نے اپنے خون کا چشمہ دریافت کیا ہے: اور دونوں کو اپنے لوگوں میں سے کاٹ دیا جائے گا۔ {دریافت شدہ: عبرانی۔ برہنہ بنایا گیا}\n19۔ اور تم اپنی ماں کی بہن اور اپنے باپ کی بہن کی برہنگی کو ظاہر نہیں کرو گے، کیونکہ وہ اپنے قریبی رشتہ داروں کو بے نقاب کرتا ہے: وہ اپنی بدکاری برداشت کریں گے۔ {کھولتا ہے: عبرانی۔ ننگا بنا دیا ہے}\n20۔ اور اگر کوئی آدمی اپنے چچا کی بیوی کے ساتھ سوتا ہے، تو اس نے اپنے چچا کی برہنگی ظاہر کر دی ہے: وہ اپنا گناہ اٹھائیں گے؛ وہ بغیر اولاد کے مر جائیں گے۔\n21۔ اور اگر کوئی آدمی اپنے بھائی کی بیوی لے جائے تو یہ ناپاک چیز ہے: اس نے اپنے بھائی کی برہنگی کو بے نقاب کر دیا ہے؛ وہ بے اولاد ہوں گے۔ {an...: عبرانی۔ ایک علیحدگی}\n22۔ لہٰذا تم میرے تمام قوانین اور تمام فیصلے پورے کرو گے، اور انہیں پورا کرو گے: تاکہ وہ زمین، جہاں میں تمہیں وہاں بسنے کے لیے لایا ہوں، تم باہر نہ نکلو۔\n23۔ اور تم اس قوم کے آداب پر نہیں چلو گے، جنہیں میں نے تمہارے سامنے نکالا ہے: کیونکہ انہوں نے یہ سب کچھ کیا، اور اس لیے میں ان سے نفرت کرتا ہوں۔\n24۔ لیکن میں نے تم سے کہا ہے، تم ان کی زمین کے وارث بنو گے، اور میں اسے تمہیں دوں گا کہ تم اس کا مالک ہو، ایک ایسی زمین جو دودھ اور شہد سے بہتی ہے: میں تمہارا خداوند خدا ہوں، جس نے تمہیں {دوسرے} لوگوں سے جدا کیا ہے۔\n25۔ اس لیے تم پاک جانوروں اور ناپاک جانوروں کے درمیان، اور ناپاک مرغیوں اور پاکیزہ کے درمیان فرق کرو گے، اور تم اپنی جانداروں کو جانور، پرندے، یا زمین پر رینگنے والے کسی بھی جاندار سے ناپاک نہ بنا دو، جسے میں نے تم سے ناپاک سمجھا ہے۔ {کریپتھ: یا، حرکت کرو}\n26. اور تم میرے لیے پاک رہو گے: کیونکہ میں، خداوند مقدس ہوں، اور تمہیں {دوسرے} لوگوں سے جدا کر دیا ہے تاکہ تم میرے ہو۔\n27. جو مرد یا عورت بھی مانوس روح رکھتی ہے، یا جو جادوگر ہے، اسے ضرور قتل کر دیا جائے گا: وہ انہیں پتھر سے پتھر مارے گا: ان کا خون ان پر ہوگا۔","1۔ اور خداوند نے موسیٰ سے فرمایا: ہارون کے بیٹوں کے کاہنوں سے بات کر، اور ان سے کہو، اس کی قوم میں مردوں کے لیے کوئی ناپاک نہیں ہوگا:\n2۔ لیکن اس کے رشتہ داروں کے لیے، جو اس کے قریب ہیں، {یعنی}، اپنی ماں کے لیے، اپنے والد کے لیے، اپنے بیٹے کے لیے، اپنی بیٹی کے لیے، اور اپنے بھائی کے لیے،\n3۔ اور اس کی بہن کے لیے ایک کنواری ہے، جو اس کے قریب ہے اور جس کا کوئی شوہر نہیں ہے؛ اس کے لیے وہ ناپاک ہو۔\n4۔ {لیکن} وہ اپنے آپ کو ناپاک نہیں کرے گا، {چونکہ وہ اپنے لوگوں میں ایک اہم آدمی ہے}، تاکہ خود کو بے حرمتی کرے۔ {وہ...: یا، چونکہ وہ اپنے لوگوں میں شوہر ہے، وہ اپنی بیوی کے لیے خود کو ناپاک نہیں کرے گا، وغیرہ}\n5۔ وہ اپنے سر پر گنجا نہیں بنائیں گے، نہ داڑھی کے کونے کو منڈائیں گے، اور نہ ہی اپنے جسم میں کوئی کٹائی کریں گے۔\n6۔ وہ اپنے خدا کے لیے پاک ہوں گے، اور اپنے خدا کے نام کی بے حرمتی نہیں کریں گے: کیونکہ خداوند کی آگ سے دی گئی نذرانے {اور} اپنے خدا کی روٹی کے لیے وہ پیش کرتے ہیں: اس لیے وہ مقدس ہوں گے۔\n7۔ وہ بیوی نہیں لیں گے، یعنی کوئی بدکار یا ناپاک؛ اور نہ ہی وہ عورت کو اس کے شوہر سے الگ کر کے نہیں لیں گے: کیونکہ وہ اپنے خدا کے لیے مقدس ہے۔\n8. تو اسے پاک کرو گے؛ کیونکہ وہ تمہارے خدا کی روٹی پیش کرتا ہے: وہ تمہارے لیے پاک ہوگا: کیونکہ میں، جو تمہیں مقدس بناتا ہوں، میں پاک ہوں۔\n9۔ اور کسی بھی پادری کی بیٹی، اگر وہ خود کو طوائف کا کردار ادا کر کے بے حرمتی کرے، تو وہ اپنے باپ کی بے حرمتی کرے گی: اسے آگ میں جلا دیا جائے گا۔\n10۔ اور جو اپنے بھائیوں میں سے اعلیٰ کاہن ہے، جس کے سر پر مسح کا تیل ڈالا گیا اور جو لباس پہننے کے لیے وقف ہے، وہ اپنا سر نہیں کھولے گا اور نہ ہی اپنے کپڑے پھاڑے گا؛\n11۔ نہ وہ کسی مردہ جسم میں جائے گا، نہ اپنے والد کے لیے خود کو ناپاک کرے گا، نہ اپنی ماں کے لیے؛\n12۔ نہ وہ مقدس مقام سے باہر جائے گا، نہ اپنے خدا کے مقدس مقام کو بے حرمتی کرے گا؛ کیونکہ اس کے خدا کے مسح کے تیل کا تاج {ہے} اس پر: میں {ہوں} خداوند۔\n13۔ اور وہ کنواری پن میں بیوی لے گا۔\n14۔ بیوہ، یا طلاق یافتہ عورت، یا بدکار عورت، {یا} بدکار عورت، یہ وہ نہیں لے گا: بلکہ وہ اپنی قوم کی کنواری کو بیوی بنائے گا۔\n15۔ نہ ہی وہ اپنی نسل کو اپنی قوم میں بے حرمتی کرے گا: کیونکہ میں، خداوند اسے پاک کرتا ہوں۔\n16۔ اور خداوند نے موسیٰ سے کہا،\n17۔ ہارون سے بات کرو اور کہو، جو بھی تیری نسل سے ہے اور جس کے پاس کوئی عیب ہے، وہ اپنے خدا کی روٹی پیش کرنے نہ آئے۔ {روٹی: یا، کھانا}\n18۔ کیونکہ جس شخص پر کوئی داغ ہے، وہ قریب نہیں آئے گا: اندھا، لنگڑا، یا جس کی ناک چپٹی ہو، یا کوئی غیر ضروری چیز،\n19۔ یا وہ آدمی جو ٹوٹے ہوئے پاؤں یا ٹوٹے ہوئے ہاتھوں کا ہو،\n20۔ یا کروک بیکٹ، یا بونا، یا جس کی آنکھ میں داغ ہو، یا اسکوروی ہو، یا پٹی ہو، یا اس کے پتھر ٹوٹے ہوئے ہوں؛ {ایک بونا: یا، بہت پتلا}\n21. کوئی شخص جس پر ہارون کاهن کی نسل کا داغ ہو، وہ رب کی آگ سے دی گئی نذرانے پیش کرنے کے قریب نہیں آئے گا: اس کے پاس داغ ہے؛ وہ اپنے خدا کی روٹی پیش کرنے کے قریب نہیں آئے گا۔\n22. وہ اپنے خدا کی روٹی کھائے گا، {دونوں} سب سے مقدس اور مقدس کی روٹی۔\n23۔ صرف وہ نہ تو چادر میں جائے گا، نہ قربان گاہ کے قریب جائے گا، کیونکہ اس میں کوئی داغ ہے؛ کہ وہ میرے مقدس مقامات کی بے حرمتی نہ کرے: کیونکہ میں خداوند انہیں مقدس کرتا ہوں۔\n24۔ اور موسیٰ نے یہ بات ہارون، اس کے بیٹوں اور تمام بنی اسرائیل کو بتائی۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ ہارون اور اس کے بیٹوں سے بات کرو کہ وہ بنی اسرائیل کی مقدس چیزوں سے الگ ہو جائیں، اور میرے مقدس نام کی بے حرمتی نہ کریں {ان چیزوں میں} جنہیں وہ میرے لیے مقدس کرتے ہیں: میں {ہوں} خداوند ہوں۔\n3۔ ان سے کہو، جو بھی تمہاری تمام نسلوں میں سے ہے، جو ان مقدس چیزوں کی طرف جاتا ہے جنہیں بنی بنی اسرائیل خداوند کے لیے مقدس کرتے ہیں، اور اس کی ناپاکی اس پر ہے، وہ روح میری موجودگی سے کاٹ دی جائے گی: میں خداوند ہوں۔\n4۔ ہارون کی نسل میں سے کون سا شخص کوڑھی ہے یا اس کا کوئی مستقل اولاد ہے؛ وہ مقدس چیزوں میں سے نہیں کھائے گا، جب تک کہ وہ پاک نہ ہو جائے۔ اور جو کسی بھی ناپاک چیز کو چھوئے {جو مردہ کے ذریعے} یا اس آدمی کی اولاد سے نکلے؛ {دوڑتا ہوا...: ہیب۔ رننگ آف دی رینس}\n5۔ یا جو کوئی بھی رینگنے والی چیز کو چھوئے جس سے وہ ناپاک ہو جائے، یا کوئی ایسا شخص جس سے وہ ناپاک ہو جائے، جو بھی ناپاک ہو؛\n6۔ جو روح ایسے کسی کو چھو لے وہ ناپاک رہے گی جب تک کہ وہ پانی سے نہ دھوئے، اور مقدس چیزوں میں سے نہیں کھائے گی جب تک کہ وہ اپنے گوشت کو پانی سے نہ دھوئے۔\n7۔ اور جب سورج غروب ہو جائے تو وہ پاک ہو جائے گا، اور بعد میں مقدس چیزوں میں سے کھائے گا؛ کیونکہ یہ اس کا کھانا ہے۔\n8۔ جو چیز خود سے مر جائے یا جانوروں سے پھٹی ہو، وہ خود کو ناپاک کرنے کے لیے نہیں کھائے گا: میں {ہوں} خداوند۔\n9۔ لہٰذا وہ میرے حکم کی پاسداری کریں گے، ورنہ اس کا گناہ اٹھائیں گے، اور اگر وہ اسے بے حرمتی کریں تو مر جائیں گے: میں خداوند انہیں پاک کرتا ہوں۔\n10۔ کوئی اجنبی مقدس چیز نہیں کھائے گا: پادری کا مسافر یا کرائے کا خادم مقدس چیز نہیں کھائے گا۔\n11۔ لیکن اگر پادری اپنی دولت سے کوئی روح خریدے تو وہ اس میں سے کھائے گا، اور جو اس کے گھر میں پیدا ہوگا: وہ اس کے گوشت سے کھائے گا۔ {ساتھ...: عبوری۔ اپنے پیسے خریدنے کے بعد}\n12۔ اگر پادری کی بیٹی بھی کسی اجنبی سے شادی شدہ ہو، تو وہ مقدس چیزوں کی قربانی نہیں کھا سکتی۔ {ایک اجنبی: عبرانی۔ ایک آدمی ایک اجنبی}\n13۔ لیکن اگر پادری کی بیٹی بیوہ ہو، یا طلاق یافتہ ہو، اور اس کا کوئی بچہ نہ ہو، اور اسے اپنے والد کے گھر واپس بھیجا جائے، جیسے وہ جوانی میں تھی، تو وہ اپنے والد کے گوشت سے کھائے گی؛ لیکن کوئی اجنبی اس میں سے نہیں کھائے گا۔\n14۔ اور اگر کوئی شخص انجانے میں مقدس چیز کھا لے، تو وہ اس کا پانچواں حصہ اس میں ڈال دے گا، اور مقدس چیز کے ساتھ پادری کو دے دے گا۔\n15۔ اور وہ بنی اسرائیل کی مقدس چیزوں کی بے حرمتی نہیں کریں گے، جو وہ خداوند کو پیش کرتے ہیں؛\n16۔ یا انہیں گناہ کی گناہ برداشت کرنے دو، جب وہ اپنی مقدس چیزیں کھائیں: کیونکہ میں خداوند انہیں پاک کرتا ہوں۔ {برداشت کرو...: یا، اپنے کھانے میں گناہ کے جرم میں مبتلا ہو جاؤ}\n17۔ اور خداوند نے موسیٰ سے کہا،\n18۔ ہارون، اس کے بیٹوں سے، اور تمام بنی اسرائیل سے بات کرو، اور ان سے کہو، جو بھی وہ اسرائیل کے گھرانے یا اسرائیل کے اجنبیوں کا ہے، جو اس کی تمام قسموں اور اپنی تمام آزاد مرضی کی نذرانے کے لیے اس کی قربانی پیش کرے گا، جو وہ خداوند کو جلانے کی قربانی کے طور پر پیش کریں گے؛\n19۔ {تم اپنی مرضی سے} ایک بے داغ نر پیش کرو گے، چاہے وہ بویش، بھیڑ یا بکریوں کا ہو۔\n20۔ {لیکن} جو بھی داغ ہے، {وہ} تم پیش نہیں کرو گے: کیونکہ وہ تمہارے لیے قابل قبول نہیں ہوگا۔\n21۔ اور جو بھی اپنے عہد کو پورا کرنے کے لیے خداوند کے سامنے صلح کی قربانی پیش کرے، یا مویشیوں یا بھیڑوں کی صورت میں آزاد مرضی کی قربانی پیش کرے، تو اسے قبول کرنے کے لیے بہترین ہوگا؛ اس میں کوئی داغ نہیں ہوگا۔ {بھیڑیں: یا، بکریاں}\n22۔ اندھا، ٹوٹا ہوا، معذور، یا وین، اسکرووی، یا زخم کے ساتھ، تم یہ سب خداوند کو پیش نہیں کرو گے، اور نہ ہی ان کی آگ میں قربان گاہ پر خدا کے سامنے پیش کرو گے۔\n23۔ یا تو بیل یا بکری جس کے اعضا میں کوئی غیر ضروری یا کمی ہو، تاکہ تم اپنی مرضی سے پیش کر سکو؛ لیکن قسم کے لیے اسے قبول نہیں کیا جائے گا۔ {لیمب: یا، بچے}\n24۔ تم خداوند کو وہ چیز پیش نہیں کرو گے جو زخمی ہے، یا کچلا گیا ہے، یا ٹوٹا ہے، یا کٹ گیا ہے؛ نہ ہی تم اپنی زمین میں اس کی کوئی قربانی پیش کرو گے۔\n25۔ کسی اجنبی کے ہاتھ سے آپ اپنے خدا کی روٹی ان میں سے کسی کو پیش نہیں کریں گے؛ کیونکہ ان کی بدعنوانی ان میں ہے، اور ان میں داغیں ہیں: وہ تمہارے لیے قبول نہیں کیے جائیں گے۔\n26۔ اور خداوند نے موسیٰ سے کہا،\n27۔ جب کوئی بیل، بھیڑ، یا بکری پیدا کی جائے تو وہ بند کے نیچے سات دن رہے گا؛ اور آٹھویں دن سے اور اس کے بعد اسے آگ کے ذریعے خداوند کے لیے پیش کی جانے والی قربانی کے طور پر قبول کیا جائے گا۔\n28۔ اور {چاہے وہ گائے ہو یا بھیڑو}، تم اسے اور اس کے بچوں کو ایک ہی دن میں نہیں مارو گے۔ {ایو: یا، وہ بکری}\n29۔ اور جب تم خداوند کے لیے شکر گزاری کی قربانی پیش کرو، تو اپنی مرضی سے پیش کرو۔\n30۔ اسی دن اسے کھایا جائے گا؛ تم اس میں سے کچھ بھی کل تک نہیں چھوڑو گے: میں {ہوں} خداوند ہوں۔\n31۔ اس لیے تم میرے احکامات کی پاسداری کرو گے، اور عمل کرو گے: میں خداوند ہوں۔\n32. نہ ہی تم میرے مقدس نام کی توہین کرو گے؛ لیکن میں بنی اسرائیل میں مقدس ہوں گا: میں وہ خداوند ہوں جو تمہیں مقدس کرتا ہے،\n33۔ جس نے تمہیں مصر کی سرزمین سے نکالا، تاکہ وہ تمہارا خدا بن سکے: میں خداوند ہوں۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل سے بات کرو، اور انہیں کہو، {خداوند کے تہواروں کے بارے میں}، جنہیں تم مقدس اجتماعات قرار دو گے، {حتیٰ} کہ یہ میرے تہوار ہیں۔\n3۔ چھ دن کام کیا جائے گا: لیکن ساتواں دن آرام کا سبت ہے، ایک مقدس اجتماع؛ تم وہاں کوئی کام نہیں کرو گے: یہ خداوند کا سبت ہے تمہارے تمام گھروں میں۔\n4۔ یہ خداوند کے تہوار ہیں، {حتیٰ کہ} مقدس اجتماعات بھی، جنہیں آپ ان کے موسموں میں اعلان کریں گے۔\n5. پہلے مہینے کے چودہویں {دن} میں، جب یہ رب کا فسح ہے۔\n6۔ اور اسی مہینے کی پندرہویں تاریخ کو خداوند کے لیے بغیر خمیر کی روٹی کا تہوار ہے: سات دن آپ کو بغیر خمیر کی روٹی کھانی ہوگی۔\n7۔ پہلے دن آپ کو مقدس اجلاس کرنا ہوگا: آپ اس میں کوئی غلامی کا کام نہیں کریں گے۔\n8۔ لیکن تم سات دن خدا کو آگ سے پیش کی گئی قربانی پیش کرو: ساتویں دن مقدس اجلاس ہے: تم وہاں کوئی غلامی کا کام نہیں کرو گے۔\n9۔ اور خداوند نے موسیٰ سے کہا،\n10۔ بنی اسرائیل سے بات کرو، اور ان سے کہو، جب تم اس زمین میں آؤ جو میں تمہیں دیتا ہوں، اور اس کی فصل کاٹو گے، تو تم اپنی فصل کے پہلے پھلوں کا ایک گچھا کاہنی کے پاس لاؤ گے: {گٹھ: یا، مٹھی بھری: عبرانی۔ عمر}\n11۔ اور وہ گچھا خداوند کے سامنے لہرائے گا، تاکہ وہ تمہارے لیے قبول ہو: سبت کے بعد کل پادری اسے لہرائے گا۔\n12۔ اور تم اس دن پیش کرو گے جب تم پہلے سال کے بغیر کسی داغ کے گٹھا اور برہ لہراؤ گے، تاکہ خداوند کے سامنے ایک جلنے کی قربانی پیش کی جا سکے۔\n13۔ اور اس کی گوشت کی قربانی دو دسویں سودے عمدہ آٹے کے تیل کے ساتھ ملائی ہوگی، جو آگ سے خداوند کے لیے پیش کی جائے گی {کیونکہ یہ میٹھا ذائقہ ہے}؛ اور اس کی نذرانہ {شراب کی} ہوگی، چوتھی {حصہ} ایک ہن۔\n14۔ اور تم نہ روٹی کھاؤ گے، نہ خشک دانہ، نہ سبز کان، جب تک کہ اسی دن تم اپنے خدا کو نذرانہ پیش نہ کرو: یہ تمہارے تمام گھروں میں ہمیشہ کے لیے ایک مجسمہ رہے گا۔\n15۔ اور تم کل سبت کے بعد سے گنتی کرو گے، اس دن سے جب تم نے پیشکش کا گٹھا لایا تھا؛ سات سبت مکمل ہوں گے:\n16۔ کل ساتویں سبت کے بعد بھی تم پچاس دن گنو گے؛ اور تم خداوند کے لیے نیا گوشت کی قربانی پیش کرو گے۔\n17۔ تم اپنی رہائش گاہوں سے دو لہرانے والے روٹیاں دو دسویں حصے کی نکالو گے: وہ عمدہ آٹے کی ہوں گی؛ انہیں خمیر کے ساتھ پکایا جائے گا؛ {وہ} خداوند کے پہلے پھل ہیں۔\n18۔ اور تم روٹی کے ساتھ سات برہ بغیر کسی داغ کے پہلے سال کے پیش کرو، اور ایک نوجوان بیل، اور دو مینڈھے پیش کرو: یہ خداوند کے لیے جلنے والی قربانی ہوں گے، ان کے گوشت کی قربانی کے ساتھ، اور ان کی شراب کی قربانیاں، {حتیٰ کہ} آگ سے پیش کی گئی نذرانہ، خدا کے لیے میٹھے ذائقے کی پیشکش۔\n19۔ پھر تم بکریوں کے ایک بچے کو گناہ کی قربانی کے طور پر قربان کرو، اور پہلے سال کے دو برہ صلح کی قربانی کے طور پر۔\n20۔ اور پادری انہیں پہلے پھلوں کی روٹی کے ساتھ لہرائے گا {کیونکہ خدا کے حضور دو بکریوں کے ساتھ} ایک نذرانہ ہوگا: وہ پادری کے لیے خداوند کے لیے مقدس ہوں گے۔\n21. اور تم اسی دن اعلان کرو گے، {تاکہ} یہ تمہارے لیے ایک مقدس دعوت ہو: تم اس میں کوئی غلامی کا کام نہیں کرو گے: یہ تمہارے تمام گھروں میں ہمیشہ کے لیے ایک قانون رہے گا، تمہاری نسلوں تک۔\n22۔ اور جب تم اپنی زمین کی فصل کاٹو گے، تو جب تم اپنی زمین کی فصل کاٹو گے تو اپنے کھیت کے کونوں کو صاف صاف نہیں کرو گے، نہ ہی اپنی فصل کا کوئی کٹاؤ جمع کرو گے: تم انہیں غریبوں اور اجنبیوں کے لیے چھوڑ دو گے: میں تمہارا خداوند خدا ہوں۔\n23۔ اور خداوند نے موسیٰ سے کہا،\n24۔ بنی اسرائیل سے فرماو، ساتویں مہینے میں، مہینے کے پہلے دن، تم سبت مناؤ گے، بگل بجانے کی یادگار، ایک مقدس اجتماع۔\n25۔ تم اس میں کوئی غلامی کا کام نہیں کرو گے: بلکہ تم آگ سے دی گئی نذرانہ خداوند کے سامنے پیش کرو گے۔\n26۔ اور خداوند نے موسیٰ سے کہا،\n27. اسی ساتویں مہینے کے دسویں دن کو کفارہ کا دن ہوگا: یہ آپ کے لیے مقدس اجتماع ہوگا؛ اور تم اپنی جانوں کو اذیت دو گے، اور آگ سے خدا کو پیش کرو گے۔\n28۔ اور تم اسی دن کوئی کام نہیں کرو گے: کیونکہ یہ کفارہ کا دن ہے، تاکہ تمہارے خداوند خدا کے سامنے تمہارے لیے کفارہ ہو۔\n29۔ جو بھی شخص اسی دن متاثر نہ ہو، اسے اپنی قوم سے الگ کر دیا جائے گا۔\n30۔ اور جو بھی روح اسی دن کوئی کام کرے، میں اسے اس کے لوگوں میں سے ختم کر دوں گا۔\n31۔ تم کوئی کام نہیں کرو گے: یہ تمہاری نسلوں تک تمہارے تمام گھروں میں ہمیشہ کے لیے ایک قانون رہے گا۔\n32. یہ آپ کے لیے آرام کا سبت ہوگا، اور آپ اپنی جانوں کو تکلیف دیں گے: مہینے کے نویں دن شام کو، مساوات سے شام تک، آپ اپنا سبت منائیں گے۔ {جشن مناؤ: عبرانی۔ آرام}\n33۔ اور خداوند نے موسیٰ سے کہا،\n34۔ بنی اسرائیل سے کہو کہ، اس ساتویں مہینے کی پندرہویں تاریخ کو خداوند کے لیے سات دن کے لیے خیمہ جات کا تہوار ہوگا۔\n35۔ پہلے دن مقدس اجلاس ہوگا: آپ وہاں کوئی غلامی کا کام نہیں کریں گے۔\n36. سات دن تم آگ سے خدا کے لیے پیش کی گئی قربانی پیش کرو؛ آٹھویں دن تمہارے لیے مقدس اجلاس ہوگا؛ اور تم آگ سے پیش کی گئی نذرانہ خداوند کو پیش کرو گے: یہ ایک سنجیدہ اجتماع ہے؛ {اور} تم کوئی غلامی کا کام نہیں کرو گے۔ {سنجیدہ...: عبرانی۔ پابندی کا دن}\n37۔ یہ خداوند کے تہوار ہیں، جنہیں تم مقدس اجتماعات قرار دو گے، تاکہ خداوند کو آگ سے پیش کی گئی قربانی، جلتی قربانی، گوشت کی قربانی، قربانی اور شراب کی قربانیاں، سب کچھ خداوند کے دن پیش کریں:\n38۔ خداوند کے سبت کے علاوہ، اور تمہارے تحفوں کے علاوہ، اور تمہارے تمام وعدوں کے ساتھ، اور اپنی تمام آزاد مرضی کی نذرانے کے علاوہ، جو تم خداوند کو دیتے ہو۔\n39۔ ساتویں مہینے کے پندرہویں دن، جب تم زمین کے پھل جمع کرو گے، تو تم خداوند کے لیے سات دن عید رکھو گے: پہلے دن سبت ہوگا، اور آٹھویں دن سبت ہوگا۔\n40۔ اور تم پہلے دن اچھے درختوں کی شاخیں، کھجور کی شاخیں، گھنے درختوں کی شاخیں اور ندی کے بید کے درخت لے جاؤ گے؛ اور تم سات دن اپنے خداوند خدا کے سامنے خوش رہو گے۔ {اچھے درختوں کی شاخیں: عبرانی۔ پھل وغیرہ}\n41۔ اور تم اسے سال کے سات دن خداوند کے لیے عید کے طور پر مناؤ گے۔ {یہ تمہاری نسلوں میں ہمیشہ کے لیے ایک قانون رہے گا: تم اسے ساتویں مہینے میں مناؤ گے۔\n42۔ تم سات دن بوتھز میں رہو گے؛ جو بھی بنی اسرائیل پیدا ہوئے ہیں، وہ کبوتوں میں رہیں گے:\n43. تاکہ تمہاری نسلیں جان سکیں کہ میں نے اسرائیل کے بچوں کو بوتھوں میں رکھا، جب میں نے انہیں مصر کی سرزمین سے نکالا: میں خداوند تمہارا خدا ہوں۔\n44۔ اور موسیٰ نے بنی اسرائیل کو خداوند کے تہوار کا اعلان کیا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل کو حکم دو کہ وہ تمہارے پاس روشنی کے لیے پیلا خالص تیل اور زیتون لاؤ، تاکہ چراغ مسلسل جلائیں۔ {وجہ بنانے کے لیے: عبرانی۔ جس کی وجہ سے وہ عروج پر پہنچے}\n3۔ گواہی کے پردے کے بغیر، جماعت کے خیمے میں، ہارون اسے شام سے صبح تک خداوند کے سامنے مسلسل حکم دے گا: {یہ تمہاری نسلوں میں ہمیشہ کے لیے ایک قانون رہے گا۔\n4۔ وہ خداوند کے سامنے خالص شمعدان پر چراغے مسلسل جلانے کا حکم دے گا۔\n5۔ اور تم عمدہ آٹا لے کر بارہ کیک بیک کرو: ایک کیک میں دو دسویں سودے ہوں گے۔\n6۔ اور تم انہیں دو قطاروں میں، چھ قطاروں میں، پاک میز پر خداوند کے سامنے رکھو۔\n7۔ اور تم ہر قطار پر خالص لوبان رکھو، تاکہ وہ روٹی پر یادگار کے طور پر ہو، یہاں تک کہ آگ سے خداوند کے لیے پیش کی گئی نذرانہ بھی۔\n8۔ ہر سبت کو وہ اسے خداوند کے سامنے مسلسل ترتیب دے گا، اور ایک دائمی عہد کے ذریعے بنی اسرائیل سے لیا جائے گا۔\n9۔ اور یہ ہارون اور اس کے بیٹوں کا ہوگا؛ اور وہ اسے مقدس جگہ پر کھائیں گے: کیونکہ یہ خداوند کی آگ سے دی گئی دائمی قانون کی قربانیوں میں سب سے مقدس ہے۔\n10۔ اور ایک اسرائیلی عورت کا بیٹا، جس کا باپ مصری تھا، بنی اسرائیل کے درمیان نکلا: اور یہ اسرائیلی عورتوں کا بیٹا اور اسرائیل کا ایک مرد کیمپ میں اکٹھے لڑے؛\n11۔ اور اسرائیلی عورت کے بیٹے نے {خداوند کے نام} کی توہین کی اور لعنت کی۔ اور وہ اسے موسیٰ کے پاس لے گئے: (اور اس کی ماں کا نام شیلومیت تھا، جو ڈیبری کی بیٹی تھی، قبیلہ دان سے:)\n12۔ اور انہوں نے اسے قید میں رکھا تاکہ خداوند کا ذہن انہیں دکھایا جا سکے۔ {وہ...: عببرانی۔ خداوند کے منہ کے مطابق ان کے سامنے وضاحت کرنا}\n13۔ اور خداوند نے موسیٰ سے کہا،\n14۔ جس نے بغیر کیمپ کے لعنت دی ہے اسے باہر لاؤ؛ اور جو بھی اس کی آواز سنتا ہے وہ اس کے سر پر ہاتھ رکھ دے، اور تمام جماعت اسے پتھر مار دے۔\n15۔ اور تم بنی اسرائیل سے کہو کہ، جو اپنے خدا کو لعنت دے گا وہ اس کا گناہ اٹھائے گا۔\n16۔ اور جو خدا کے نام کی توہین کرے گا، اسے ضرور قتل کر دیا جائے گا، {اور} تمام جماعت اسے پتھر مار دیں گے: اور وہ اجنبی بھی، جیسا کہ وہ زمین میں پیدا ہوا ہے، جب وہ خداوند کے نام کی توہین کرے گا، اسے قتل کر دیا جائے گا۔\n17۔ اور جو کسی کو مارے گا، اسے ضرور موت دی جائے گی۔ {killeth...: عبرانی۔ ایک انسان کی زندگی کو سزا دیتا ہے}\n18۔ اور جو جانور مارے گا وہ اسے اچھا بنائے گا؛ جانور کے بدلے درندہ۔ {جانور کے لیے...: عبرانی زندگی کے بدلے زندگی}\n19۔ اور اگر کوئی شخص اپنے پڑوسی میں داغ ڈالے؛ جیسے اس نے کیا، ویسا ہی اس کے ساتھ بھی ہوگا؛\n20۔ توڑ پھوڑ کے بدلے، آنکھ کے بدلے آنکھ، دانت کے بدلے دانت: جیسے اس نے انسان میں داغ ڈالا ہے، ویسے ہی اس کے ساتھ بھی دوبارہ کیا جائے گا۔\n21۔ اور جو جانور مارے گا، وہ اسے واپس کرے گا: اور جو کسی کو مارے گا، اسے مار دیا جائے گا۔\n22۔ تمہارے پاس ایک ہی قانون ہوگا، اجنبی کے لیے بھی، جیسا کہ تمہارے اپنے ملک کے لیے بھی: کیونکہ میں تمہارا خداوند خدا ہوں۔\n23۔ اور موسیٰ نے بنی اسرائیل سے کہا کہ وہ اس شخص کو نکالیں جس نے کیا ہے، اسے کیمپ سے باہر نکالیں اور اسے پتھر ماریں۔ اور بنی اسرائیل نے وہی کیا جو خداوند نے موسیٰ کو حکم دیا۔","1۔ اور خداوند نے کوہ سینا میں موسیٰ سے کہا،\n2۔ بنی اسرائیل سے بات کرو، اور ان سے کہو، جب تم اس زمین میں آؤ جو میں تمہیں دیتا ہوں، تو زمین خداوند کے لیے سبت منائے گی۔ {برقرار رکھو: عبوری۔ آرام}\n3۔ چھ سال تک تم اپنا کھیت بوؤں گے، اور چھ سال تک اپنے انگور کے باغ کو کاٹو گے، اور اس کے پھل جمع کرو گے؛\n4۔ لیکن ساتویں سال زمین کے لیے آرام کا سبت ہوگا، خداوند کے لیے سبت ہوگا: نہ تو اپنا کھیت بوؤ گے، نہ اپنے انگور کے باغ کو کاٹو گے۔\n5۔ جو چیز اپنی مرضی سے تمہاری فصل سے اگتی ہے، اسے نہ کاٹو گے، نہ اپنی بیل کے انگور بغیر کپڑے جمع کرو گے: {کیونکہ} یہ زمین کے لیے آرام کا سال ہے۔ {تمہاری انگور سے...: عبرانی۔ تیری جدائی کی}\n6۔ اور زمین کا سبت تمہارے لیے گوشت ہوگا؛ تمہارے لیے، تمہارے خادم کے لیے، تمہاری نوکرانی کے لیے، تمہارے کرائے کے خادم کے لیے، اور تمہارے اجنبی کے لیے جو تمہارے ساتھ رہتا ہے،\n7۔ اور تمہارے مویشیوں کے لیے، اور تمہاری زمین میں موجود جانوروں کے لیے، اس کی تمام پیداوار گوشت ہوگی۔\n8۔ اور تم اپنے لیے سات سال کے سبت گننا، سات بار سات سال؛ اور سالوں کے سات سبت کا وقفہ تمہارے لیے چالیس اور نو سال ہوگا۔\n9۔ پھر تم ساتویں مہینے کے دسویں دن جوبل کی بگل بجاؤ گے، کفارے کے دن تم اپنی پوری زمین میں بگل بجاؤ گے۔ {جوبل کے مطابق: عبرانی۔ اونچی آواز}\n10۔ اور تم پچاسویں سال کو مقدس مناؤ گے، اور پورے علاقے میں اس کے تمام باشندوں کو آزادی کا اعلان کرو گے: یہ تمہارے لیے خوشی ہوگی؛ اور تم ہر آدمی کو اس کے قبضے میں واپس کرو گے، اور ہر آدمی کو اس کے خاندان کے پاس واپس کرو گے۔\n11۔ پچاسواں سال تمہارے لیے ایک جوبل ہوگا: تم نہ بوؤ گے، نہ وہ کاٹو گے جو اس میں اگتا ہے، نہ ہی اپنی انگور کو بغیر کپڑے جمع کرو گے۔\n12۔ کیونکہ یہ جوبل ہے؛ یہ تمہارے لیے مقدس ہوگا: تم اس کی پیداوار کھیت سے کھاؤ گے۔\n13۔ اس یوبیل کے سال میں تم ہر آدمی کو اس کی ملکیت میں واپس کرو گے۔\n14۔ اور اگر تم اپنے پڑوسی کو لوٹ بیچو، یا اپنے پڑوسی کے ہاتھ سے خریدو، تو تم ایک دوسرے پر ظلم نہیں کرو گے:\n15۔ جوبیل کے بعد آپ اپنے پڑوسی سے خریدنے والے سالوں کی تعداد کے مطابق، {اور} اس کے پھلوں کے سالوں کی تعداد کے مطابق جو وہ آپ کو بیچے گا:\n16۔ سالوں کی تعداد کے مطابق تم اس کی قیمت بڑھاؤ گے، اور چند سالوں کے حساب سے تم اس کی قیمت کم کرو گے: کیونکہ {سالوں کے} کے حساب سے وہ تمہیں بیچتا ہے۔\n17۔ لہٰذا تم ایک دوسرے پر ظلم نہیں کرو گے؛ لیکن تم اپنے خدا سے ڈرو: کیونکہ میں تمہارا خداوند خدا ہوں۔\n18۔ اسی لیے تم میرے قوانین پر عمل کرو گے، میرے فیصلے رکھو گے، اور عمل کرو گے؛ اور تم زمین میں محفوظ رہو گے۔\n19۔ اور زمین اپنا پھل دے گی، اور تم اپنی پوری خوراک کھاؤ گے، اور اس میں محفوظ رہو گے۔\n20۔ اور اگر تم پوچھو، ساتویں سال ہم کیا کھائیں گے؟ دیکھو، ہم نہ تو بوئیں گے، نہ اپنی افزائش میں جمع ہوں گے:\n21۔ پھر میں چھٹے سال میں تم پر اپنی برکت کا حکم دوں گا، اور یہ تین سال تک پھل دے گی۔\n22۔ اور تم آٹھویں سال بوؤ گے، اور نویں سال تک پرانے پھل کھاؤ گے؛ جب تک اس کے پھل نہیں آتے، تم پرانے {دکان} سے کھاؤ گے۔\n23۔ زمین ہمیشہ کے لیے فروخت نہیں کی جائے گی: کیونکہ زمین {ہے} میری؛ کیونکہ تم میرے ساتھ اجنبی اور مسافر ہو۔ {ہمیشہ کے لیے: یا، بالکل کٹ جائے: عبرانی۔ کاٹنے کے لیے}\n24۔ اور اپنی ملکیت کی تمام زمین میں تم اس زمین کی کفارہ عطا کرو گے۔\n25۔ اگر تمہارا بھائی غریب ہو اور اپنی جائیداد کا کچھ حصہ بیچ دے، اور اگر اس کے رشتہ داروں میں سے کوئی اسے واپس لینے آئے، تو وہ وہ چیز واپس کرے گا جو اس کے بھائی نے بیچی ہے۔\n26۔ اور اگر اس آدمی کے پاس اسے نجات دینے والا کوئی نہ ہو، اور وہ خود اسے نجات دے سکے؛ {خود...: عبرانی۔ اس کا ہاتھ پہنچ گیا ہے اور کافی پایا ہے}\n27۔ پھر وہ اس کی فروخت کے سال گنتا ہے، اور اضافی رقم اس شخص کو واپس کر دیتا ہے جسے اس نے بیچا ہے؛ تاکہ وہ اپنے قبضے میں واپس آ سکے۔\n28۔ لیکن اگر وہ اسے واپس نہ دے سکے، تو جو کچھ بیچا جائے گا وہ اس کے ہاتھ میں رہے گا جس نے اسے جوبل کے سال تک خریدا ہے: اور جوبل میں وہ ختم ہو جائے گا، اور وہ اپنی ملکیت میں واپس چلا جائے گا۔\n29۔ اور اگر کوئی شخص کسی فصیل والے شہر میں رہائش گاہ بیچے، تو وہ اسے فروخت ہونے کے ایک سال کے اندر واپس کر سکتا ہے؛ {ایک پورے سال کے اندر} وہ اسے نجات دے۔\n30۔ اور اگر وہ پورے سال کے اندر نجات نہ دی جائے، تو جو گھر دیواروں والے شہر میں ہے، وہ ہمیشہ کے لیے اس کے لیے قائم کیا جائے گا جس نے اسے اپنی نسلوں تک خریدا: یہ جشن میں ختم نہیں ہوگا۔\n31۔ لیکن ان دیہاتوں کے گھر جن کے گرد دیوار نہیں ہے، انہیں دیہات کے کھیتوں میں شمار کیا جائے گا: انہیں نجات دی جا سکتی ہے، اور وہ یوبیل میں باہر جائیں گے۔ {وہ شاید...: عبرانی۔ نجات اس کی ملکیت ہے}\n32. لاویوں کے شہروں کے باوجود، {اور} ان کے ملکیتی شہروں کے گھروں کے باوجود، لاویوں کو کسی بھی وقت نجات مل سکتی ہے۔\n33۔ اور اگر کوئی شخص لاویوں سے خرید لے، تو جو گھر بیچا گیا اور اس کی ملکیت کا شہر یوبیل کے سال میں ختم ہو جائے گا: کیونکہ لاویوں کے شہروں کے گھر ان کی ملکیت بنی اسرائیل میں ہیں۔ {ایک آدمی...: یا، لاویوں میں سے کوئی انہیں نجات دے}\n34۔ لیکن ان کے شہروں کے مضافات کا کھیت فروخت نہیں کیا جا سکتا؛ کیونکہ یہ ان کی دائمی ملکیت ہے۔\n35۔ اور اگر تمہارا بھائی غریب ہو اور تمہارے ساتھ زوال پذیر ہو جائے؛ پھر تم اسے آزاد کرو گے: {ہاں، چاہے وہ اجنبی ہو، یا کوئی مسافر ہو؛ تاکہ وہ تمہارے ساتھ رہ سکے۔ {گرے ہوئے...: عبرانی۔ اس کا ہاتھ ناکام ہو جاتا ہے} {ریلیف: عبرانی مضبوط کریں}\n36۔ اس سے سود نہ لو، نہ بڑھو، بلکہ اپنے خدا سے ڈرو؛ تاکہ تمہارا بھائی تمہارے ساتھ رہے۔\n37۔ تم اسے سود پر اپنا پیسہ نہیں دینا، نہ ہی اسے اپنی خوراک کے لیے قرض دینا۔\n38. میں خداوند تمہارا خدا ہوں، جس نے تمہیں مصر کی سرزمین سے نکالا، تاکہ تمہیں کنعان کی سرزمین دوں، اور تمہارا خدا بنوں۔\n39۔ اور اگر تمہارا بھائی {جو تمہارے ساتھ رہتا ہے} غریب ہو جائے اور تمہیں بیچ دیا جائے؛ تم اسے غلام کے طور پر کام کرنے پر مجبور نہ کرو: {مجبور...: عبرانی اپنی خدمت اس کے ساتھ خدمت کرو وغیرہ}\n40۔ {لیکن} ایک کرائے کے خادم کی طرح، {اور} ایک مسافر کے طور پر، وہ تمہارے ساتھ ہوگا، {اور} سال جوبل تک تمہاری خدمت کرے گا:\n41۔ اور {پھر} وہ تم سے جدا ہو جائے گا، {دونوں} وہ اور اس کے بچے اس کے ساتھ، اور اپنے خاندان کے پاس واپس جائے گا، اور اپنے باپ دادا کی ملکیت میں واپس جائے گا۔\n42. کیونکہ وہ میرے خادم ہیں، جنہیں میں نے مصر کی سرزمین سے نکالا ہے: انہیں غلام کے طور پر فروخت نہیں کیا جائے گا۔ {یعنی...: عبرانی ایک بانڈ مین کی فروخت کے ساتھ}\n43. تم اس پر سختی سے حکومت نہ کرو؛ لیکن اپنے خدا سے ڈرو۔\n44۔ تمہارے غلام اور تمہاری خادمائیں جو تمہارے پاس ہوں گی، وہ تمہارے ارد گرد موجود کافروں میں سے ہوں گی؛ ان میں سے تم غلام اور غلام خریدو گے۔\n45۔ مزید برآں، آپ ان اجنبیوں کے بچوں کو خریدیں گے جو آپ کے درمیان رہتے ہیں، اور ان کے خاندانوں کے جو آپ کے ساتھ ہیں، جو انہوں نے آپ کی زمین میں پیدا کیے، اور وہ آپ کی ملکیت ہوں گے۔\n46۔ اور آپ انہیں اپنے بچوں کے لیے وراثت کے طور پر لیں گے، تاکہ وہ انہیں ملکیت کے بدلے وراثت میں حاصل کریں؛ وہ ہمیشہ کے لیے تمہارے غلام رہیں گے: لیکن اپنے بھائیوں پر بنی اسرائیل، تم ایک دوسرے پر سختی سے حکمرانی نہیں کرو گے۔ {وہ...: عبرانی۔ تم ان کے ساتھ اپنی خدمت کرو گے}\n47. اور اگر کوئی مسافر یا اجنبی تمہارے ساتھ امیر ہو جائے، اور تمہارا بھائی {جو اس کے ساتھ رہتا ہے} غریب ہو جائے، اور خود کو اجنبی کو بیچ دے {یا} تمہارے قریب سفر کرنے والے کو، یا اجنبی کے خاندان کے خاندان کے لوگوں کو: {امیر ہو...: عبرانی۔ اس کا ہاتھ حاصل کرنا، وغیرہ}\n48۔ اس کے بعد جب وہ فروخت ہو جائے تو اسے دوبارہ نجات دی جا سکتی ہے؛ اس کے بھائیوں میں سے کوئی اسے نجات دے سکتا ہے:\n49۔ یا تو اس کا چچا یا اس کے چچا کا بیٹا اسے نجات دے سکتا ہے، یا اس کے خاندان کے کوئی قریبی رشتہ دار اسے نجات دے سکتا ہے؛ یا اگر ممکن ہو تو وہ خود کو سدھارنے کی کوشش کر سکتا ہے۔\n50۔ اور وہ اس شخص کا حساب کرے گا جس نے اسے خریدا تھا اس سال سے لے کر جوبل کے سال تک: اور اس کی فروخت کی قیمت اس سال کے حساب سے ہوگی جو ایک کرائے کے خادم کے وقت کے مطابق ہوگی۔\n51۔ اگر {ابھی بہت سال پیچھے ہیں}، تو ان کے مطابق وہ اپنی نجات کی قیمت اس رقم سے واپس دے گا جس کے لیے اسے خریدا گیا تھا۔\n52۔ اور اگر یوبیل کے سال تک چند سال باقی ہیں، تو وہ اس کے ساتھ گنتا ہے، {اور} اپنی عمر کے مطابق اسے اپنی نجات کی قیمت دوبارہ دے گا۔\n53۔ {اور} سالانہ مزدور کی طرح وہ اس کے ساتھ ہوگا: {اور دوسرا} اس پر سختی سے حکومت نہیں کرے گا تمہاری نظر میں۔\n54۔ اور اگر وہ ان سالوں میں نجات نہ پائے، تو وہ جوبیل کے سال میں باہر جائے گا، {دونوں} وہ اور اس کے بچے اس کے ساتھ۔ {ان میں...: یا، ان طریقوں سے}\n55۔ کیونکہ میرے لیے بنی اسرائیل خادم ہیں؛ وہ میرے بندے ہیں جنہیں میں نے مصر کی سرزمین سے نکالا: میں خداوند تمہارا خدا ہوں۔","1۔ تم نہ اپنے لیے بت بنا سکتے ہو اور نہ ہی کوئی مجسمہ بنا سکتے ہو، نہ ہی اپنی زمین پر کوئی پتھر کی تصویر قائم کرو گے تاکہ اس کے سامنے سجدہ کرو: کیونکہ میں خداوند تمہارا خدا ہوں۔ {کھڑے ہو کر...: یا، ستون} {تصویر کا...: یا، مجسمہ شدہ پتھر: عبرانی۔ تصویر کا پتھر}\n2. تم میرے سبت رکھو گے، اور میرا مقدس مقام احترام کرو گے: میں خداوند ہوں۔\n3۔ اگر تم میرے احکامات میں چلتے ہو، میرے احکامات کی پاسداری کرو اور ان پر عمل کرو؛\n4۔ پھر میں تمہیں مناسب وقت پر بارش دوں گا، زمین اپنی پیداوار دے گی، اور کھیت کے درخت اپنا پھل دیں گے۔\n5۔ اور تمہاری تھریشنگ شراب تک پہنچے گی، اور شکار بونے کے وقت تک: اور تم اپنی روٹی پوری طرح کھاؤ گے، اور اپنی زمین میں محفوظ رہو گے۔\n6۔ اور میں زمین میں امن دوں گا، اور تم لیٹ جاؤ گے، اور کوئی تمہیں خوفزدہ نہیں کرے گا: اور میں زمین سے برے جانوروں کو ختم کروں گا، نہ ہی تلوار تمہاری زمین میں جائے گی۔ {رڈ: ہیب۔ رکنے کی وجہ}\n7۔ اور تم اپنے دشمنوں کا پیچھا کرو گے، اور وہ تمہارے سامنے تلوار کے ہاتھوں گریں گے۔\n8۔ اور تم میں سے پانچ سو کا پیچھا کریں گے، اور سو تم میں سے دس ہزار کو بھگا دیں گے، اور تمہارے دشمن تلوار کے ہاتھوں تمہارے سامنے گریں گے۔\n9۔ کیونکہ میں تمہاری عزت کروں گا، تمہیں پھلدار کروں گا، تمہیں بڑھاؤں گا، اور تمہارے ساتھ اپنا عہد قائم کروں گا۔\n10۔ اور تم پرانے دکان کو کھاؤ گے، اور پرانے کو نئے کے لیے نکالو گے۔\n11۔ اور میں تمہارے درمیان اپنا خیمہ قائم کروں گا: اور میری جان تم سے نفرت نہیں کرے گی۔\n12۔ اور میں تمہارے درمیان چلوں گا، اور تمہارا خدا بنوں گا، اور تم میرے لوگ بنو گے۔\n13. میں خداوند تمہارا خدا ہوں، جس نے تمہیں مصر کی سرزمین سے نکالا، تاکہ تم ان کے غلام نہ بنو؛ اور میں نے تمہارے جولے کی پٹیاں توڑ دی ہیں، اور تمہیں سیدھا کھڑا کر دیا ہے۔\n14۔ لیکن اگر تم میری بات نہیں سنو گے، اور یہ تمام احکامات نہیں مانو گے؛\n15۔ اور اگر تم میرے قوانین سے نفرت کرو گے، یا اگر تمہاری روح میرے فیصلوں سے نفرت کرے، تاکہ تم میرے تمام احکامات نہ مانو، {سوائے }کہ میرا عہد توڑو:\n16. میں بھی یہ تمہارے ساتھ کروں گا؛ میں تم پر دہشت، تپ دہہ اور جلتا ہوا عذاب بھی مقرر کروں گا، جو آنکھوں کو کھا جائے گا اور دل میں غم ڈالے گا: اور تم اپنا بیج بیکار بوؤ گے، کیونکہ تمہارے دشمن اسے کھا جائیں گے۔ {اوور: عبرانی۔ upon}\n17۔ اور میں تمہارے خلاف اپنا چہرہ رکھوں گا، اور تم اپنے دشمنوں کے سامنے مارے جاؤ گے: جو تم سے نفرت کرتے ہیں وہ تم پر حکومت کریں گے؛ اور تم بھاگو گے جب کوئی تمہارا پیچھا نہیں کرے گا۔\n18۔ اور اگر تم ابھی تک اس سب کے باوجود میری بات نہیں سنتے، تو میں تمہیں تمہارے گناہوں کی سزا سات گنا زیادہ دوں گا۔\n19۔ اور میں تمہاری طاقت کے غرور کو توڑ دوں گا؛ اور میں تمہارا آسمان لوہا اور تمہاری زمین کو پیتل کی طرح بناؤں گا:\n20۔ اور تمہاری طاقت ضائع ہو جائے گی: کیونکہ تمہاری زمین اپنی پیداوار نہیں دے گی، نہ ہی زمین کے درخت پھل دیں گے۔\n21۔ اور اگر تم میرے خلاف چلو اور میری بات نہ سنو؛ میں تمہارے گناہوں کے مطابق تم پر سات گنا زیادہ آفتیں لاؤں گا۔ {برعکس...: یا، میرے ساتھ ہر قسم کی مہمات}\n22۔ میں آپ کے درمیان جنگلی جانور بھی بھیجوں گا، جو آپ کے بچوں کو چھین لیں گے، آپ کے مویشی تباہ کریں گے، اور آپ کی تعداد کم کر دیں گے؛ اور تمہاری {بلندی} کی راہیں ویران ہو جائیں گی۔\n23۔ اور اگر تم میرے ذریعے ان چیزوں سے اصلاح نہیں بننا چاہتے، بلکہ میرے خلاف چلو گے؛\n24۔ پھر میں بھی تمہارے خلاف چلوں گا، اور تمہیں سات بار تمہارے گناہوں کی سزا دوں گا۔\n25۔ اور میں تم پر ایک تلوار لاؤں گا، جو {میرے} عہد کے جھگڑے کا بدلہ لے گی: اور جب تم اپنے شہروں میں جمع ہو جاؤ گے، تو میں تمہارے درمیان وبا بھیجوں گا؛ اور تم دشمن کے ہاتھ میں دیے جاؤ گے۔\n26۔ {اور} جب میں تمہاری روٹی کی چھڑی توڑ دوں گا، دس عورتیں تمہاری روٹی ایک تندور میں پکاتی ہوں گی، اور وہ تمہیں وزن کے حساب سے دوبارہ روٹی دیں گی: اور تم کھاؤ گے، اور مطمئن نہیں ہوں گے۔\n27۔ اور اگر تم اس سب کے لیے میری بات نہیں سننا چاہتے، بلکہ میرے خلاف چلتے رہو؛\n28۔ پھر میں بھی غصے میں تمہارے خلاف چلا جاؤں گا؛ اور میں، حتیٰ کہ میں بھی، تمہیں تمہارے گناہوں پر سات بار سزا دوں گا۔\n29۔ اور تم اپنے بیٹوں کا گوشت کھاؤ گے، اور اپنی بیٹیوں کا گوشت کھاؤ گے۔\n30۔ اور میں تمہارے اونچے مقامات تباہ کر دوں گا، تمہاری مجسمے کاٹ دوں گا، اور تمہارے بتوں کی لاشوں پر تمہاری لاشیں ڈال دوں گا، اور میری روح تم سے نفرت کرے گی۔\n31۔ اور میں تمہارے شہروں کو ویران کر دوں گا، اور تمہارے مقدس مقامات کو ویران کر دوں گا، اور میں تمہاری میٹھی خوشبوؤں کی خوشبو نہیں سونگھوں گا۔\n32۔ اور میں زمین کو ویران کر دوں گا: اور تمہارے دشمن جو وہاں رہتے ہیں اس پر حیران رہ جائیں گے۔\n33۔ اور میں تمہیں کافروں میں بکھیر دوں گا، اور تمہارے پیچھے تلوار نکالوں گا، اور تمہاری زمین ویران ہو جائے گی، اور تمہارے شہر ویران ہو جائیں گے۔\n34۔ پھر زمین اپنی سبت سے لطف اندوز ہو گی، جب تک وہ ویران ہے، اور تم اپنے دشمنوں کی زمین میں رہو؛ {حتیٰ کہ} تب زمین آرام کرے گی، اور اپنی سبت سے لطف اندوز ہوگی۔\n35۔ جب تک یہ ویران ہے، وہ آرام کرے گا؛ کیونکہ وہ تمہارے سبت میں آرام نہیں کرتا تھا، جب تم اس پر رہتے۔\n36۔ اور جو لوگ تم میں سے زندہ رہ گئے ہیں ان پر میں ان کے دشمنوں کی زمینوں میں ان کے دلوں میں بے ہوشی بھیجوں گا؛ اور ہلتے ہوئے پتے کی آواز ان کا پیچھا کرے گی؛ اور وہ بھاگ جائیں گے، جیسے تلوار سے بھاگ رہے ہوں؛ اور جب کوئی پیچھا نہ کرے تو وہ گر جائیں گے۔ {ہلایا ہوا: عبرانی۔ ڈرائیون}\n37۔ اور وہ ایک دوسرے پر گریں گے، جیسے تلوار کے سامنے، جب کوئی پیچھا نہ کرے گا: اور تم اپنے دشمنوں کے سامنے کھڑے ہونے کی طاقت نہیں رکھو گے۔\n38۔ اور تم کافروں میں ہلاک ہو جاؤ گے، اور تمہارے دشمنوں کی زمین تمہیں کھا جائے گی۔\n39۔ اور جو تم میں سے بچ جائیں گے وہ تمہارے دشمنوں کی زمینوں میں اپنی بدکاری میں تڑپیں گے؛ اور اپنے باپ دادا کی گناہوں پر بھی وہ ان کے ساتھ تڑپیں گے۔\n40۔ اگر وہ اپنے گناہوں کا اعتراف کریں، اور اپنے باپوں کی گناہوں کا اعتراف کریں، جو انہوں نے میرے خلاف کیا، اور یہ بھی کہ وہ میرے خلاف چلے ہیں؛\n41۔ اور {یہ} کہ میں بھی ان کے خلاف چلا ہوں، اور انہیں ان کے دشمنوں کی سرزمین میں لے آیا ہوں؛ اگر پھر ان کے غیر ختنہ شدہ دل عاجز ہو جائیں، اور پھر وہ اپنے گناہوں کی سزا قبول کریں:\n42۔ پھر میں یعقوب کے ساتھ اپنا عہد یاد رکھوں گا، اسحاق کے ساتھ میرا وعدہ، اور ابراہیم کے ساتھ اپنا عہد بھی یاد رکھوں گا؛ اور میں اس زمین کو یاد رکھوں گا۔\n43۔ زمین بھی ان سے بچ جائے گی، اور اس کے سبت سے لطف اندوز ہوں گی، جبکہ وہ ان کے بغیر ویران پڑے گی: اور وہ اپنی گناہوں کی سزا قبول کریں گے: کیونکہ وہ میرے فیصلوں سے نفرت کرتے تھے، اور کیونکہ ان کی روح میرے قوانین سے نفرت کرتی تھی۔\n44۔ اور پھر بھی، جب وہ اپنے دشمنوں کی سرزمین میں ہوں گے، تو میں انہیں دور نہیں کروں گا، نہ ہی ان سے نفرت کروں گا، انہیں مکمل طور پر تباہ نہیں کروں گا، اور ان سے اپنا عہد توڑوں گا: کیونکہ میں خداوند ان کا خدا ہوں۔\n45۔ لیکن میں ان کی خاطر ان کے آباواجداد کے عہد کو یاد رکھوں گا، جنہیں میں نے مصر کی سرزمین سے کافروں کے سامنے نکالا، تاکہ میں ان کا خدا بن سکوں: میں خداوند ہوں۔\n46۔ یہ وہ قوانین، فیصلے اور قوانین ہیں جو خداوند نے موسیٰ کے ہاتھوں کوہ سینا میں اپنے اور بنی اسرائیل کے درمیان بنائے۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل سے بات کرو، اور ان سے کہو، جب کوئی شخص ایک عہد کرے گا، تو وہ لوگ تمہاری نظر سے خداوند کے لیے ہوں گے۔\n3۔ اور آپ کا اندازہ مرد کی عمر بیس سال سے ساٹھ سال تک ہوگا، اور آپ کا اندازہ مقدس مقام کے شیکل کے بعد پچاس شیکل چاندی ہوگا۔\n4۔ اور اگر وہ عورت ہو، تو تمہاری قیمت تیس شیکل ہوگی۔\n5۔ اور اگر وہ پانچ سال کی عمر سے لے کر بیس سال کی عمر تک ہو، تو تمہارا تخمینہ مرد کے بیس شیکل اور مادہ کے لیے دس شیکل ہوگا۔\n6۔ اور اگر یہ ایک ماہ کی عمر سے پانچ سال تک ہو، تو تمہارا اندازہ مرد کے پانچ شیکل چاندی کے ہوگا، اور مادہ کے لیے تین شیکل چاندی ہوگی۔\n7۔ اور اگر وہ ساٹھ سال اور اس سے زیادہ عمر کا ہو؛ اگر وہ مرد ہے، تو تمہاری قیمت پندرہ شیکل ہوگی، اور عورت کے لیے دس شیکل۔\n8۔ لیکن اگر وہ تمہاری قیمت سے زیادہ غریب ہو، تو وہ پادری کے سامنے پیش ہوگا، اور پادری اس کی قدر کرے گا؛ اپنی صلاحیت کے مطابق جو عہد کیا گیا ہے، پادری اس کی قدر کرے گا۔\n9۔ اور اگر وہ کوئی جانور ہو، جس سے لوگ خداوند کے لیے قربانی پیش کریں، تو جو کچھ بھی {کوئی انسان} ان میں سے خداوند کو دیتا ہے، وہ سب مقدس ہوگا۔\n10۔ وہ اسے تبدیل نہیں کرے گا، نہ ہی اسے بدلے گا، اچھائی کو برائی سے بدلے گا، اور اگر وہ جانور کے بدلے جانور کو تبدیل کرے گا، تو وہ اور اس کا تبادلہ مقدس ہوگا۔\n11۔ اور اگر کوئی ناپاک جانور ہو جس کی قربانی خداوند کو نہ دی جائے، تو وہ درندے کو پادری کے سامنے پیش کرے گا:\n12۔ اور پادری اس کی قدر کرے گا، چاہے وہ اچھا ہو یا برا: جیسے تم اسے اہمیت دیتے ہو، {جو پادری ہے}، ویسا ہی ہوگا۔ {یعنی...: عبرانی تیری رائے کے مطابق، اے پادری، وغیرہ}\n13۔ لیکن اگر وہ اسے کسی حد تک بھی چھٹائے گا، تو وہ اس کا پانچواں حصہ آپ کی قیمت میں شامل کرے گا۔\n14۔ اور جب کوئی آدمی اپنے گھر کو خداوند کے لیے مقدس قرار دے گا، تو پادری اس کا اندازہ لگائے گا، چاہے وہ اچھا ہو یا برا: جیسے پادری اس کا اندازہ لگائے گا، ویسے ہی وہ قائم رہے گا۔\n15۔ اور اگر جو اسے مقدس کرے گا وہ اپنے گھر کو نجات دے گا، تو وہ تمہارے اندازے کی رقم کا پانچواں حصہ اس میں شامل کرے گا، اور وہ اس کا ہوگا۔\n16۔ اور اگر کوئی شخص اپنے کھیت کے کسی کھیت کا کچھ حصہ خداوند کے سامنے مقدس کرے تو تمہارا اندازہ اس کے بیج کے مطابق ہوگا: جو کے بیج کا ہومر {اس کی قیمت پچاس شیکل چاندی کے برابر ہو جائے گا}۔ {an...: یا، ہومر کی سرزمین، وغیرہ}\n17۔ اگر وہ جوبل کے سال سے اپنے کھیت کو مقدس کرے، تو آپ کے اندازے کے مطابق وہ قائم رہے گا۔\n18۔ لیکن اگر وہ جوبل کے بعد اپنے کھیت کو مقدس کرے، تو پادری اس کے حساب سے باقی رہ جانے والے سالوں کے حساب سے، حتیٰ کہ یوبیل کے سال تک، اور یہ رقم تمہارے اندازے سے منہا ہو جائے گی۔\n19۔ اور اگر جس نے کھیت کو مقدس کیا ہے وہ کسی بھی طرح اسے نجات دے، تو وہ تمہاری قدر کے پیسے کا پانچواں حصہ اس میں شامل کرے گا، اور یہ اس کے لیے یقینی ہو جائے گا۔\n20۔ اور اگر وہ کھیت کو نجات نہیں دے گا، یا اگر اس نے کھیت کسی اور کو بیچ دیا ہے، تو وہ دوبارہ نہیں ملے گا۔\n21۔ لیکن میدان جب جوبل میں جائے گا، تو خداوند کے لیے مقدس ہوگا، جیسے وقف شدہ میدان؛ اس کی ملکیت پادری کی ہوگی۔\n22۔ اور اگر {انسان} وہ کھیت خدا کے لیے مقدس کرے جو اس نے خریدا ہو، جو {ہے} اس کے کھیتوں میں سے نہیں؛\n23۔ پھر پادری اس کے سامنے تمہاری قدر کا حساب لگائے گا، {حتی} جوبل کے سال تک: اور وہ اس دن تمہاری قدر کرے گا، {بطور} خداوند کے لیے ایک مقدس چیز کے طور پر۔\n24۔ جوبیل کے سال میں کھیت اس کے پاس واپس آئے گا جس سے یہ خریدا گیا تھا، {حتیٰ کہ} اس کے پاس بھی جس کی زمین کی ملکیت {تھی}۔\n25۔ اور تمہارے تمام اندازے مقدس مقام کے شیکل کے مطابق ہوں گے: بیس گرہ شیکل ہوں گے۔\n26۔ صرف جانوروں میں سے پہلا اولاد، جو خداوند کا پہلا ہونا چاہیے، کوئی انسان اسے پاک نہیں کرے گا؛ چاہے وہ بیل ہو یا بھیڑ: یہ خداوند کا ہے۔ {سب سے پہلے: عبرانی۔ فرسٹ بورن وغیرہ}\n27۔ اور اگر وہ کسی ناپاک جانور کا ہو، تو وہ آپ کے اندازے کے مطابق اسے نجات دے گا، اور اس میں پانچواں حصہ شامل کرے گا: یا اگر وہ نجات نہ دی جائے تو آپ کے اندازے کے مطابق فروخت ہو جائے گا۔\n28. اگرچہ کوئی وقف شدہ چیز نہ ہو، جو انسان خداوند کے لیے وقف کرے جو اس کے پاس ہے، {انسانی} اور جانور دونوں، اور اپنی ملکیت کے میدان سے، بیچی جائے گی یا نجات دی جائے گی: ہر وقف شدہ چیز خداوند کے لیے سب سے مقدس ہے۔\n29۔ کوئی بھی وفادار، جو انسانوں کے لیے وقف ہو، نجات نہیں پائے گا؛ {لیکن} یقینا موت کی سزا دی جائے گی۔\n30۔ اور زمین کی ساری عشر، {چاہے} زمین کے بیج کی ہو، {یا} درخت کے پھل کی، {ہے} خداوند کا: {یہ} خداوند کے لیے مقدس ہے۔\n31۔ اور اگر کوئی شخص اپنی عشر میں سے {چاہیے} حاصل کرنا چاہے تو اس میں پانچواں حصہ شامل کرے گا۔\n32۔ اور ریوڑ یا ریوڑ کی عشر کے بارے میں، جو بھی چھڑی کے نیچے سے گزرتا ہے، دسواں حصہ خداوند کے لیے مقدس ہوگا۔\n33۔ وہ یہ نہیں دیکھے گا کہ یہ اچھا ہے یا برا، نہ ہی اسے بدلے گا: اور اگر وہ اسے تبدیل کرے تو وہ اور اس کی تبدیلی دونوں مقدس ہوں گی؛ یہ نجات نہیں پا سکے گا۔\n34۔ یہ وہ احکامات ہیں جو خداوند نے موسیٰ کو بنی اسرائیل کے لیے کوہ سینا میں حکم دیے تھے۔"];
